    [185] = "奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只荆棘谷猛虎幼崽。",
    [186] = "奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只荆棘谷猛虎。",
    [187] = "奈辛瓦里远征队的艾耶克·罗欧克要求你杀死10只老年荆棘谷猛虎。",
    [188] = "奈辛瓦里远征队的艾耶克·罗欧克要求你杀死辛达尔并带回它的爪子。",
