    [190] = "奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只猎豹幼崽。",
    [191] = "奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只黑豹。",
    [192] = "奈辛瓦里远征队的埃尔加丁爵士要求你杀死10只深喉猎豹。",
    [193] = "奈辛瓦里远征队的埃尔加丁爵士要求你杀死巴尔瑟拉，并带回它的牙。",
    [194] = "赫米特·奈辛瓦里要求你杀死10只荆棘谷迅猛龙。",
    [195] = "赫米特·奈辛瓦里要求你杀死10只鞭尾迅猛龙。",
    [196] = "赫米特·奈辛瓦里要求你杀死10只丛林捕猎者。",
    [197] = "赫米特·奈辛瓦里要求你杀死荆棘谷中最危险最狡猾的迅猛龙泰希斯。",
    [198] = "将杂七杂八的地精补给物资带给列兵索尔森。",
    [199] = "回去见主工程师辛德维尔七世，把你找到的线索交给他。",
    [200] = "找到书呆子赫罗德的档案。",
    [201] = "找到猎人营地并向藏宝海湾的克拉兹克报告这个营地的位置。",
    [202] = "杀掉6名库尔森精英和4名库尔森副首领，并将库尔森的头颅交给反抗军营地里的多伦上尉。",
    [203] = "杀死15名库尔森丛林战士，然后向反抗军营地的尤瓦中士复命。",
    [204] = "给反抗军营地里的尤瓦中士带回7份密林药剂和1份毒草汁液。",
    [205] = "给叛军营地的尼麦兹修士带回4只劈颅巨魔的神像。",
    [206] = "将心灵之眼交给反抗军营地里的尼麦兹修士。",
    [207] = "找到4块石板并将上面的内容带回去交给尼麦兹修士。",
    [208] = "赫米特·奈辛瓦里要求你将虎王邦加拉什的头带回来给他。",
    [209] = "给藏宝海湾的科博克带回18根劈颅巨魔的獠牙。",
    [210] = "把克拉兹克的烹调锅带给藏宝海湾的地精克拉兹克。",
    [211] = "把阿拉基的护符匣碎片交给西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特。",
    [212] = "杀死一只冷眼蜥蜴，取一块冷蜥蜴肉并把它带给“蓝色隐士”旅店里的安古斯·斯特恩。 <如果你在任务过程中死亡则任务失败>",
    [213] = "给藏宝海湾的科博克带回8块打磨过的水晶。",
    [214] = "给哨兵岭哨塔的哨兵瑞尔带回10条红色丝质面罩。",
    [215] = "与反抗军营地里的多伦上尉谈一谈。",
    [216] = "杀死12个蓟皮复仇者和12个蓟皮萨满祭司。他们大部分都位于佐拉姆海岸东部的蓟皮村里。任务完成后回到灰谷佐拉姆加前哨站的卡拉恩·阿玛卡那里复命。",
    [217] = "杀掉穴居人首领格劳姆格及他的两个护卫，纳什尔和布劳勒尔。然后回到南部警戒塔向拉格弗斯上尉报告。",
    [218] = "格瑞林·白须要你去杀掉冷酷的格瑞克尼尔，并取回他的日记。",
    [219] = "保护基沙恩下士回到赤脊。",
    [220] = "把最纯净的水交给贫瘠之地的伊斯伦。",
    [221] = "为夜色镇的卡洛尔杀掉12个夜行黑暗狼人。",
    [222] = "为夜色镇的卡洛尔杀掉8个夜行邪齿狼人和8个夜行堕落狼人。",
    [223] = "把卡洛尔的便笺交给乔纳森·卡尔文。",
    [224] = "南部警戒塔的巡山人库伯弗林特要你杀掉10个碎石穴居人和10个碎石怪斥候。",
    [225] = "去和夜色镇的希拉·沃宁迪谈一谈。",
    [226] = "杀掉12只饥饿的恐狼和8只疯狂的恐狼，然后到斯温的营地中向拉尔斯交差。",
    [227] = "去和夜色镇的指挥官阿尔泰娅·埃伯洛克谈一谈。",
    [228] = "杀掉摩拉迪姆，把他的头骨交给夜色镇的指挥官阿尔泰娅·埃伯洛克。",
    [229] = "去和夜色镇的守夜人莎拉·拉迪莫尔谈一谈。",
    [230] = "把你从斯温的农场找到的书交给他。",
    [231] = "把莎拉·拉迪莫尔的戒指拿到摩根·拉迪莫尔的坟墓上去。",
    [232] = "把订货单交给幽暗城的奥雷萨多·卢卡。",
    [233] = "把这一摞信件送给塔林·锐眼。",
    [234] = "把这封信送给格瑞林·白须。",
    [235] = "与灰谷碎木哨岗的塞娜尼·雷心谈一谈。",
    [237] = "南部警戒塔的巡山人格拉维戈要你杀掉10个碎石怪击颅者和10个碎石怪先知，然后回去向他汇报。",
    [238] = "把采样工具包交给幽暗城的药剂师金格。",
    [239] = "到西泉要塞去和瑞尼尔副队长谈一谈。",
    [240] = "把黑蟹蛋糕拿回去交给基特斯。",
    [243] = "和加基森的首席工程师沙克斯·比格维兹谈一谈，请他为实验工具包提供能量源。",
    [244] = "找到菲尔顿副队长。",
    [245] = "守夜人道茨要你杀15只小型结网毒蜘蛛。",
    [246] = "杀死10个混血赤脊山豺狼人和6个赤脊山偷猎者，然后向湖畔镇的菲尔顿副队长复命。",
    [248] = "爬上石堡要塞一旁的哨塔。 为阿祖拉的铭文饰品找一个合适的容器。",
    [249] = "击败莫甘斯。 将他的阴影坠饰带给塞欧克瑞图斯，他就在艾尔文森林内的阿祖拉之塔中。",
    [250] = "查看水坝东边斜坡附近的区域，调查一下黑铁矮人准备做什么，然后把线索带给主工程师辛德维尔七世．",
    [251] = "把写给艾尔罗的信拿给希拉·沃宁迪。",
    [252] = "把翻好的信带给艾尔罗·埃伯洛克公爵。",
    [253] = "找到伊莉莎的坟墓，从她的身上取回藏尸者的心脏，把它交给艾尔罗·埃伯洛克。",
    [255] = "塞尔萨玛的镇长埃罗恩·钝鼻雇你去杀掉4个莫格罗什食人魔、4个莫格罗什蛮兵和4个莫格罗什执行者。",
    [256] = "杀了卓克苏尔，把他的头颅带给塞尔萨玛的镇长埃罗恩·钝鼻。",
    [257] = "杀死6只山鹫，然后回到旅行者营地见年轻的达瑞尔，时限为15分钟。",
    [258] = "杀掉5只老山猪，然后回到旅行者营地去见年轻的达瑞尔，时限为12分钟。",
    [261] = "杀掉30个亡灵劫掠者，然后向尼耶尔前哨站的安东修士复命。",
    [262] = "带着你从斯温的农场找到的书，把它拿给夜色镇上的人看看。",
    [263] = "南部警戒塔的巡山人沃尔班要你杀掉10个碎石怪萨满祭司和10个碎石怪断骨者。",
    [264] = "把克拉莉斯的坠饰放在银松森林尤瑞夫的坟墓上。",
    [265] = "看看其他的镇民有没有关于模糊的人影的线索。",
    [266] = "到旅店去查一查关于模糊人影的线索。",
    [267] = "给南部警戒塔的拉格弗斯上尉带去8颗穴居人的石牙。",
    [268] = "把基特斯的日记交给斯温。",
    [269] = "把基特斯的日记交给暴风城的主教法席恩。",
    [270] = "到湿地的米奈希尔港去，找戈罗林·钢眉谈一谈。",
    [271] = "杀掉奥尔苏迪，把它的头颅带给旅行者营地里的达瑞尔。",
    [272] = "寻找水兽耐力坠饰和水兽敏捷坠饰。与月光林地的居民谈一谈，找出这些东西可能被放在哪里。 在雷姆洛斯神殿附近将海狮坠饰的两部分合而为一。 将合并好的坠饰交给月光林地永夜港中的德迪利特·星焰。",
    [273] = "和胡达尔谈一谈。",
    [274] = "阿什兰·暗石要你回去见主工程师辛德维尔七世，把有关这种炸药的新发现告诉他。",
    [275] = "杀死12只沼泽爬行者，然后向湿地的绿色守卫者雷希耶尔复命。",
    [276] = "杀死15名藓皮豺狼人和10名混血藓皮豺狼人，然后向湿地的绿色守卫者雷希耶尔复命。",
    [277] = "给绿色守卫者雷希耶尔带回9块粗制打火石。",
    [278] = "主工程师辛德维尔七世要你收集一份潜伏者的毒液，一块莫格罗什水晶和一滴鳄鱼的眼泪。",
    [279] = "杀掉12个蓝腮鱼人。 杀掉高布勒尔并砍下它的头。 将高布勒尔的头颅交给米奈希尔港的卡尔·波兰。",
    [280] = "主工程师辛德维尔七世要你游到水坝底部，找到装着炸药的木桶，然后把拆弹剂放进去，阻止将要发生的爆炸。",
    [281] = "搜索海边鱼人村落中的木箱和木桶。",
    [282] = "和巡山人萨鲁斯谈一谈。",
    [283] = "拆弹剂看来已经产生了效果。你可以回去向主工程师辛德维尔七世汇报这个好消息了。",
    [284] = "搜索米奈希尔雕塑。",
    [285] = "继续在鱼人村落中搜寻米奈希尔雕像的踪迹。",
    [286] = "将米奈希尔雕像还给卡尔·波兰。",
    [287] = "侦查霜鬃巨魔要塞，替卡拉诺斯的森内尔·白须杀掉5个霜鬃猎头者。",
    [288] = "为大副菲兹莫斯买一份壶装蜜酒。",
    [289] = "消灭13名被诅咒的水手、5名被诅咒的水兵和大副斯涅利格。把斯涅利格的鼻烟盒交给米奈希尔港的大副菲兹莫斯。",
    [290] = "从哈林多尔船长那里拿到无畏号的保险箱钥匙。 用钥匙打开无畏号上的保险箱。",
    [291] = "把森内尔的报告交给铁炉堡的参议员巴林·红石。",
    [292] = "把被诅咒的帕雷斯之眼交给戈罗林·钢眉。",
    [293] = "把被诅咒的帕雷斯之眼交给大主教本尼迪塔斯。他就在暴风城的光明大教堂里。",
    [294] = "维尔加挖掘场的奥莫尔·铁衣要求你杀死10只杂斑迅猛龙和10只杂斑尖啸龙。",
    [295] = "奥莫尔·铁衣要求你杀死10只杂斑镰爪龙和10只杂斑刺喉龙，然后返回维尔加挖掘场向他复命。",
    [296] = "维尔加挖掘场的奥莫尔·铁衣要求你杀死萨尔图斯，并在任务完成之后带着它的一只爪子向他复命。",
    [297] = "收集8个小石像，把它们交给麦格玛尔·落斧。",
    [298] = "把铁环挖掘场的进度报告带给塞尔萨玛的吉恩·角盔。",
    [299] = "勘察员维尔加要求你在挖掘场中搜索4块石板的碎片，它们是阿度斯碎片、莫德尔碎片、高尔姆碎片和奈尔鲁碎片。",
    [301] = "把铁环挖掘场的进度报告交给勘察员塔伯斯·雷矛。",
    [302] = "和塞尔萨玛的吉恩·角盔谈一谈。",
    [303] = "丹莫德的莫特雷·加玛森要求你消灭15名黑铁矮人、5名黑铁隧道工、5名黑铁破坏者和5名黑铁爆破手。",
    [304] = "杀死邪恶的巴尔加拉斯，把他的耳朵带给丹莫德外的布莱德·长须。",
    [305] = "塔雷尔·石纹要求你到挖掘场里去找到麦琳·石纹。",
    [306] = "把麦琳的信件交给塔雷尔·石纹复命。",
    [307] = "到银泉矿洞去收集4套矿工装备，然后向巡山人卡尔·雷矛复命。",
    [309] = "确保把米兰和货物送到挖掘场，然后通知勘察员基恩萨·铁环。",
    [310] = "到卡拉诺斯的雷酒酿造厂酒窖里去，把一桶雷霆啤酒换成热麦酒。",
    [311] = "把雷霆麦酒交给烈酒村的马莱斯·麦酒。",
    [312] = "从冰须的洞穴里拿回装有马克格拉恩的干肉的储藏柜。",
    [313] = "收集8束雪怪的鬃毛，把它们交给驾驶员迪恩·石轮。",
    [314] = "山羊农场的鲁德拉·冻石要你杀了瓦加什，并且把它的牙齿给她带回去。",
    [315] = "收集6束微光草，把它们交给烈酒村的雷杰德·麦酒。",
    [317] = "收集4大块野猪肉和2张厚熊皮，把它们交给钢架补给站的驾驶员贝隆·风箱。",
    [318] = "从烈酒村的雷杰德·麦酒那里弄到一桶艾沃沙酒。",
    [319] = "杀掉6头冰爪熊、8只老峭壁野猪和8只雪豹，然后回到烈酒村的雷杰德·麦酒那里。",
    [320] = "把这桶艾沃沙酒交给钢架补给站的驾驶员贝隆·风箱。",
    [321] = "搜索飞翔鱼鹰号的残骸。",
    [322] = "将这箱光铸铁锭交给格瑞曼德·艾尔默。",
    [323] = "杀掉15个骷髅袭击者、3个骷髅医师和3个骷髅看守，然后回来见斯温。",
    [324] = "收集5块光铸铁锭，把它们交给湿地的戈罗林·钢眉。",
    [325] = "现在你已经得到了强大的武器，去向暮色森林的斯温复命吧。",
    [328] = "使用黄铜钥匙打开书呆子赫罗德的保险箱。",
    [329] = "将沾泥的便笺交给叛军营地里的多伦上尉。",
    [330] = "与塞斯曼下士谈一谈。",
    [331] = "与多伦上尉谈一谈。",
    [332] = "到加林纳酒店去, 将酒票交给苏泽塔·加林纳以换一瓶免费的酒。",
