    [338] = "收集《荆棘谷的青山》的手稿中丢失的页面。在集齐四章书之后，将它们还给巴尼尔·石罐。",
    [339] = "将奈辛瓦里的小说《荆棘谷的青山》的第1页，第4页，第6页和第8页带给巴尼尔·石罐以凑齐第一章。",
    [340] = "将奈辛瓦里的小说《荆棘谷的青山》的第10页，第11页，第14页和第16页带给巴尼尔·石罐以凑齐第二章。",
    [341] = "将奈辛瓦里的小说《荆棘谷的青山》的第18页，第20页，第21页和第24页带给巴尼尔·石罐以凑齐第三章。",
    [342] = "将奈辛瓦里的小说《荆棘谷的青山》的第25页，第26页和第27页带给巴尼尔·石罐以凑齐第四章。",
