    [357] = "把巫妖的法术书带给幽暗城的比索·埃斯沙德。",
    [358] = "杀死腐皮盗墓贼和混血腐皮豺狼人。 给布瑞尔的执政官塞弗伦带回8瓶防腐剂。",
    [359] = "与亡灵卫兵林奈谈一谈。",
    [360] = "向布瑞尔的执政官塞弗伦报告。",
