    [459] = "收集8块魔苔，把它们交给塔琳德拉。",
    [460] = "将奥拉瑞克的头颅带到他的坟墓旁。",
    [461] = "将奥拉瑞克带到密室去。",
    [463] = "找到绿色守卫者。",
    [464] = "给斯托菲队长带回8面龙喉战旗。",
    [465] = "摧毁所有的龙喉投石车。",
    [466] = "给丹莫罗的驾驶员迪恩·石轮带回6份火岩矿石。",
    [467] = "和驾驶员迪恩·石轮谈一谈。",
    [468] = "与巡山人罗克加谈一谈。",
    [469] = "将这捆鳄鱼皮带给米奈希尔港的皮匠詹姆斯·哈洛兰。",
    [470] = "铁须之墓中的某只软泥怪身上有塞达的背包，夺回背包，把它送还给米奈希望港的塞达。",
    [471] = "为米奈希尔港的詹姆斯·哈洛兰带回6张巨型鳄鱼的皮。",
