    [473] = "与斯托菲队长谈一谈。",
    [474] = "杀死纳克罗什酋长。 将纳克罗什酋长的头颅交给斯托菲队长。",
    [475] = "在星风村找到盖洛拉斯·塔文斯伦。",
    [476] = "返回多兰纳尔去见阿斯瑞达斯·熊皮。",
    [477] = "从达拉然法师的木箱中拿出里面的东西。",
    [478] = "将这个奇怪的坠饰交给瑟伯切尔的暗影牧师奥利斯特。",
    [479] = "为瑟伯切尔的暗影牧师奥利斯特抢到8个达拉然坠饰。",
    [480] = "杀死达拉然大法师，并把他的法杖交给瑟伯切尔的暗影牧师奥利斯特。",
    [481] = "把刻有符文的坠饰交给瑟伯切尔的达拉尔·道恩维沃尔。",
    [482] = "与瑟伯切尔的暗影牧师奥利斯特谈一谈。",
    [483] = "寻回四件唤醒圣物,把它们带给多兰纳尔的阿斯瑞达斯·熊皮。",
    [484] = "为米奈希尔港的詹姆斯·哈洛兰取得6张小鳄鱼皮。",
    [485] = "把定位器带到奥格索普的母体机器人那里去。 奥格索普的母体机器人位于辛特兰的河水源头，就在藏身石的附近。",
