    [651] = "从西禁锢之石、东禁锢之石和外禁锢之石中搜集烈焰钥匙、海浪钥匙和雷霆钥匙。 把它们带到内禁锢之石处。",
    [652] = "找到并杀死弗兹鲁克，然后把秩序魔棒带到阿拉希高地的钥匙之石旁。",
    [653] = "和铁炉堡的葛利·硬骨谈一谈。",
    [654] = "收集8份蜥蜴、8份土狼和8份蝎子的合格样本，并在能量源耗尽前把测试工具包交还给加基森的首席工程师沙克斯·比格维兹。",
    [655] = "和落锤村的托尔甘交谈。",
    [656] = "到密斯莱尔水晶碎块去召唤她，然后打败她。 搜出她身上的怪异镣铐，将其和密斯莱尔水晶碎块缚在一起。",
    [657] = "和基恩洛谈一谈。",
    [658] = "找到被遗忘者信使，把她的密封的信件交给格沙克农场里的奎艾。",
    [659] = "到阿拉希高地上的格沙克农场附近找到奎艾和基恩洛。",
    [660] = "保护基恩洛，直到她回到奎艾身边。",
    [661] = "到南海镇去找到费恩·奥德利克。",
    [662] = "大副尼兹利克斯让你从处女号和银松之魂号中取回航海图和航海日志。",
    [663] = "和法迪尔海湾的奥布里船长交谈。",
    [664] = "法迪尔海湾的斯迪加特船长要你去杀掉10个刺脊袭击者和3个刺脊巫师。",
    [665] = "护送菲兹索普教授到洞穴里去并平安返回。",
    [666] = "法迪尔海湾的德拉克里格博士要你去收集10块精灵宝石并在完成任务后归还寻宝潜水镜。",
    [667] = "在纳迦的攻击中保护沙克斯·奥布里。",
    [668] = "把精灵宝石交给奥布里船长。",
    [669] = "把精灵宝石样本交给藏宝海湾的舰队指挥官海角。",
    [670] = "把海角船长的密信送给阿拉希高地的沙克斯·奥布里。",
    [671] = "帮落锤村的托尔甘找10枚血石护符。",
    [672] = "从高地阔步龙和高地长尾龙身上取得10个高地迅猛龙的眼球，把它们交给落锤村的托尔甘。",
    [673] = "取回玛雷兹·考尔的血石宝珠，把它交给落锤村的托尔甘。",
    [674] = "把迅猛龙利爪护符交给戈穆尔。",
    [675] = "和托尔甘谈一谈。",
    [676] = "杀掉8个石拳食人魔和10个石拳执行者，然后去阿拉希高地的落锤村哨所找杜拉姆法尔。",
    [677] = "杀死10名枯木掷斧者、10名枯木猎头者和8个枯木巫医，然后回到落锤村哨所的杜拉姆法尔那里。",
    [678] = "杀死10个石拳蛮兵和4个石拳法师，然后向落锤村哨所的杜拉姆法尔复命。",
    [679] = "杀死15个石拳萨满祭司和10个石拳领主，然后向落锤村哨所的杜拉姆法尔复命。",
