    [683] = "把萨拉·巴鲁的便笺交给铁炉堡的国王麦格尼·铜须。",
    [684] = "把玛雷兹的头颅交给避难谷地的尼艾丝队长。",
    [685] = "把法库雷斯特和奥图的头颅交给避难谷地的尼艾丝队长。",
    [686] = "国王麦格尼·铜须让你去和大石匠玛布勒斯坦谈一谈。",
    [687] = "找到迷失者塞尔杜林。",
    [688] = "和落锤村的萨鲁克谈一谈。",
