    [690] = "找到位于阿拉希高地上的避难谷地中的斯奎尔图。",
    [691] = "帮避难谷地中的学徒克里汀收集10个枯木巨魔的獠牙，4只枯木巨魔的医药包和1把暗影猎手的小刀。",
    [692] = "把破损的卷轴碎片、弄皱的卷轴碎片和烧焦的卷轴碎片带给迷失者塞尔杜林。",
    [693] = "帮避难谷地的斯奎尔图找到特雷莱恩的符咒魔杖，并把它带回来。",
    [694] = "找到一块碧蓝玛瑙石，把它交给避难谷地处的学徒克里汀。",
    [695] = "和斯奎尔图谈一谈。",
    [696] = "找到特雷莱恩的护符匣、特雷莱恩的宝珠和特雷莱恩的黑玛瑙，把它们交给避难谷地的斯奎尔图。",
    [697] = "将给大法师马林的信交给暴风城法师区里的大法师马林。",
    [698] = "给悲伤沼泽的托克卡尔带去8块新鲜的盐齿鳄鱼肉。",
    [699] = "给悲伤沼泽的托克卡尔带去6只盐齿钳嘴鳄的爪子。",
    [700] = "向铁炉堡的国王麦格尼·铜须汇报。",
    [701] = "从高地猎兽龙身上获取12颗迅猛龙的心脏，把它们交给托尔甘。",
