    [705] = "收集9枚蓝珍珠，把它们交给荒芜之地的里格弗兹。",
    [706] = "为西格鲁·铁斧拿到一颗黑色幼龙之心。",
    [707] = "和洛克莫丹铁环挖掘场的勘察员基恩萨·铁环谈一谈。",
    [709] = "把雷乌纳石板带给迷失者塞尔杜林。",
