    [718] = "帮西格鲁·铁斧找回补给箱。",
    [719] = "找到雷杜尔的好运锄，把它交给铁趾挖掘场南边的勘察员雷杜尔。",
    [720] = "找到勘察员雷杜尔，告诉他铁趾格雷兹还活着。",
    [721] = "在奥达曼找到铁趾格雷兹。",
    [722] = "找到铁趾的护符，把它交给奥达曼的铁趾。",
    [723] = "把铁趾的护符交给荒芜之地的勘察员雷杜恩。",
    [724] = "把铁趾的护符交给铁炉堡的史学家卡尼克。",
    [725] = "找到顾问贝尔格拉姆，把便笺交给他。",
    [726] = "和史学家卡尼克谈一谈。",
    [727] = "把战锤印章交给铁炉堡的葛利·硬骨。",
    [728] = "把战锤印章交给幽暗城的看守者贝尔杜加。",
