    [730] = "到奥伯丁去寻找矮人挖掘队的线索。",
    [731] = "在勘察员雷姆塔维尔搜寻神秘化石的时候保护他，然后回到奥伯丁的考古学家霍莉那里。",
    [732] = "帮加瑞克取回大地印章。",
    [733] = "帮西格鲁收集7块金属碎片。",
    [734] = "和荒芜之地的卢希恩·枪穗谈一谈。",
    [735] = "找齐葛利·硬骨的便笺上列出的东西，然后把它们交给铁炉堡的葛利·硬骨。",
    [736] = "把贝尔杜加的便笺上列出的东西带给幽暗城的看守者贝尔杜加。",
    [737] = "把雅格因的笔记交给塞尔杜林。",
    [738] = "找到阿戈莫德。",
    [739] = "干掉杀害阿戈莫德的凶手：莫达洛克。 顺便杀掉12个石窟断骨者。 然后向洛克莫丹的勘察员基恩萨·铁环报告。",
    [741] = "把神秘的化石交给达纳苏斯的首席考古学家杜瑟·灰须。",
    [742] = "与灰谷碎木哨岗的塞娜尼·雷心谈一谈。",
    [743] = "给血蹄村的卢尔·鹰爪带回8只风怒鹰身人的爪子。",
    [744] = "收集6根碧蓝色的羽毛和6根古铜色的羽毛，把它们交给雷霆崖的伊恩·鹰爪。",
    [745] = "杀死10个白鬃制革工、8个白鬃剥皮工和5个白鬃偷猎者，然后回到血蹄村向贝恩·血蹄复命。",
    [746] = "收集5个勘察员的锄头。 在铁匠铺砸碎这些勘察员的锄头。 把5件损坏的工具交给血蹄村的贝恩·血蹄。",
    [747] = "纳拉其营地的格鲁尔·鹰风要求你带给他7片平原陆行鸟的羽毛和7块平原陆行鸟肉。",
    [748] = "收集6只草原狼的爪子和4只平原陆行鸟的爪子，把它们交给血蹄村的穆尔·雷角。",
