    [756] = "收集6个草原捕食者的爪子和6个平原狮的爪子，把它们带给穆尔·雷角。",
    [757] = "杀掉刺刃峡谷的刺背野猪人并带回12条刺背腰带，把它们交给纳拉其营地的鹰风酋长。",
    [758] = "在雷角之井使用雷角之井净化图腾，然后回来见穆尔。",
