    [792] = "杀死12只邪灵劣魔，然后向大兽穴外的祖雷萨复命。",
    [793] = "用大地印章激活钻石之柱、欧泊之柱和紫水晶之柱并拿到三颗符石。 把符石放在大地封印上，释放黑龙布莱克拉什和赫玛图斯。 杀了这两条黑龙，把黑龙布莱克拉什的锁链、赫玛图斯的锁链和大地印章交给高恩。",
    [794] = "给大兽穴外的祖雷萨带回火刃奖章。",
    [804] = "将哈纳祖目前的状况告诉大兽穴内的高内克。",
    [805] = "与森金村的加德林大师谈一谈。",
    [806] = "把费索的爪子带给剃刀岭的奥戈尼尔·魂痕。",
