    [809] = "到贫瘠之地去和雅克塞罗斯谈一谈。",
    [812] = "找到毒尾蝎的解毒剂，把它交给杜隆塔尔西北边境的林纳格。",
    [813] = "收集4个毒尾蝎的毒囊，把它们交给奥格瑞玛的考格汉。",
    [815] = "收集3个鞭尾龙的蛋，并把它们带给剃刀岭的厨师托尔卡。",
    [816] = "把关于克鲁恩的消息告诉剃刀岭西北部农场中的米莎·托克伦。",
    [817] = "收集四张杜隆塔尔虎皮，并把它们交给森金村的维尔林·长牙。",
    [818] = "把4个龙虾人的眼睛和8小瓶蟹胶带到森金村，交给沃纳尔大师。",
    [819] = "找到对老陈的空酒桶有所了解的人。",
    [821] = "收集5颗草原狮的獠牙、5个平原陆行鸟的肾脏和1根雷霆蜥蜴的角，把它们交给棘齿城的酿酒师德罗恩。",
