    [1861] = "把一份明镜湖水的样本交给暴风城的詹妮亚·坎农。",
    [1879] = "和铁炉堡的彬克谈一谈。",
    [1880] = "帮彬克找回她的法师文档存储器。",
    [1881] = "和安娜斯塔西娅·哈特威尔谈一谈。",
    [1882] = "将巴尼尔金鱼草交给幽暗城法师区的安娜斯塔西娅·哈特威尔。",
    [1883] = "和安苏瓦谈一谈。",
    [1884] = "摧毁4个魂能骨堆，然后向森金村的安苏瓦汇报。",
    [1885] = "与幽暗城潜行者区的米奈特·卡加德谈一谈。",
    [1886] = "得到阿斯托的介绍信，并将其交给潜行者区的米奈特·卡加德。",
    [1898] = "与幽暗城的安德隆·甘特交谈。",
    [1899] = "将阿斯托的的账本交给幽暗城潜行者区的米奈特·卡加德。",
    [1918] = "将被污染的水球交给灰谷碎木哨岗的马斯托克·维尔西斯。",
    [1919] = "和暴风城的詹妮亚·坎农谈一谈。",
    [1920] = "从詹妮亚·坎农身后拿取一根显形卷轴以及一盒封灵箱。将3个装满的封灵箱交给巫师圣殿里的詹妮亚·坎农。",
    [1921] = "把10匹亚麻布和6颗充能裂隙宝石交给暴风城的维恩·拉尔森。",
    [1938] = "将《乌尔的暗影魔法研究论文》交给暴风城的高阶巫师安多玛斯。",
    [1939] = "和高阶巫师安多玛斯谈一谈。",
    [1940] = "找到8束新鲜的蜘蛛丝，把它们交给暴风城的维恩·拉尔森。",
    [1943] = "和迪诺谈一谈。",
    [1944] = "将克萨维亚水样交给奥格瑞玛的迪诺。",
    [1945] = "给十字路口的基尔哈拉带去12缕欢笑姐妹的头发。",
    [1947] = "和塔贝萨谈一谈。",
    [1948] = "将电能草莓和1颗翡翠交给尘泥沼泽的塔贝萨。",
    [1949] = "和闪光平原的大法师提尔斯谈一谈。",
    [1950] = "找到提尔斯保险箱的解封咒语，然后向提尔斯复命。",
    [1951] = "将《能量仪祭》交给尘泥沼泽的塔贝萨。",
    [1952] = "等塔贝萨的仪式完成后，和她谈一谈。",
    [1953] = "和塔贝萨谈一谈。",
    [1954] = "将一颗地狱火宝珠交给尘泥沼泽的塔贝萨。",
    [1955] = "杀死宝珠之魔，然后与塔贝萨谈一谈。",
    [1956] = "找到一个黑曜石能量源，将其交给尘泥沼泽的塔贝萨。",
    [1957] = "在限定时间内杀死12只法力怒灵。",
    [1959] = "和安娜斯塔西娅·哈特威尔谈一谈。",
    [1960] = "从安娜斯塔西娅·哈特威尔身后拿取一根显形卷轴以及一盒封灵箱。将3个装满的封灵箱交给幽暗城的安娜斯塔西娅·哈特威尔。",
    [1961] = "把10块亚麻布和6块达拉然法力宝石带给乔瑟夫·格里高利。",
    [1963] = "杀死塔赞，把他的背包带给奥格瑞玛暗影裂口的瑟祖克。",
    [1978] = "将安德隆的账本交给幽暗城黑暗女王大厅里的瓦里玛萨斯。",
    [1998] = "杀掉芬维克·萨托斯，把他的头颅交给幽暗城潜行者区的米奈特·卡加德。",
    [1999] = "找到达拉然形势报告，把它交给幽暗城潜行者区的米奈特·卡加德。",
    [2038] = "找回宾格斯的装备： $宾格斯的气压炸弹、宾格斯的扳手、宾格斯的榔头和宾格斯的螺丝起子。",
    [2039] = "去洛克莫丹寻找宾格斯。",
    [2040] = "从死亡矿井中带回小型高能发动机，将其带给暴风城矮人区中的沉默的舒尼。",
    [2041] = "去暴风城和舒尼谈一谈。",
    [2078] = "找到基尔卡克的大副——机械打手4100型，把他带到基尔卡克那里。",
    [2098] = "找到基尔卡可钥匙的3段碎片，把它们交给基尔卡克·旋杆。",
    [2118] = "活捉一只狂暴蓟熊，把它带到萨纳瑞恩那里。",
    [2138] = "到森林里去杀掉20头狂暴蓟熊。",
    [2139] = "找到雌蓟熊，然后杀掉它。",
    [2158] = "和狮王之傲旅店的旅店老板法雷谈一谈。",
    [2159] = "把药草送到旅店老板凯达米尔手中。",
    [2160] = "给卡拉诺斯的塔诺克·霜锤带去一箱旅店补给品。",
    [2161] = "把乌克尔的货物交给剃刀岭的旅店老板格罗斯克。",
    [2178] = "给急弯河的奥兰达利亚·夜歌带回5块陆行鸟肉。",
    [2198] = "找到破碎的项链的来源，从而了解其潜在的价值。",
    [2199] = "给铁炉堡的塔瓦斯德·基瑟尔带去五块银锭。",
    [2200] = "去奥达曼寻找塔瓦斯的魔法项链，被杀的圣骑士是最后一个拿着它的人。",
    [2201] = "在奥达曼寻找红宝石、蓝宝石和黄宝石的下落。找到它们之后，通过塔瓦斯德给你的占卜之瓶和他进行联系。",
    [2202] = "收集12颗紫色蘑菇，把它们交给卡加斯的加卡尔。",
    [2203] = "用空的魔瓶吸收荒芜之地的烈焰守护者的血液。装满所有瓶子之后，把它们交给卡加斯的加卡尔。",
    [2204] = "从奥达曼最强大的石人身上获得能量源，然后将其交给铁炉堡的塔瓦斯德。",
    [2205] = "把科瑞恩·塞尔留斯的包裹带给暴风城兵营的马迪亚斯·肖尔。",
    [2206] = "找到迪菲亚码头主管，从他那里为马迪亚斯·肖尔拿到迪菲亚船运时间表。",
    [2218] = "和铁炉堡的霍夫丹·黑须谈一谈。",
    [2238] = "在诺莫瑞根附近找到奥宁·雨锤。",
    [2239] = "把奥宁的报告交给铁炉堡的霍夫丹。",
    [2240] = "阅读巴尔洛戈的日记，探索密室，然后向铁炉堡的勘察员塔伯斯·雷矛汇报。",
    [2241] = "把詹诺克的玫瑰带给达纳苏斯的塞尤娜。",
    [2242] = "找到远古的塞希尔，带回任何你可能发现的线索。",
    [2258] = "前往荒芜之地取回加卡尔需要的试剂，然后回到卡加斯把试剂交给他。",
    [2259] = "与达那苏斯的艾瑞安·影语取得联系。",
    [2260] = "到暴风城去找到“剃刀”雷吉克。",
    [2278] = "和石头守护者交谈，从他那里了解更多古代的知识。一旦你了解到了所有的内容之后就激活诺甘农圆盘。",
    [2279] = "把迷你版的诺甘农圆盘带到铁炉堡的探险者协会去。",
    [2280] = "把迷你版的诺甘农圆盘带到雷霆崖的贤者那里。",
    [2281] = "到赤脊山的湖畔镇去和卢修斯谈一谈。",
    [2282] = "打开卢修斯的箱子，拿到偷窃技能证明物，然后把它归还给湖畔镇的卢修斯。",
    [2283] = "在奥达曼挖掘场中寻找一条珍贵的项链，然后将其交给奥格瑞玛的德兰·杜佛斯。项链有可能已经损坏。",
    [2284] = "在奥达曼里找寻宝石的线索。",
    [2298] = "到暴风城里去找到“剃刀”雷吉克。",
    [2299] = "到铁炉堡去和霍夫丹·黑须谈一谈。",
    [2300] = "到暴风城去找到“剃刀”雷吉克。",
    [2318] = "在荒芜之地的卡加斯哨所里寻找一个可以帮你翻译圣骑士日记的人。",
    [2338] = "将项链借给加卡尔。作为交换，他将帮你翻译日记。",
    [2339] = "从奥达曼找回项链上的所有三块宝石和能量源，然后把它们交给卡加斯的加卡尔。 红宝石被藏在暗影矮人层层设防的地区。 黄宝石藏在石腭怪活动地区的一个瓮中。 蓝宝石在格瑞姆洛克手中，他是石腭怪的领袖。 能量源可能在奥达曼的某个最强生物的手中。",
    [2340] = "把项链和宝石送到奥格瑞玛的德兰·杜佛斯那里。",
    [2341] = "去卡加斯看看加卡尔是否成功了。",
    [2342] = "从奥达曼南部大厅的箱子中找到加勒特的家族宝藏，然后把它交给幽暗城的帕特里克·加瑞特。",
    [2359] = "偷取迪菲亚塔楼钥匙，进入迪菲亚塔楼，看看暮色森林的箱子里到底有什么东西，然后向暴风城的马迪亚斯·肖尔汇报。",
    [2360] = "去西部荒野和密探吉尔妮谈一谈。",
    [2378] = "前往奥格瑞玛，和暗影裂口那的申苏尔谈一谈。",
    [2379] = "与暗影裂口的赞杜沙谈一谈。",
    [2380] = "在奥格瑞玛城中的暗影裂口和申苏尔谈谈。",
    [2381] = "把南海宝藏带回给棘齿城的卑鄙的维尼克斯。不要忘了从维尼克斯的机械设备中拿取一份大饼干和潜行者工具，你的任务需要使用这两件东西。 如果你被任何奇怪的鹦鹉攻击，就对它使用大饼干！",
    [2382] = "到棘齿城去，与卑鄙的维尼克斯谈一谈。",
    [2383] = "阅读简易羊皮纸，然后和试炼谷的弗郎恩谈一谈。",
    [2398] = "在奥达曼找到巴尔洛戈。",
    [2418] = "给荒芜之地的里格弗兹带去8块德提亚姆能量石和8块安纳洛姆能量石。",
    [2438] = "将翡翠摄梦符交给多兰纳尔的塔隆凯·捷根。",
    [2439] = "把你的报酬凭证交给铁炉堡银行的丁尼塔·石衣。",
    [2440] = "把报酬凭证交给雷霆崖的本娜·冰蹄。",
    [2458] = "到淤泥沼泽北边的风险投资公司塔楼去，联系碎手氏族的卧底费苏勒。 看到塔楼之后，用信号枪发射信号，向工头费苏勒示意你已经到达。发出两个闪光信号，然后使用碎手军礼和工头费苏勒接头。 注意，这些步骤必须依次进行，因为费苏勒会攻击并干掉任何他无法识别的人。",
    [2459] = "多兰纳尔的塔隆凯·捷根要你杀掉7个瘤背秘法师，并找到遗失的珠宝。",
    [2460] = "对着申苏尔练习碎手军礼。",
    [2478] = "从工头希里克斯那里偷出希里克斯的塔楼钥匙，进入塔楼，然后杀掉两个变异风险投资公司工人、两个风险投资公司巡逻员、两个风险投资公司看守。 杀掉大工头普兹克·加里维克斯，取了他的首级，然后打开加里维克斯的箱子，拿走赞吉尔的改良药剂。将药剂和加里维克斯的头颅交给奥格瑞玛的申苏尔，等候进一步的指示。",
    [2479] = "到希尔斯布莱德丘陵的塔伦米尔去，把赞吉尔的药剂样品交给瑟尔格·希诺特。 要去塔伦米尔，可以搭乘飞艇到幽暗城，然后沿着大路向南穿过银松森林，直到希尔斯布莱德丘陵。跟着路标走！",
    [2480] = "等待瑟尔格·希诺特完成解药。",
    [2498] = "雷利亚·绿树要你和奥拉密斯湖的德纳兰谈一谈。",
    [2499] = "奥拉密斯湖的德纳兰要你去拿到奥肯斯古尔身上的巨大的瘤。",
    [2500] = "从荒芜之地拿到加克所需的材料，然后回到塞尔萨玛去见他。",
    [2501] = "在荒芜之地的守护火龙身上使用空的魔瓶。将这些容器都盛满之后，把它们交给塞尔萨玛的加克。",
    [2518] = "达纳苏斯月神殿的女祭司艾茉拉让你把萨丝拉的银色丝囊交给她。",
    [2519] = "艾奎恩妮让你和月神殿的女祭司艾茉拉谈一谈。",
    [2520] = "女祭司艾茉拉让你将萨丝拉的银色丝囊放在大殿的喷泉处，然后回去见她。",
    [2521] = "在你探索诅咒之地的旅程中，如果碰巧发现了无暇的德莱尼水晶球，就把它交给收藏家库米沙。 你要知道，这种宝石是整个艾泽拉斯最珍稀的水晶。诅咒之地上的任何一种生物都有可能带着一颗无暇的德莱尼水晶球。 每找到一颗，你都会得到相应的酬劳。",
    [2522] = "找到一颗无暇的德莱尼水晶球，把它交给收藏家库米沙。",
    [2541] = "将一个萨满巫毒符咒交给班奈希尔兽穴的奥本·怒爪。",
    [2561] = "奥本·怒爪要求你去杀掉他那失去灵魂的身体，然后对其尸体使用巫毒咒符。",
    [2581] = "收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。",
    [2582] = "收集3个弯牙土狼的颚骨、2片诅咒之地的野猪肺和1个厚甲蝎螯，把它们交给血法师德拉吉亚。",
    [2583] = "收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。",
    [2584] = "收集3片诅咒之地的野猪肺、2个厚甲蝎螯和1颗石化蜥蜴的大脑，把它们交给血法师德拉吉亚。",
    [2585] = "收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。",
    [2586] = "收集3个厚甲蝎螯、2个秃鹫的砂囊和1片诅咒之地的野猪肺，把它们血法师德拉吉亚。",
    [2601] = "收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。",
    [2602] = "收集10颗石化蜥蜴的大脑和2个秃鹫的砂囊，把它们交给血法师莱诺雷。",
    [2603] = "收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。",
    [2604] = "收集10个秃鹫的砂囊和2块弯牙土狼的颚骨，把它们交给血法师莱诺雷。",
    [2605] = "找到1个饱满的露水腺，把它交给加基森的马林·诺格弗格。",
    [2606] = "马林·诺格弗格让你与加基森的斯普琳科谈一谈。",
    [2607] = "到兵营的地窖里去和道克·米希匹克斯谈一谈。",
    [2608] = "用/lay指令躺下，接受道克·米希匹克斯的治疗。如果他找不到病因，就找不到治疗的方法。",
    [2609] = "给道克·米希匹克斯带去一束普通野花、一只铅瓶，一根青铜管，最后还要一卷淡绿色丝线。伊提斯综合症可不会不治而愈，年轻的小姐。",
    [2621] = "与斯通纳德的分队指挥官鲁尔格谈一谈。",
    [2622] = "与本戈尔谈一谈。",
    [2623] = "取回酋长的命令，把它们还给部落英雄的灵魂。",
    [2641] = "加基森的斯普琳科要你去给她找到一颗紫色水生菇。",
    [2661] = "斯普琳科让你把紫色粉末交给加基森的马林·诺格弗格。",
    [2662] = "马林·诺格弗格让你在他制成药剂之后再去找他。",
    [2681] = "解救九个拉瑟莱克的仆从、三个瑟温妮的仆从、三个奥利斯塔的仆从和三个戈洛尔的仆从。完成任务后，回到部落英雄的灵魂这里。",
    [2701] = "打开箱子，取走你的酬劳。",
    [2702] = "和桑德·裂蹄谈一谈。",
    [2721] = "找到基利斯的下落。",
    [2742] = "护送林吉逃出奎尔丹尼小屋，然后在望海崖找到他藏起来的东西。",
