    [3086] = "阅读雕文石板，然后和试炼谷里大兽穴入口附近的迈安谈一谈。",
    [3087] = "阅读风蚀羊皮纸，然后和试炼谷的基沙谈一谈。",
    [3088] = "阅读密文羊皮纸，然后和试炼谷的鲁瓦格谈一谈。",
    [3089] = "阅读符文羊皮纸，然后和试炼谷的史克里克谈一谈。",
    [3090] = "阅读被污染的羊皮纸，然后到试炼谷的大兽穴里去和纳托克谈一谈。",
