    [3094] = "阅读绿色便笺，然后与纳拉其营地的加尔特·迷雾行者谈一谈。",
    [3095] = "阅读简易卷轴，然后和丧钟镇的丹纳尔·斯特恩谈一谈。",
    [3096] = "阅读密文卷轴，然后和丧钟镇的大卫·提亚斯谈一谈。",
    [3097] = "阅读神圣卷轴，然后和丧钟镇教堂的黑暗牧师杜斯滕谈一谈。",
    [3098] = "阅读雕文卷轴，然后和丧钟镇教堂的伊莎贝拉谈一谈。",
    [3099] = "阅读被污染的卷轴，然后和丧钟镇的马克希米林谈一谈。",
