    [3101] = "阅读圣洁信件，然后和北郡修道院的萨缪尔修士谈一谈。",
    [3102] = "阅读密文信件，然后与北郡修道院的乔里克·克里丹谈一谈。",
    [3103] = "阅读神圣信件，然后与北郡修道院的牧师安妮塔谈一谈。",
    [3104] = "阅读雕文信件，然后与北郡修道院的凯尔东·布雷曼谈一谈。",
    [3105] = "阅读被污染的信件，然后与北郡修道院旁边的杜希拉·拉萨雷谈一谈。",
    [3106] = "阅读简易符文，然后与寒脊山谷的斯兰·库尔曼谈一谈。",
    [3107] = "阅读神圣符文，然后与寒脊山谷的布罗莫斯·格鲁诺尔谈一谈。",
    [3108] = "阅读风蚀符文，然后与寒脊山谷的索加斯·格瑞姆森谈一谈。",
    [3109] = "阅读密文符文，然后与寒脊山谷的索姆·哈格林谈一谈。",
    [3110] = "阅读神圣符文，然后与安威玛尔的布兰斯托·卡尔德谈一谈。",
    [3112] = "阅读简易备忘录，然后与寒脊山谷的斯兰·库尔曼谈一谈。",
    [3113] = "阅读密文备忘录，然后与寒脊山谷的索姆·哈格林谈一谈。",
    [3114] = "阅读雕文备忘录，然后与寒脊山谷上的安威玛尔镇里的玛瑞克·斯托纳尔谈一谈。",
    [3115] = "阅读被污染的备忘录，然后寒脊山谷上的安威玛尔镇里的阿拉玛尔·格里姆谈一谈。",
    [3116] = "阅读简易符记，然后与幽影谷的奥莉希亚谈一谈。",
    [3117] = "阅读风化符记，然后与奥达希尔里和阿亚娜·远途谈一谈。",
    [3118] = "阅读密文符记，然后与幽影谷的弗拉胡恩·影语者谈一谈。",
    [3119] = "阅读神圣符记，然后与奥达希尔的珊达谈一谈。",
    [3120] = "阅读绿色符记，然后与幽影谷中的奥达希尔顶端的玛丹特·硬木谈一谈。",
    [3121] = "将皱缩的头颅交给奥格瑞玛的尼尔鲁·火刃。",
    [3122] = "将尼尔鲁的草药包送给菲拉斯的巫医尤克里。",
    [3123] = "到辛特兰去杀掉10头枭兽，然后使用灵魂精华容器捕获它们的灵魂。 将灵魂精华容器和10个枭兽灵魂精华交给菲拉斯的巫医尤克里。",
    [3124] = "杀掉10只任意种类的乱羽角鹰兽，然后用灵魂精华容器捕获它们的灵魂。",
    [3125] = "杀掉8只精龙或小精龙，然后用灵魂精华容器捕获它们的灵魂。",
    [3126] = "杀掉3个森林漫游者，然后用灵魂精华容器捕获它们的灵魂。",
    [3127] = "杀掉7个大地行者或者峭壁巨人，然后用灵魂精华容器捕获它们的灵魂。",
    [3128] = "为莫沙彻营地的巫医尤克里收集2根断裂的原木、6颗包壳矿石、20片有弹性的肌腱和40块金属碎片。",
    [3129] = "巫医尤克里希望你在他准备武器的时候稍等一会儿。",
    [3130] = "到羽月要塞的拉托尼库斯·月矛那里去报到。",
    [3141] = "听洛拉姆斯·萨里比迪斯讲述他的故事。",
    [3161] = "塔纳利斯的玛尔冯·瑞文斯克要你收集30件加兹瑞迪安饰物。",
    [3181] = "将玛尔戈的巨角交给巡山人贝波蒂。",
    [3182] = "把玛尔戈的巨角交给铁炉堡的索里奥斯馆长。",
    [3201] = "把索里奥斯的证明信交给巡山人贝波蒂。",
    [3221] = "与瑟伯切尔的药剂师伦弗利尔谈一谈。",
    [3261] = "与陶拉祖营地的乔恩·星眼谈一谈。",
    [3281] = "把被偷走的银币交给十字路口的加兹罗格。",
    [3301] = "和瑟伯切尔的茉拉·符文图腾谈一谈。",
    [3321] = "等待特伦顿完成他的工作。",
    [3341] = "安德鲁·布隆奈尔要你杀了寒冰之王亚门纳尔并将其头骨带回来。",
    [3361] = "把菲利克斯的盒子、菲利克斯的箱子和菲利克斯的螺钉桶交给安威玛尔的菲利克斯。",
    [3362] = "加基森的特兰雷克要你杀掉8只长瘤的灌木兽和8只灌木塑根者。",
    [3364] = "在5分钟内把热酒交给安威玛尔的德南·弗卡特。",
    [3365] = "把诺里斯的杯子还给诺里斯·激流。",
    [3367] = "帮助杜里奥斯回到铁炉堡。",
    [3368] = "把烧焦的信件交给铁炉堡的索里奥斯，他在探险者大厅里。",
    [3369] = "把噩梦碎片交给长者高地的哈缪尔·符文图腾。",
    [3370] = "把噩梦碎片交给达纳苏斯的玛斯雷·驭熊者。",
    [3371] = "回到灼热峡谷，找到杜里奥斯的考古队员。",
    [3372] = "到北方去找到被暮光之锤守卫着的神秘的古器。",
    [3373] = "把伊兰尼库斯精华放在精华之泉里，精华之泉就在沉没的神庙中，伊兰尼库斯的巢穴里。",
    [3374] = "把伊瑟拉巨龙军团的誓言石和被禁锢的伊兰尼库斯精华交给悲伤沼泽的伊萨里奥斯。在那里你可以决定是否要帮助伊瑟拉的绿龙军团。",
    [3375] = "把一瓶法力药水、一块煤和一瓶蜂蜜酒送到铁炉堡的塔瓦斯德·基瑟尔那里，用以换取塔瓦斯德的占卜之瓶。",
    [3376] = "把刺鬃酋长的头颅交给红云台地的卫兵维萨罗·风羽。",
    [3377] = "听萨麦尔讲述他的故事。",
    [3378] = "找到艾露恩祷言，然后将其交给达纳苏斯的阿斯塔利·逐星。",
    [3379] = "杀死在灼热峡谷游荡的暗影蛛丝偷猎者小队。尼莉丝认为他们共有5名成员，你的任务就是把他们全都干掉。",
    [3380] = "到塔纳利斯找到玛尔冯·瑞文斯克。",
    [3382] = "帮助瓦妮莎·贝蒂斯船长、她的船员和地平线轻帆号上的乘客抵御纳迦的攻击。瓦妮莎·贝蒂斯船长必须存活。",
    [3385] = "杀了贸易首领考维克和他的同伙科朗克。从他的尸体上拿回商人的背包，把它交给尼莉丝。",
    [3402] = "和加基森的维兹格里克谈一谈。",
    [3441] = "听威拉罗克·温布雷讲述他的故事。",
    [3442] = "收集4份烈焰之心和4份傀儡之油，然后把这些东西交给威拉罗克·温布雷。",
    [3443] = "给威拉罗克·温布雷带去8把瑟银匕首。",
    [3444] = "到棘齿城去，从玛尔冯·瑞文斯克的车间里取回石环。",
    [3445] = "到塔纳利斯找到玛尔冯·瑞文斯克。",
    [3446] = "在悲伤沼泽沉没的神庙中找到哈卡祭坛。",
    [3447] = "到沉没的神庙去，揭开雕像群中隐藏的秘密。",
    [3448] = "跟铁炉堡的泰摩尔谈一谈。",
    [3449] = "使用绘图工具包获取贝萨玛拉符文、辛耶尔符文、玛科里符文和塞尔哈符文的拓片，然后前往艾萨拉南部半岛外的小岛，把它们交给驾驶员西格斯·熔光。",
    [3450] = "与铁炉堡的希格斯·熔火谈一谈。",
    [3451] = "与铁炉堡的希格斯·熔火谈一谈，从他那儿获得一支标准型闪光信号枪。",
    [3452] = "找到一个拉格纳罗斯符记，把它交给威拉罗克·温布雷。",
    [3453] = "等待威拉罗克·温布雷完成惩戒火炬。",
    [3454] = "拿起惩戒火炬。",
    [3461] = "到铁炉堡去，将法师泰摩尔的绘图工具包还给他。",
    [3462] = "与侍卫玛特拉克谈一谈。",
    [3463] = "使用惩戒火炬点燃北部、南部、东部和西部的哨塔。",
    [3481] = "打开箱子。",
    [3501] = "将有瑕疵的德莱尼水晶碎片交给库米沙，你就可以得到相应的回报。",
    [3502] = "将有瑕疵的德莱尼水晶碎片交给库米沙。诅咒之地的任何怪物都有可能携带着这样的碎片。",
    [3504] = "把这封给阿格图的密信交给艾萨拉的阿格图·血拳。",
    [3505] = "杀死6名血精灵搜寻者和6名血精灵勘测员，然后查明雷姆托里的力量源自何处。",
    [3506] = "摧毁大法师雷姆托里携带的奥术聚焦水晶并杀死她。然后把她的脑袋交给艾萨拉的阿格图·血拳。",
    [3507] = "与奥格瑞玛的贝尔戈洛姆·石槌谈一谈。",
    [3508] = "等待洛拉姆斯完成启迪法术。",
    [3509] = "与艾萨拉的亚考罗克谈一谈。你应该在海边搜索亚考兰神殿。",
    [3510] = "杀掉赫塔拉，将染血的赫塔拉头颅、破碎的赫塔拉头颅和淤血的赫塔拉头颅交给亚考罗克。",
    [3511] = "将调剂交给洛拉姆斯·萨里比迪斯。",
    [3512] = "到冬泉谷的东部地区去，与灵语者阿姆布兰希谈一谈。",
    [3513] = "将符文卷轴带到贫瘠之地的北部警戒塔去。",
    [3514] = "杀死猛禽洞穴的领袖琳萨瑞尔。",
    [3517] = "找到贝萨玛拉石板、辛耶尔石板、玛科里石板和塞尔哈石板，把它们交给瓦罗莫克的杰迪加。",
    [3518] = "将贝萨玛拉石板交给雷霆崖的玛加萨·恐怖图腾。",
    [3519] = "与幽影谷的迪兰妮亚·银辉谈一谈。",
    [3520] = "在菲拉斯捕获3个尖啸者的灵魂，然后回到热砂港的叶基亚那里去。",
    [3521] = "在幽影谷中为迪兰妮亚·银辉收集7朵紫蓝色蘑菇、4朵月牙百合花和一份树林蜘蛛的脓液。",
    [3522] = "在5分钟内将埃沃隆的解药交给他。你可以北边的洞穴入口外面找到埃沃隆。",
    [3523] = "如果你同意帮助奔尼斯特拉兹，就再跟他谈谈，并将誓言石还给他。",
    [3524] = "从奥伯丁南面的海岸上收集海洋生物的骨头，然后带着骨头向奥伯丁的温尼斯·布莱葛回复。",
    [3525] = "保护奔尼斯特拉兹来到剃刀高地的野猪人神像处。 当他在进行仪式封印神像时保护他。",
    [3526] = "如果你想要对地精工程学有更多了解，就把工程学教材交给加基森的尼克斯·斯普克斯宾。",
    [3527] = "将第一块和第二块摩沙鲁石板交给塔纳利斯的叶基亚。",
    [3528] = "将装满的哈卡之卵交给塔纳利斯的叶基亚。",
    [3541] = "将辛耶尔石板交给奥格瑞玛的杰斯雷蒙。",
    [3542] = "将玛科里石板交给幽暗城的安德隆·甘特。",
    [3561] = "将塞尔哈石板交给艾萨拉的大法师克希雷姆。",
    [3562] = "将玛加萨的便笺交给艾萨拉的杰迪加。",
    [3563] = "将杰斯雷蒙的便笺交给艾萨拉的杰迪加。",
    [3564] = "将安德隆的便笺交给艾萨拉的杰迪加。",
    [3565] = "将克希雷姆的便笺交给艾萨拉的杰迪加。",
    [3566] = "杀死黑衣拉索里克和奥比斯顿，带着黑衣拉索里克的头颅和奥比斯顿的心脏回到铁炉堡的索里奥斯那儿。",
    [3568] = "在艾萨拉的埃达拉斯废墟旁的海潮之池中收集4瓶水，然后回到药剂师科雷那儿。",
    [3569] = "将科雷的药剂交给幽暗城的瑟尔萨·风歌。",
    [3601] = "搜索萨拉斯营地，找到基姆加尔的指南针、望远镜、烧鸡和花生，然后把它们交给艾萨拉的基姆加尔。",
    [3602] = "在艾萨拉南部收集20块艾萨拉晶体。你可以使用地狱犬协助寻找一些隐藏的矿脉。 任务完成之后就回到洛拉姆斯那里去。",
    [3621] = "把货物交给荆棘谷的加尔文。",
    [3625] = "等待加尔文为你锻造武器。",
    [3626] = "回到部落英雄的灵魂那里。",
    [3627] = "杀掉毁灭者戈洛尔、瑟温妮，以及大法师奥利斯塔。从他们到尸体上拿到戈洛尔的护符、瑟温妮的护符和奥利斯塔的护符。 记住使用你的魔化艾萨拉水晶武器来削弱他们，否则他们是无法被杀死的——你必须小心谨慎地使用你的武器……",
    [3628] = "消灭污染者拉瑟莱克，将污染者之角交给部落英雄的灵魂。另外你还要把污染者防护结界交给他，这样部落英雄的灵魂就可以消灭它，以避免它落入邪恶势力之手。",
    [3629] = "如果你想要对地精工程学有更多了解，就把工程学教材交给加基森的尼克斯·斯普克斯宾。",
    [3630] = "如果你想要对侏儒工程学有更多了解，就把工程学教材交给铁炉堡的工匠大师欧沃斯巴克。",
    [3631] = "与贫瘠之地棘齿城的斯坦哈德·法尔杉谈一谈。",
    [3632] = "如果你想要对侏儒工程学有更多了解，就把工程学教材交给铁炉堡的工匠大师欧沃斯巴克。",
    [3633] = "如果你想要对地精工程学有更多了解，就把工程学教材交给加基森的尼克斯·斯普克斯宾。",
    [3634] = "如果你想要对侏儒工程学有更多了解，就把工程学教材交给铁炉堡的工匠大师欧沃斯巴克。",
    [3635] = "如果你想要对侏儒工程学有更多了解，就把工程学教材交给藏宝海湾的奥格索普·奥布诺提斯。",
    [3636] = "大主教本尼迪塔斯要你去杀死剃刀高地的寒冰之王亚门纳尔。",
    [3637] = "如果你想要对侏儒工程学有更多了解，就把工程学教材交给藏宝海湾的奥格索普·奥布诺提斯。",
    [3638] = "如果你同意成为一名地精技师，就右键点击保密协议，然后再次和加基森的尼克斯·斯普克斯宾谈一谈。",
    [3639] = "将20颗重磅铁制炸弹、20颗实心炸弹和5只自爆绵羊交给加基森的尼克斯·斯普克斯宾。",
    [3640] = "如果你同意成为一名侏儒技师，就右键点击保密协议，然后再次和铁炉堡的工匠大师欧沃斯巴克谈一谈。",
    [3641] = "将6根秘银管、1只精确瞄准镜和2个高级假人交给铁炉堡的工匠大师欧沃斯巴克。",
    [3642] = "如果你同意成为一名侏儒技师，就右键点击保密协议，然后再次和藏宝海湾的奥格索普·奥布诺提斯谈一谈。",
    [3643] = "将6根秘银管、1只精确瞄准镜和2个高级假人交给藏宝海湾的奥格索普·奥布诺提斯。",
    [3661] = "为鲁瑟兰村的艾瑞拉斯·琥珀收集15支枭兽羽毛。",
    [3681] = "与暴风城的达索瑞恩·拉尔谈一谈。",
    [3701] = "到燃烧平原的索瑞森废墟中去，从索瑞森遗物上搜集信息。当你收集到足够的信息之后，就回到皇家历史学家阿克瑟努斯那里。",
    [3702] = "听皇家历史学家阿克瑟努斯讲述索瑞森的历史。",
    [3741] = "找到希拉里的项链，将其还给湖畔镇的希拉里。",
    [3761] = "收集20份安戈洛的泥土，把它们交给雷霆崖的格德。",
    [3762] = "与雷霆崖的大德鲁伊哈缪尔·符文图腾谈一谈。",
    [3763] = "与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。",
    [3764] = "收集20份安戈洛的泥土，把它们交给达纳苏斯的耶纳尔。",
    [3765] = "到奥伯丁的戈沙拉·夜语那儿去。",
    [3781] = "将大德鲁伊的草种购买券交给达纳苏斯城塞纳里奥区的玛斯雷·驭熊者。",
    [3782] = "将草种购买券交给雷霆崖的巴珊娜·符文图腾。",
    [3783] = "为永望镇的乌米收集10张厚雪人毛皮。",
    [3784] = "与雷霆崖的大德鲁伊哈缪尔·符文图腾谈一谈。",
    [3785] = "用一个常青袋、一包萨伦迪斯种子以及两份安戈洛的泥土来尝试种植晨光麦。 将10株晨光麦交给达纳苏斯的玛斯雷·驭熊者。",
    [3786] = "用一个常青袋、一包萨伦迪斯种子以及两份安戈洛的泥土来尝试种植晨光麦。 将10株晨光麦交给雷霆崖的巴珊娜·符文图腾。",
    [3787] = "与羽月要塞的奎恩提斯谈一谈。",
    [3788] = "与羽月要塞的奎恩提斯谈一谈。",
    [3789] = "与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。",
    [3790] = "与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。",
    [3791] = "将10株晨光麦交给羽月要塞的奎恩提斯。",
    [3801] = "如果你想要得到进入这座城市主城区的钥匙，就去和弗兰克罗恩·铸铁谈一谈。",
    [3802] = "杀掉弗诺斯·达克维尔并拿回战锤铁胆。把铁胆之锤拿到索瑞森神殿去，将其放在弗兰克罗恩·铸铁的雕像上。",
    [3821] = "到燃烧平原去找到沙妮·长齿。",
    [3822] = "从克罗格鲁尔手中拿回沙妮的鼻环，把它还给卡加斯的萨特拉克。搜寻巨槌石的每一处山洞和矿井。",
    [3823] = "杀掉15个火腹食人魔法师、7个火腹食人魔和7个火腹蛮兵，完成任务之后向奥拉留斯报告。",
    [3824] = "找到戈泰什，他应该在巨槌石西面的某处。杀掉戈泰什并把他的头颅交给燃烧平原的奥拉留斯。",
    [3825] = "把戈泰什的头颅放在巨槌石的山顶上。找一块软土堆把串着头颅的长矛插上去就可以了。",
    [3841] = "与千针石林的奎恩丁谈一谈。",
    [3842] = "将2瓶次级坚韧药剂交给千针石林的奎恩丁。",
    [3843] = "带着这枚脆弱的小精龙卵去辛特兰，与阿格纳谈一谈，但是你一定要在它还有生命力的时候赶到，在蛋里的小生命夭折之前，你只有1小时的时间。",
    [3844] = "在池塘附近查找与搁浅的小艇有关的线索。",
    [3845] = "查看袋子里的东西，然后将它们交给物主。",
    [3861] = "找一些特殊的鸡饲料，把它交给友好的小鸡。当你找到小鸡的时候，在喂食它之前对它做出高兴的表情。（使用/cheer命令）",
    [3881] = "将食物箱和研究设备交给安戈洛环形山的威利德·马绍尔。",
    [3882] = "将8根恐龙骨头交给安戈洛环形山的斯巴克·尼米尔。",
    [3883] = "使用采集瓶从安戈洛环形山的某个格里什虫巢的孵化室中收集一份巢穴侧壁的样本，在有悬挂着的虫卵的房间里收集样本。 将虫穴内壁样本交给安戈洛环形山的霍莱伊·马绍尔。",
    [3884] = "将日记还给安戈洛环形山中的威利德·马绍尔。",
    [3901] = "杀掉12个断骨骷髅，然后回到丧钟镇的暗影牧师萨维斯那里。",
    [3902] = "在丧钟镇及临近地区搜寻6件破烂装备，把它们交给亡灵卫兵萨尔坦。",
    [3903] = "与米莉·奥斯沃斯谈一谈。",
    [3904] = "收集8箱米莉的葡萄，把它们交给北郡修道院的米莉·奥斯沃斯。",
    [3905] = "将葡萄出货单交给北郡修道院的尼尔斯修士。",
    [3906] = "到黑石山脉的采石场去干掉征服者派隆，然后向桑德哈特回报。",
    [3907] = "进入黑石深渊并找到伊森迪奥斯。杀掉它，然后把你找到的信息汇报给桑德哈特。",
    [3908] = "把林克的剑交给冬泉谷的多诺瓦·雪山。",
    [3909] = "去菲拉斯找格雷甘·山酒。从他那里问到获取视灵药剂的方法，然后向冬泉谷的多诺瓦·雪山复命。",
    [3912] = "在加基森镇外的墓地中使用视灵药剂，然后按照多诺瓦的指示找到加里杨。",
    [3913] = "复活，然后寻找加里杨让你去找的那块墓碑。",
    [3914] = "把林克的强化之剑交给安戈洛尔环形山的林克。",
    [3921] = "将损坏的主动式负载平衡器交给维妮·布特巴克。",
    [3922] = "把15个高强度齿轮交给贫瘠之地的维妮·布特巴克。",
    [3923] = "把破碎的主动式负载平衡器交给奥格瑞玛的雷里·格里斯高布。",
    [3924] = "把主动式负载平衡器说明书交给奥格瑞玛的雷里·格里斯高布。",
    [3941] = "到马绍尔营地那里的山洞中去找科琳。",
    [3942] = "到费伍德森林去找艾瑞丹·蓝风。",
    [3961] = "把亚奎门塔斯的银图腾交给马绍尔营地里的林克。",
    [3962] = "到马绍尔营地南边的火羽山去。 找到火焰使者，并使用图腾除掉它的防护光环。在击败它之后从洞中取得金色火焰。",
    [3981] = "在黑石深渊里找到指挥官哥沙克。 在那幅草图上画着的是一个铁栏后面的兽人，也许你应该到某个类似监狱的地方去找找看。",
    [3982] = "保护哥沙克。",
    [4001] = "与卡兰·巨锤谈一谈，收集关于绑架公主铁炉堡公主茉艾拉·铜须这一事件的情报。将情报反馈给奥格瑞玛城里的萨尔。 哥沙克提到过卡兰被关在附近的某个牢房中。",
    [4002] = "如果你准备好要接受萨尔所安排的任务，就去找他谈一谈。",
    [4003] = "杀掉达格兰·索瑞森大帝，然后将铁炉堡公主茉艾拉·铜须从他的邪恶诅咒中拯救出来。",
    [4004] = "向萨尔报告！",
    [4005] = "把阿奎尔之书、银爪和铁树之心带到塔纳利斯去。 使用这本书召唤亚奎门塔斯。 在图腾完成之后，把它交给马绍尔营地的科琳。",
    [4021] = "将克罗姆扎军旗的碎片交给十字路口西边的雷戈萨·死门。",
    [4022] = "向塞勒斯·萨雷芬图斯展示你从威拉罗克·温布雷那里得到的黑龙皮。",
    [4023] = "向塞勒斯·萨雷芬图斯证明你的价值。 你感觉到塞勒斯似乎对你不屑一顾。",
    [4024] = "到黑石深渊去杀掉贝尔加。 你只知道这个巨型怪物住在黑石深渊的最深处。记住你要使用特殊的黑龙皮从贝尔加的尸体上采集烈焰精华。 将你采集到的烈焰精华交给塞勒斯·萨雷芬图斯。",
    [4061] = "到燃烧平原去为塞朵拉·穆瓦丹尼收集10块断裂的元素碎片。 塞朵拉曾经说过，那里的机械傀儡和元素生物是这种碎片的主要来源。",
    [4062] = "将元素碎片样本交给鲁特维尔·沃拉图斯。 塞朵拉说鲁特维尔就在东边的一处营地里。",
    [4063] = "找到并杀掉傀儡统帅阿格曼奇，将他的头交给鲁特维尔。你还需要从守卫着阿格曼奇的狂怒傀儡和战斗傀儡身上收集10块完整的元素核心。",
    [4081] = "到黑石深渊去消灭那些邪恶的侵略者！ 军官高图斯要你去杀死15个铁怒卫士、10个铁怒狱卒和5个铁怒步兵。完成任务之后回去向他复命。",
    [4082] = "到黑石深渊去消灭那些邪恶的侵略者！ 高图斯军阀要你杀死10个铁怒医师,、10个铁怒士兵和10个铁怒军官。完成任务之后回去向他复命。",
    [4084] = "为费伍德森林的艾瑞丹·蓝风收集11只银爪和1颗铁树之心。",
    [4101] = "收集15颗血琥珀，把它们交给费伍德森林的阿拉珊蒂丝·银空。",
    [4102] = "收集15颗血琥珀，把它们交给费伍德森林的梅贝丝·河风。",
    [4120] = "菲拉斯莫沙彻营地的塔罗·刺蹄要你去费伍德森林杀掉12头怒爪灰熊和12头魔爪掠夺者。",
    [4121] = "押送你的囚犯格拉克·洛克鲁布。穿过燃烧平原和黑石山脉，一直走到灼热峡谷。 雷克斯洛特曾经告诉过你，他会让他的人等在黑石山脉的另外一边准备接收格拉克。 另外，你还要把瑟银镣铐一并还给雷克斯洛特。",
    [4122] = "到燃烧平原去找到格拉克·洛克鲁布。你回忆起雷克斯洛特曾经提起过，格拉克应该是在一座大型的黑石要塞中。 当你找到格拉克·洛克鲁布之后，用瑟银镣铐把他铐起来，然后将其带回灼热峡谷。雷克斯洛特会让他的部下等在那里接应你。",
    [4123] = "把山脉之心交给燃烧平原的麦克斯沃特·尤博格林。",
    [4124] = "和羽月要塞的基恩诺·火花谈一谈。",
    [4125] = "找到信使的小船，你应该在菲拉斯的南部海岸线上展开搜索。",
    [4126] = "把遗失的雷酒秘方带给卡拉诺斯的拉格纳·雷酒。",
    [4127] = "回到羽月要塞，给基恩诺·火花看看你找到的这把被丢弃的小刀。",
    [4128] = "和拉格纳·雷酒谈一谈。",
    [4129] = "把被丢弃的小刀交给羽月要塞的奎恩提斯。",
    [4130] = "和羽月要塞的基恩诺·火花谈一谈。",
    [4131] = "在菲拉斯南部地区的木爪豺狼人营地里寻找信使的下落或者信使的物品。",
    [4132] = "到黑石深渊去杀掉安格弗将军！当任务完成之后向军官高图斯复命。",
    [4133] = "与卡加斯的暗法师薇薇安·拉格雷谈一谈。",
    [4134] = "把遗失的雷酒秘方交给卡加斯的薇薇安·拉格雷。",
    [4135] = "现在你已经知道了拉斯卡尔的去向，那么你最好到痛苦深渊去寻找他，或者至少是他的尸体。根据便笺上的信息，那个地方应该在木爪豺狼人营地的南边。",
    [4136] = "把雷布里的头颅交给燃烧平原的尤卡·斯库比格特。",
    [4141] = "从安戈洛尔环形山的血瓣花猛击者和血瓣花掠夺者身上收集15个血瓣花，然后向穆尔金回复。",
    [4142] = "把血瓣花交给菲拉斯的格雷甘·山酒。",
    [4143] = "收集5份阿塔莱之雾的样本，然后向安戈洛环形山的穆尔金复命。",
    [4145] = "为马绍尔营地里的拉瑞安杀掉5个血瓣花鞭笞者、5个血瓣花捕兽者、5个血瓣花掠夺者和5个血瓣花猛击者。",
    [4146] = "收集5份阿塔莱之雾的样本，然后将它们送到马绍尔营地的拉瑞安那里。",
    [4147] = "到棘齿城去，在玛尔冯·瑞文斯克的车间里找到他。",
    [4161] = "为多兰纳尔的扎瑞恩收集7条小蜘蛛腿。",
    [4181] = "如果你想要对地精工程学有更多了解，就把工程学教材交给加基森的尼克斯·斯普克斯宾。",
    [4182] = "杀掉15条黑色小龙、10条黑色龙兽和1条黑色幼龙。当你完成任务之后就向赫林迪斯·河角回报。",
    [4183] = "把赫林迪斯·河角的信交给湖畔镇的所罗门镇长。",
    [4184] = "到暴风城去把所罗门的求援信交给伯瓦尔·弗塔根公爵。 伯瓦尔在暴风要塞里。",
    [4185] = "与女伯爵卡特拉娜·普瑞斯托谈话，然后再与伯瓦尔·弗塔根公爵谈话。",
    [4186] = "把伯瓦尔的命令交给湖畔镇的所罗门镇长。",
    [4201] = "将4份格罗姆之血、10块巨型银矿和装满水的娜玛拉之瓶交给黑石深渊的娜玛拉小姐。",
    [4223] = "和燃烧平原的麦克斯韦尔元帅谈一谈。",
    [4224] = "和狼狈不堪的约翰谈谈来了解温德索尔元帅的命运，然后回到麦克斯韦尔元帅那里。 你想起麦克斯韦尔元帅说过他在一个北面的洞穴那里。",
    [4241] = "到西北部的黑石山脉去，在黑石深渊中找到温德索尔元帅的下落。 狼狈不堪的约翰曾告诉你说温德索尔被关进了一个监狱。",
    [4242] = "把这个坏消息传达给麦克斯韦尔元帅。",
    [4243] = "在安戈洛环形山找到A-Me 01。",
    [4244] = "找到一个秘银外壳，然后回到安戈洛环形山的A-Me 01身边。",
    [4245] = "将A-Me 01交给安戈洛环形山的卡尔纳·雷塔维。",
    [4261] = "护送艾雷到灰谷，然后和灰谷东部的林歌神殿中的凯尼斯·静风谈一谈。",
    [4262] = "杀掉征服者派隆，然后向加琳达复命。 加琳达告诉过你，派隆守在采矿场中，也许你应该去那里找找。",
    [4263] = "在黑石深渊里找到伊森迪奥斯，然后把他干掉！",
    [4264] = "温德索尔元帅也许会对你手中的东西感兴趣。毕竟，希望还没有被完全扼杀。",
    [4265] = "将拉斯卡尔安全护送到祖卡什虫巢外。 回到羽月要塞的基恩诺·火花那儿，告诉他拉斯卡尔还活着，且状况良好。",
    [4266] = "与羽月要塞的珊蒂斯·羽月谈一谈。",
    [4267] = "把拉斯卡尔的报告交给达纳苏斯的格拉希娜·灵风。",
    [4281] = "将未递送的包裹交给萨兰纳尔驿站的法芬德尔。",
    [4282] = "找回温德索尔元帅遗失的情报。 温德索尔元帅确信那些情报在安格弗将军和傀儡统帅阿格曼奇的手里。",
    [4283] = "奥拉留斯想要50枚黑石徽章。在燃烧平原的兽人身上应该可以找到那些徽章。",
    [4284] = "收集红色能量水晶、蓝色能量水晶、黄色能量水晶和绿色能量水晶各7块，把它们交给马绍尔营地里的科琳。",
    [4285] = "在安戈洛尔环形山找到北部水晶塔。",
    [4286] = "到黑石深渊去找到20个黑铁挎包。当你完成任务之后，回到奥拉留斯那里复命。你认为黑石深渊里的黑铁矮人应该会有这些黑铁挎包。",
    [4287] = "在安戈洛尔环形山找到东部水晶塔。",
    [4288] = "在安戈洛尔环形山找到西部水晶塔。",
    [4289] = "将2块安戈洛猩猩的皮、2块安戈洛大猩猩的皮和2块安戈洛巨猩猩的皮交给安戈洛环形山入口处的托尔瓦·寻路者。",
    [4290] = "找到拉克维刚刚猎杀的动物的尸体，从尸体上偷取一块蛇颈龙肉块，然后回到安戈洛环形山的托尔瓦·寻路者那里。",
    [4291] = "将2份暴掠龙信息素交给安戈洛尔环形山入口附近的托尔瓦·寻路者。",
    [4292] = "使用托尔瓦的麻袋中的东西召唤拉克维并打败它。将拉克维的头颅交给安戈洛环形山入口处的托尔瓦·寻路者。",
    [4293] = "从费伍德的软泥怪身上收集费伍德软泥怪样本，然后使用幽暗城的化学家弗雷身旁的测试设备来检测你所收集的样本中哪一份被腐化的程度最深。给化学家弗雷带去5个被腐化的费伍德样本。",
    [4294] = "从安戈洛尔环形山那里任何泥浆怪身上收集安戈洛泥浆怪样本。使用幽暗城的化学家弗雷身旁的测试仪器来检验你所采集到的样本的纯度。把5份纯净的安戈洛样本送到化学家弗雷那里去。",
    [4296] = "把石板拓文交给燃烧平原的麦克斯沃特·尤博格林。",
    [4297] = "将5块银鬃捕猎者的肉交给辛特兰的阿格纳。",
    [4298] = "与辛特兰的阿格纳谈一谈。",
    [4300] = "将8只白色暴掠龙爪交给奥格瑞玛的杰斯雷蒙。",
    [4301] = "把尤尔查的毛皮交给安戈洛环形山入口处的托尔瓦·寻路者。",
    [4321] = "过一会再和科琳说话。",
    [4322] = "帮助温德索尔元帅拿回他的装备并救出他的朋友。当你成功之后就回去向麦克斯韦尔元帅复命。",
    [4324] = "与燃烧平原的尤卡·斯库比格特谈一谈。",
    [4341] = "去黑石深渊找到卡兰·巨锤。 国王提到卡兰在那里负责看守囚犯——也许你应该在监狱附近寻找他。",
    [4342] = "听卡兰·巨锤说他的故事。",
    [4361] = "回到铁炉堡，把这个坏消息带给国王麦格尼·铜须。",
    [4362] = "回到黑石深渊，从达格兰·索瑞森大帝的魔掌中救出铁炉堡公主茉艾拉·铜须。",
    [4363] = "回到铁炉堡去，与国王麦格尼·铜须谈一谈。",
    [4402] = "收集10个仙人掌果，把它们交给戈加尔。你记得他说可以在仙人掌上收集到这种果子。",
    [4421] = "杀掉11个碧火魔仆、9个碧火巡影者、9个碧火潜行者和萨瓦瑟拉斯。任务完成之后回到费伍德森林的艾瑞丹·蓝风处复命。",
    [4441] = "到达纳苏斯去，用艾瑞丹的瓶子收集月神殿中的祝福之水，然后回到艾瑞丹那儿。",
    [4442] = "过一会儿再与艾瑞丹对话。",
    [4449] = "杀掉8个黑铁地质学家，并将15块丝绸交给灼热峡谷里那个被锁在厕所中的矮人。",
    [4450] = "把古德斯迪尔的账本和上面所列的物品交给塔纳利斯的克林科·古德斯迪尔。",
    [4451] = "搜寻灼热峡谷并找到一个可以插入这把格里塞特厕所钥匙的锁眼。",
    [4485] = "与暴风城的达索瑞恩·拉尔谈一谈。",
    [4486] = "与暴风城的达索瑞恩·拉尔谈一谈。",
    [4487] = "与棘齿城的斯坦哈德·法尔杉谈一谈。",
    [4488] = "与棘齿城的斯坦哈德·法尔杉谈一谈。",
    [4489] = "与棘齿城的斯坦哈德·法尔杉谈一谈。",
    [4490] = "与棘齿城的斯坦哈德·法尔杉谈一谈，学习召唤地狱战马的能力。",
    [4491] = "把林格带回马绍尔营地的斯普拉格·弗劳克身边。 如果林格晕倒了，就用斯普拉格的水壶让他恢复。",
    [4492] = "在火羽山找到林格。",
    [4493] = "与加基森的炼金师匹斯特苏格谈一谈。",
    [4494] = "与加基森的炼金师匹斯特苏格谈一谈。",
    [4495] = "在北边的洞穴附近找到埃沃隆。",
    [4496] = "把一份格里什信息素和5份安戈洛的泥土样本交给加基森的炼金师匹斯特苏格。",
    [4501] = "杀掉10只翼手龙和15只狂怒的翼手龙，然后向马绍尔营地的斯普拉格·弗劳克报告。",
    [4502] = "到安戈洛环形山的火山中去，从那里的元素身上收集9份安戈洛灰烬，把它们交给棘齿城的莉芙·雷兹菲克斯。",
    [4503] = "为马绍尔营地的希兹尔收集8块精细的双帆龙鳞片和8块精细的翼手龙鳞片。",
    [4504] = "帮加基森的特兰雷克收集12块极度粘稠的沥青。",
    [4505] = "从碧火萨特的月亮井中收集一份被腐化的水的样本，把它交给血毒哨所的温娜·哈萨德。",
    [4506] = "把温娜的小猫带到堕落的月亮井旁边，把猫放出来，然后把它还给温娜。 当你回到温娜那里之后，点击猫就可以将它还给温娜。",
    [4507] = "召唤格里什皇后，然后击败她。 把格里什皇后的大脑交给加基森的炼金师匹斯特苏格。",
    [4508] = "把匹斯特苏格的安戈洛报告交给达纳苏斯的格拉希娜·灵风。",
    [4509] = "把匹斯特苏格的安戈洛报告交给奥格瑞玛斯的基尔兹宾·鼓眼。",
    [4510] = "把银行赠券交给达纳苏斯银行的伊迪瑞娜。",
    [4511] = "把银行赠券交给奥格瑞玛银行的卡鲁斯。",
    [4512] = "将6瓶被诅咒的软泥怪样本和6瓶被污染的软泥怪样本交给铁炉堡的拉里斯·空轮。",
    [4513] = "将10个纯净样本瓶交给铁炉堡的拉里斯·空轮。 如果你无法找到它们的话，不妨到拉里斯那里去再打听一些线索。",
    [4521] = "费伍德森林的特鲁尔·法贝恩要你去冬泉谷猎杀15头狂怒的枭兽和15头蓬毛枭兽。",
    [4542] = "把紧急信件交给乱风岗的峭壁卫兵图林·长角。",
    [4581] = "把辛德瑞尔的便笺交给林歌神殿里的凯尼斯·静风。",
    [4621] = "杀死藏宝海湾的舰队指挥官卡拉·海角和大财主里维加兹，然后回到荆棘谷海边的红雾号上去，向舰队指挥官菲尔拉伦复命。",
    [4641] = "与高内克谈一谈。卡尔图克在你的地图上标出了他的位置，并告诉你高内克居住在西边的大兽穴中。",
    [4642] = "把一块融合的软泥怪样本交给幽暗城的化学家弗雷。",
    [4681] = "在奥伯丁西面海水中的海龟骸骨那里取回海龟残骸，然后与奥伯丁的温尼斯·布莱葛谈一谈。",
    [4701] = "到黑石塔去摧毁那里的座狼源头。当你离开的时候，赫林迪斯喊出了一个名字：哈雷肯。这个词就是兽人语中“座狼”的意思。",
    [4721] = "费伍德森林的特鲁尔·法贝恩要你去冬泉谷猎杀10头狂暴枭兽。",
    [4722] = "把海龟的残骸交给奥伯丁的温尼斯·布莱葛。",
    [4723] = "把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。",
    [4724] = "杀死血斧座狼的领袖，哈雷肯。",
    [4725] = "把有奇怪标记的箱子交给奥伯丁的温尼斯·布莱葛。",
    [4726] = "将龙灵采集器900型和8份雏龙精华交给燃烧平原烈焰峰的丁奇·斯迪波尔。",
    [4727] = "把海龟的残骸交给奥伯丁的温尼斯·布莱葛。",
    [4728] = "把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。",
    [4729] = "到黑石塔去找到血斧座狼幼崽。使用笼子来捕捉这些凶猛的小野兽，然后把笼中的座狼幼崽交给基布雷尔。",
    [4730] = "把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。",
    [4731] = "把有奇怪标记的箱子交给奥伯丁的温尼斯·布莱葛。",
    [4732] = "把海龟的残骸交给奥伯丁的温尼斯·布莱葛。",
    [4733] = "把海洋生物的骸骨交给奥伯丁的温尼斯·布莱葛。",
    [4734] = "在孵化间对着某颗龙蛋使用龙蛋冷冻器初号机。",
    [4735] = "将电动采集模块和8颗收集到的龙蛋交给燃烧平原烈焰峰的丁奇·斯迪波尔。",
    [4736] = "与贫瘠之地的梅纳拉·沃伦德谈一谈。",
    [4737] = "与贫瘠之地的梅纳拉·沃伦德谈一谈。",
    [4738] = "与贫瘠之地的梅纳拉·沃伦德谈一谈。",
    [4739] = "与贫瘠之地的梅纳拉·沃伦德谈一谈。",
    [4740] = "找到并杀死名为莫克迪普的鱼人。它守护着位于奥伯丁南部海岸的鱼人营地。 向奥伯丁的哨兵戈琳达·纳希恩报告莫克迪普的死讯。",
    [4741] = "费伍德森林的特鲁尔·法贝恩要你去冬泉谷猎杀13头月光枭兽。",
    [4742] = "找到三块命令宝石：燃棘宝钻、尖石宝钻和血斧宝钻。把它们和原始晋升印章一起交给维埃兰。 可能携带者三块宝石的将军是：燃棘氏族的指挥官沃恩、尖石氏族的欧莫克大王，以及血斧氏族的维姆萨拉克。",
    [4743] = "到尘泥沼泽中的巨龙沼泽去。找到上古老龙埃博斯塔夫，对他发起无情的攻击，直到他的意志被摧毁。 此时，你必须尽快将未铸造的晋升印章放在这条龙面前，并使用龙力宝珠控制他的躯体，强迫他将黑龙的烈焰喷向未铸造的晋升印章！",
    [4761] = "与奥伯丁的桑迪斯·织风谈一谈。",
    [4762] = "到奥伯丁的北面去，沿着壁泉河到达第一个瀑布处，从瀑布下的水潭中取出一份水样。 将壁泉河水样交给奥伯丁的桑迪斯·织风。",
    [4763] = "在空的净化碗里盛满奥伯丁月亮井的井水。 在黑木熊怪的北部营地里收集水果、坚果和谷物各一份。 将水和三种食物混合起来，放置在壁泉河附近的营火边，这样就会召来唤引诱熊怪堕落的萨特。 取回堕落护符，将它交给奥伯丁的桑迪斯·织风。",
    [4764] = "将末日扣环交给燃烧平原的玛亚拉·布莱特文。",
    [4765] = "将瑞治维尔的箱子交给暴风城的雷明顿·瑞治维尔。",
    [4766] = "与燃烧平原的玛亚拉·布莱特文谈一谈。",
    [4767] = "将10颗双足飞龙的蛋交给乱风岗的艾鲁。",
    [4768] = "将黑暗石板交给卡加斯的暗法师薇薇安·拉格雷。",
    [4769] = "与卡加斯的暗法师薇薇安·拉格雷谈一谈。",
    [4770] = "护送波卡·雨山走出风巢，然后和白沙岗哨的莫特加·火鬃谈一谈。",
    [4771] = "将黎明先锋放在通灵学院的观察室里。打败维克图斯，然后回到贝蒂娜·比格辛克那里去。",
    [4781] = "将一块金锭交给荆棘谷的希兹克·古斯提。",
    [4782] = "回到贫瘠之地的梅纳拉·沃伦德那里。",
    [4783] = "将10瓶怨怒萨特之血和1块次级地狱火石交给贫瘠之地的梅纳拉·沃伦德。",
    [4784] = "将一些优质金线、2块闷烧煤和一块灵魂碎片交给贫瘠之地的梅纳拉·沃伦德。",
    [4786] = "等待梅纳拉·沃伦德织好披风，然后跟她谈一谈。",
    [4787] = "将远古之卵交给塔纳利斯的叶基亚。",
    [4788] = "将第五块和第六块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。",
    [4808] = "把丁奇的信交给菲诺克。",
    [4809] = "将8支完整的冰风奇美拉角交给菲诺克。",
    [4810] = "把菲诺克的包裹交给燃烧平原的丁奇·斯迪波尔。",
    [4811] = "到奥伯丁的东边去，沿着黑海岸东部边界的山脉寻找一颗巨大的红色水晶，然后向奥伯丁的哨兵戈琳达·纳希恩汇报你的发现。",
    [4812] = "在奥伯丁月亮井中把空水瓶装满，然后调查黑海岸东部山脉的红水晶。",
    [4813] = "向奥伯丁的哨兵哨兵戈琳达·纳希恩报告你的发现。",
    [4821] = "把异型卵交给乱风岗的哈加尔·雷蹄。",
    [4841] = "杀掉12个加拉克斥候、10个加拉克争斗者和6个加拉克逐风者，然后向乱风岗的峭壁卫兵图林·长角复命。",
    [4842] = "根据多诺瓦·雪山的指示行动，然后回到她那里报告。",
    [4861] = "在冬泉谷的南部寻找加隆·石矛的被破坏的营帐，以及他的补给物资。",
    [4862] = "到黑石塔去为基布雷尔收集15枚尖塔蜘蛛卵。 听说那些蜘蛛周围有许多这样的卵。",
    [4863] = "找到加隆·石矛的马车。",
    [4864] = "从雪地中拾起加隆的补给物资，然后寻找盗取加隆所说的护符的枭兽。 将加隆的补给物资和蓝色羽毛护符交给冬泉谷的加隆·石矛。",
    [4865] = "向莫特加·火鬃汇报你的发现。",
    [4866] = "你可以在黑石塔的中心地带找到烟网蛛后。与她战斗，让她在你体内注入毒汁。如果你有能力的话，就杀死她吧。当你中毒之后，回到狼狈不堪的约翰那儿，他会从你的身体里抽取这些“蛛后的乳汁”。",
    [4867] = "阅读瓦罗什的卷轴。将瓦罗什的蟑螂交给他。",
    [4881] = "将暗杀计划通知给白沙岗哨的卡纳提·灰云。",
    [4882] = "把蓝羽项链交给血毒岗哨的特鲁尔·法贝恩。",
    [4883] = "把蓝羽项链交给纳拉·蛮鬃。",
    [4901] = "在兰莎尔拉尝试激活艾露恩祭坛的过程中保护她。然后将你的发现报告给鲁瑟兰村的艾瑞拉斯·琥珀。",
    [4902] = "与达纳苏斯的大德鲁伊范达尔·鹿盔谈一谈。",
    [4903] = "杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。",
    [4904] = "护送拉克塔·风歌离开恐怖图腾营地，然后与乱风岗的萨利亚谈一谈。",
    [4906] = "费伍德森林的艾瑞丹·蓝风要你去杀掉8个碧火唤魔者、8个碧火背叛者、8个碧火欺诈者和萨瓦里克。任务完成之后回到艾瑞丹那里复命。",
    [4907] = "与丁奇·斯迪波尔谈一谈。",
    [4921] = "找到曼科里克的妻子，然后回到十字路口找他。",
    [4941] = "和奥格瑞玛的伊崔格谈一谈。讨论完毕后，咨询萨尔的意见。 你回忆起曾在萨尔的大厅中见过伊崔格。",
    [4961] = "杀死宝珠之魔，然后与塔贝萨谈一谈。",
    [4962] = "带上地狱犬红宝石到凄凉之地去，用它捕获一只地狱犬的灵魂。成功之后，将地狱犬红宝石和被禁锢的地狱犬灵魂交给贫瘠之地的梅纳拉·沃伦德。",
    [4963] = "带上地狱火绿宝石到凄凉之地去，用它捕获一个地狱火的灵魂。成功之后，将地狱火绿宝石和被禁锢的地狱火灵魂交给贫瘠之地的梅纳拉·沃伦德。",
    [4964] = "等待梅纳拉·沃伦德完成达奥拉赫宝珠，然后再与她谈一谈。",
    [4965] = "与贫瘠之地的梅纳拉·沃伦德谈一谈。",
    [4966] = "保护卡纳提·灰云免受半人马的袭击。",
    [4967] = "与贫瘠之地的梅纳拉·沃伦德谈一谈。",
    [4968] = "与贫瘠之地的梅纳拉·沃伦德谈一谈。",
    [4969] = "与贫瘠之地的梅纳拉·沃伦德谈一谈。",
    [4970] = "收集5块碎齿熊肉和5块冰风奇美拉肉，把它们交给冬泉谷的雷沃·霜翼。",
    [4971] = "在安多哈尔的一处仓库附近使用时光置换器，使时光寄生虫现身。 杀掉15只时光寄生虫，然后将时光置换器还给西瘟疫之地安多哈尔旅店的克罗米。",
    [4972] = "在安多哈尔城中四处散落的保险箱里找到5只安多哈尔怀表，然后把它们交给西瘟疫之地安多哈尔旅店里的克罗米。",
    [4973] = "在安多哈尔城的废墟里找到5只安多哈尔怀表，然后把它们交给西瘟疫之地安多哈尔旅店里的克罗米。",
    [4974] = "去<name>石塔杀死大酋长雷德·<name>手，带着他的头颅返回奥格瑞玛。",
    [4975] = "等待梅纳拉·沃伦德完成诺奥拉赫宝珠，然后再与她谈一谈。",
    [4976] = "将净化过的地狱火宝珠交给贫瘠之地的梅纳拉·沃伦德。",
    [4981] = "到黑石塔去查明比修的下落。",
    [4982] = "找到比修的装置并把它们还给她。你记得她说过她把装置藏在城市的最底层。",
    [4983] = "把比修的侦查报告交给卡加斯的雷克斯洛特。",
    [4984] = "消灭8只生病的狼，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。",
    [4985] = "消灭8只生病的灰熊，然后去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。",
    [4986] = "根据雕文橡木枝上面所附加的魔法，这个牛头人德鲁伊本来准备把它交给达纳苏斯的塞纳里奥议会。看来你应该到那里去找一个德鲁伊，并寻求他的帮助。",
    [4987] = "根据雕文橡木枝上面所附加的魔法，这个牛头人德鲁伊本来准备把它交给雷霆崖的塞纳里奥议会。看来你应该到那里去找一个德鲁伊，并寻求他的帮助。",
    [5001] = "找到比修的装置并把它们还给她。祝你好运！",
    [5002] = "到燃烧平原去，把比修的情报交给麦克斯韦尔元帅。",
    [5021] = "这个女人的幽灵告诉你她要送出一只包裹。她说那只包裹就在她的马旁边。至于马在哪里或者包裹要送到哪里去，她却根本没有说。",
    [5022] = "与暴风城的皇家代理人巴瑟罗尔协商，查找到艾玛·费尔斯通的下落。通常在市政厅里都有一个人口普查官。",
    [5023] = "与幽暗城的皇家管理人巴哈乌斯协商，查找杰雷米亚·费尔斯通的下落。通常在公会注册处附近会有一个人口普查官。",
    [5041] = "找到十字路口的补给箱，把它还给贫瘠之地的索克。",
    [5047] = "与永望镇的玛雷弗斯·暗锤谈一谈。",
    [5048] = "找到暴风城的艾玛并弄清她是否就是艾玛·费尔斯通。如果是的话，那么她可能想要拿到詹妮丝·费尔斯通给她的包裹。",
    [5049] = "在幽暗城找到杰雷米亚·派森并查明他是否就是你要找的杰雷米亚·费尔斯通。如果他是的话，那么他可能会想要拿到詹妮丝·费尔斯通寄给他的包裹。",
    [5050] = "把半个好运护符还给西瘟疫之地的詹妮丝·费尔斯通。",
    [5051] = "在西瘟疫之地的费尔斯通农场某地找到另外一半好运护符，并把两半护符合并。 把好运护符交给西瘟疫之地费尔斯通农场的詹妮丝·费尔斯通。",
    [5052] = "给陶拉祖营地的碎牙带去一块血岩碎片。 如果你想要他赐予你阿迦玛甘的力量，就搜集更多的血岩碎片。",
    [5054] = "永望镇的斯托姆·影蹄想要你去杀死尤西乌斯。",
    [5055] = "永望镇的斯托姆·影蹄想要你去杀死布鲁米兰。",
    [5056] = "永望镇的斯托姆·影蹄想要你去杀死希洛塔姆。",
    [5057] = "把斯托姆·影蹄的徽记交给雷霆崖的梅洛·石蹄。",
    [5061] = "回到达纳苏斯，让玛斯雷·驭熊者看看你的海狮坠饰。",
    [5062] = "收集10支火岩龙舌兰，然后去找雷霆崖长者高地的玛加萨·恐怖图腾。",
    [5063] = "为了制造血色学者之帽，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，5根磨损的憎恶缝合线，8块奥术水晶，5根魔化红线。 另外你还必须支付50金币的制作费用。",
    [5064] = "在黑云峰拿到三封密信。",
    [5065] = "把第三块和第四块摩沙鲁石板交给塔纳利斯的勘查员詹斯·铁靴。",
    [5066] = "找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。",
    [5067] = "为了制造阿卡纳护腿，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，5根磨损的憎恶缝合线，5块奥金锭，5份莱斯·霜语的防腐液。 另外你还必须支付50金币的制作费用。",
    [5068] = "为了制造嗜血胸甲，你必须将下列物品交给玛雷弗斯·暗锤：1块比斯巨兽的皮，10根磨损的憎恶缝合线，5块奥金锭，5块暗影之皮。 另外你还必须支付50金币的制作费用。",
    [5081] = "到黑石塔去消灭指挥官沃恩、欧莫克大王和维姆萨拉克。完成任务之后回到麦克斯韦尔元帅处复命。",
    [5082] = "冬泉谷的多诺瓦·雪山要你去杀死8个冬泉探路者、8个冬泉巢穴守卫和8个冬泉图腾师。",
    [5083] = "将空的火酒瓶交给冬泉谷的多诺瓦·雪山。",
    [5084] = "搜寻费伍德森林北部的死木熊怪的营帐，继续寻找线索。",
    [5085] = "将你的发现报告给多诺瓦·雪山。",
    [5086] = "为冬泉谷的多诺瓦·雪山收集3份剧毒水滴。",
    [5087] = "找到冬泉信使，阻止他们向冬泉村运送物品。",
    [5088] = "消灭阿利卡拉。把她的遗体和火岩粉交给白沙岗哨的莫特加·火鬃作为证明。",
    [5089] = "把达基萨斯将军的命令交给燃烧平原的麦克斯韦尔元帅。",
    [5090] = "找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。",
    [5091] = "找到指挥官阿什拉姆·瓦罗菲斯特。他的大本营位于奥特兰克山脉以北的冰风岗。",
    [5092] = "杀掉悔恨岭中的10个骷髅剥皮者和10个被奴役的食尸鬼。 然后向西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特复命。",
    [5093] = "找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。",
    [5094] = "找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。",
    [5095] = "找到高级执行官德灵顿。他将自己的大本营建在提瑞斯法林地和幽暗城以东的亡灵壁垒。",
    [5096] = "到血色十字军建在费尔斯通农场和达尔松之泪之间的营地去，摧毁他们的指挥帐篷。 将亡灵天灾的战旗插在营地中，然后回到西瘟疫之地亡灵壁垒的高级执行官德灵顿那儿。",
    [5097] = "使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。 在做完了标记之后，将信号火炬还给西瘟疫之地冰风岗的指挥官阿什拉姆·瓦罗菲斯特。",
    [5098] = "使用信号火炬为安多哈尔城中的四座哨塔做上标记，你必须站在哨塔门口才能成功地进行标记。 在做完了标记之后，将信号火炬还给西瘟疫之地亡灵壁垒的高级执行官德灵顿。",
    [5102] = "到黑石塔去杀掉达基萨斯将军，完成任务之后就回到麦克斯韦尔元帅那里复命。",
    [5103] = "世界上一定有人知道关于这副手套的事情，祝你好运！",
    [5121] = "冬泉谷的多诺瓦·雪山要你去击败冬泉酋长。",
    [5123] = "把潦草的日志交给冬泉谷的多诺瓦·雪山。",
    [5124] = "将6块魔化瑟银锭、2份火焰精华和4颗红宝石交给玛雷弗斯·暗锤。另外你还得把未淬火的板甲护手也交给他。",
    [5126] = "与罗拉克斯谈一谈，听听他要说什么。",
    [5127] = "到黑石塔去找到古拉鲁克。杀死他，然后用血污长矛刺入他的尸体。当他的灵魂被吸干后，这支矛就会成为穿魂长矛。 你还必须找到未铸造的符文覆饰胸甲。 将穿魂长矛和未铸造的符文覆饰胸甲都交给冬泉谷的罗拉克斯。",
    [5128] = "将潦草的日志交给费伍德森林南部的科雷克·望天。",
    [5141] = "将2套硬化蝎壳胸甲、2套硬化蝎壳手套和10片龙鳞交给艾萨拉的彼得·加林。 完成这项任务之后，你就可以学到龙鳞制皮技术了。 同时，你也将永远无法学习元素制皮技术和部族制皮技术，在决定之前先考虑清楚。",
    [5142] = "找到帕米拉·雷德帕斯。",
    [5143] = "将1件蛮皮外衣和1件蛮皮头盔交给菲拉斯的凯雷希亚·猎月。 完成这项任务之后，你就可以学到部族制皮技术了。 同时，你也将永远无法学习元素制皮技术和龙鳞制皮技术，在决定之前先考虑清楚。",
    [5144] = "将2个火焰之心、2个纯水之球、2个大地之核和2个风之气息交给灼热峡谷的萨拉·坦尼。 一旦你完成这项任务，就可以开始学习元素制皮技艺了。 同时，你也就无法再学习龙鳞制皮和部落制皮了，在你决定之前要考虑清楚。",
    [5145] = "将2套硬化蝎壳胸甲、2套硬化蝎壳手套和10片龙鳞交给荒芜之地的索卡夫·龙眼。 完成这项任务之后，你就可以学到龙鳞制皮技术了。 同时，你也将永远无法学习元素制皮技术和部族制皮技术，在决定之前先考虑清楚。",
    [5146] = "将2个火焰之心、2个纯水之球、2个大地之核和2个风之气息交给阿拉希山脉的布鲁姆·白蹄。 一旦你完成这项任务，就可以开始学习元素制皮技艺了。 同时，你也就无法再学习龙鳞制皮和部落制皮了，在你决定之前要考虑清楚。",
    [5147] = "杀死阿纳克·恐怖图腾，并向乱风岗的峭壁卫兵图林·长角出示证据。",
    [5148] = "将1件蛮皮外衣和1件蛮皮头盔交给荆棘谷的瑟伊布。 完成这项任务之后，你就可以学到部族制皮技术了。 同时，你也将永远无法学习元素制皮技术和龙鳞制皮技术，在决定之前先考虑清楚。",
    [5149] = "找到帕米拉的洋娃娃。",
    [5151] = "杀了那头野兽，把超适应齿轮和钥匙交给维兹罗。",
    [5152] = "与安多哈尔废墟南边的玛莱恩谈一谈。",
    [5153] = "把约瑟夫的结婚戒指交给安多哈尔的克罗米。",
    [5154] = "把《达隆郡的历史》交给安多哈尔的克罗米。",
    [5155] = "到加德纳尔去杀掉4个加德纳尔恶犬、4个加德纳尔守护者、6个加德纳尔精兵和6个加德纳尔祭司，然后向费伍德森林的格雷塔·苔蹄复命。",
    [5156] = "杀掉2个热能野兽和2个热能恐兽，并探索碎痕谷。然后查看凹坑中是否仍然充满了堕落的恶臭之水，完成这些任务之后，向费伍德森林中的塔诺恩·红羽复命。",
    [5157] = "把空壶拿到加德纳尔中心的月亮井去，装满井水之后再回到费伍德森林的格雷塔·苔蹄那里。",
    [5158] = "把腐化的月亮井水交给贫瘠之地的水之先知伊斯伦。",
    [5159] = "把净化过的月亮井水交给费伍德森林的格雷塔·苔蹄。",
    [5160] = "到冬泉谷去找到哈尔琳，把奥比的鳞片交给她。",
    [5161] = "要是你想继续的话，就与哈尔琳谈一谈。",
    [5162] = "与瘟疫之地的耶兹巴交谈。他居住在安多哈尔。",
    [5163] = "带着乌米的机械雪人去吓唬她的朋友： 永望镇的莱加奇（冬泉谷）、加基森的斯普琳科（塔纳利斯），还有马绍尔营地的奎克希尔（安戈洛环形山）。 当你完成任务之后，把机械雪人还给乌米。",
    [5164] = "阅读游荡者目录。",
    [5165] = "使用净化过的月亮井水熄灭暗影堡内部的四座火盆的火焰，从而破除其保护效果，然后向翡翠圣地的格雷塔·苔蹄复命。",
    [5166] = "为了铸造多彩巨龙胸甲，你必须把以下材料交给雕刻者耶兹巴： 1块多彩龙鳞。 10块闪亮的彩色龙鳞。 10份英雄之血。 10块磨损的憎恶缝合线。",
    [5167] = "为了铸造多彩挑战者腿甲，你必须把以下材料交给雕刻者耶兹巴： 1块多彩龙鳞。 10块闪亮的彩色龙鳞。 10份英雄之血。 5块暗影之皮。",
    [5168] = "把达维的圣契和雷德帕斯之盾交给卡林·雷德帕斯。",
    [5181] = "将霍古斯的颅骨和马杜克的破碎之剑交给圣光之愿礼拜堂的卡林·雷德帕斯。",
    [5201] = "雷沃·霜翼要你去杀死5个冬泉萨满祭司和5个冬泉巨熊怪。",
    [5202] = "搜寻加德纳尔，找出血红钥匙的用途。",
    [5203] = "护送亚科纳琳到莱弗治和她的装备所在的地方，然后保护她逃离暗影堡。之后，在费伍德森林找杰希尔·月弓，并告诉她刚才发生的事情。",
    [5204] = "回到加德纳尔杀了魅魔拉凯雅，然后找到特雷·莱弗治的残骸。",
    [5206] = "把5个共鸣颅骨和神秘水晶交给东瘟疫之地的卡林·雷德帕斯。",
    [5210] = "将《达隆镇全史》交给东瘟疫之地的卡林·雷德帕斯。",
    [5211] = "释放15个达隆郡居民的灵魂，然后返回卡林·雷德帕斯身边。",
    [5212] = "从斯坦索姆找回20个瘟疫肉块，并把它们交给贝蒂娜·比格辛克。你觉得斯坦索姆中的生灵都不大可能长着肉……",
    [5213] = "到斯坦索姆去探索那里的通灵塔。找到新的天灾军团档案，把它交给贝蒂娜·比格辛克。",
    [5214] = "找到艾兹拉·格里姆在斯坦索姆的烟草店，并从中找回一盒格里姆的优质香烟，把它交给烟鬼拉鲁恩。",
    [5215] = "与西瘟疫之地冰风岗的高阶牧师玛多妮尔谈一谈。",
    [5216] = "到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。",
    [5217] = "把费尔斯通农场的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。",
    [5219] = "到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带达尔松之泪的空瓶来采集瘟疫之锅中的毒药样本。",
    [5220] = "把达尔松之泪的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。",
    [5222] = "到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带嚎哭鬼屋的空瓶来采集瘟疫之锅中的毒药样本。",
    [5223] = "把嚎哭鬼屋的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。",
    [5225] = "到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。",
    [5226] = "把盖罗恩农场的样本瓶交给西瘟疫之地冰风岗的高阶牧师玛多妮尔。",
    [5228] = "与西瘟疫之地亡灵壁垒的暗影牧师范蒂丝谈一谈。",
    [5229] = "到西瘟疫之地的费尔斯通农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带费尔斯通农场的空瓶来采集瘟疫之锅中的毒药样本。",
    [5230] = "把费尔斯通农场的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。",
    [5231] = "到西瘟疫之地的达尔松之泪去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带达尔松之泪的空瓶来采集瘟疫之锅中的毒药样本。",
    [5232] = "把装满的达尔松眼泪之瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。",
    [5233] = "到西瘟疫之地的嚎哭鬼屋去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带嚎哭鬼屋的空瓶来采集瘟疫之锅中的毒药样本。",
    [5234] = "把嚎哭鬼屋的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。",
    [5235] = "到西瘟疫之地的盖罗恩农场去，找到并击败那里的护锅者，用它的钥匙打开瘟疫之锅。你必须随身携带盖罗恩农场的空瓶来采集瘟疫之锅中的毒药样本。",
    [5236] = "把盖罗恩农场的样本瓶交给西瘟疫之地亡灵壁垒的暗影牧师范蒂丝。",
    [5241] = "找到卡林·瑞德巴思。",
    [5242] = "杀掉米莱恩和萨莉亚，并把暗影领主费尔丹的头颅交给费伍德森林的格雷塔·苔蹄。",
    [5243] = "到北方的斯坦索姆去，寻找散落在城市中的补给箱，并收集5瓶斯坦索姆圣水。当你找到足够的圣水之后就回去向莱尼德·巴萨罗梅复命。",
    [5244] = "与坠星村的加隆·石矛谈一谈。",
    [5245] = "使用加隆的镐来寻找四块上层精灵遗物的碎片，把它们交给东瘟疫之地的奥萝拉。",
    [5246] = "在艾萨拉的辛玛洛神殿里找到神圣的上层精灵笔迹，并将它带给位于东瘟疫之地的北地哨塔附近的奥萝拉。",
    [5247] = "给东瘟疫之地的奥萝拉带去一块魔化瑟银锭、5块恢复水晶，以及一小瓶恐怖之水。",
    [5248] = "把辛玛洛水晶带回冬泉谷的凯斯利尔湖，在那里寻找一个会与你讲话的上层精灵。",
    [5249] = "找到冬泉谷的坠星村，在那里与维恩德·夜风谈一谈。",
    [5250] = "找到冬泉谷的坠星村，在那里与维恩德·夜风谈一谈。",
    [5251] = "在斯坦索姆城中找到血色十字军的档案管理员加尔福特，杀掉他，然后烧毁血色十字军档案。",
    [5252] = "和坠星村的维恩德·夜风谈一谈，了解到辛玛洛水晶所在的位置。",
    [5253] = "将辛玛洛水晶送到达纳苏斯的大德鲁伊范达尔·鹿盔那里。",
    [5261] = "与伊根·派特斯金纳谈一谈。",
    [5262] = "将巴纳扎尔的头颅交给东瘟疫之地的尼古拉斯·瑟伦霍夫公爵。",
    [5263] = "到斯坦索姆去杀掉瑞文戴尔男爵，把他的头颅交给尼古拉斯·瑟伦霍夫公爵。",
    [5264] = "和玛克斯韦尔·泰罗索斯男爵谈一谈。他就在教堂里面。",
    [5265] = "打开银色黎明宝箱，拿取你应得的奖励。",
    [5281] = "找到埃根。你只知道他在斯坦索姆附近。",
    [5282] = "对斯坦索姆城中的鬼魂使用埃根的冲击器。当那些永不安息的灵魂挣脱他们的外壳时，再次使用埃根的冲击器——他们就可以获得自由了！ 解放15个永不安息的灵魂，然后回到埃根那里去。",
    [5283] = "要想成为一名护甲铸造师的话，你必须将下列物品交给格鲁努斯：4顶精制秘银头盔、2双精制秘银战靴和1副精制秘银胸甲。",
    [5284] = "要想成为一名武器铸造师的话，你必须将下列物品交给埃隆努斯·冷钢：4把月钢宽剑、4把巨型铁斧、2把秘银重斧和2把巨型黑色锤。",
    [5301] = "要想成为一名护甲铸造师的话，你必须将下列物品交给奥克索斯：4顶精制秘银头盔、2双精制秘银战靴和1副精制秘银胸甲。",
    [5302] = "要想成为一名武器铸造师的话，你必须将下列物品交给伯古什：4把月钢宽剑、4把巨型铁斧、2把秘银重斧和2把巨型黑色锤。",
    [5305] = "到斯坦索姆去杀死红衣铸锤师。将红衣铸锤师的围裙交给莉莉丝。",
    [5306] = "到黑石塔去杀死暗影猎手沃什加斯，将沃什加斯的菊石交给基尔拉姆。",
    [5307] = "在斯坦索姆找到黑衣守卫铸剑师，然后杀死他。将黑色卫士徽记交给亡灵杀手瑟里尔。",
    [5321] = "护送克罗尼亚·恒影沿着大路向南走，去找利拉迪斯·月河，以便在黑海岸找回他的背包。",
    [5341] = "到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到阿莱克斯·巴罗夫那儿去。",
    [5342] = "到冰风岗——联盟的领地——去暗杀维尔顿·巴罗夫。把他的脑袋交给阿莱克斯·巴罗夫。 要多加小心，联盟也许对维尔顿实施了严密的保护。",
    [5343] = "到通灵学院中去取得巴罗夫家族的宝藏。这份宝藏包括四份地契：凯尔达隆地契、布瑞尔地契、塔伦米尔地契，还有南海镇地契。完成任务之后就回到维尔顿·巴罗夫那儿去。",
    [5344] = "去亡灵壁垒——部落的领地——去暗杀阿莱克斯·巴罗夫。把他的脑袋交给维尔顿·巴罗夫。 要小心，部落也许对阿莱克斯实施了严密的保护。",
    [5361] = "将峭壁卫兵图林·长角的报告交给凄凉之地幽灵岗哨的纳塔卡·长角。",
    [5381] = "在雷斧堡垒中找到恶魔之盒，把它和恶魔之锄一起交给葬影村的泰迦·慧鬃。",
    [5382] = "在通灵学院中找到瑟尔林·卡斯迪诺夫教授。杀死他，并烧毁艾瓦·萨克霍夫和卢森·萨克霍夫的遗体。任务完成后就回到艾瓦·萨克霍夫那儿。",
    [5384] = "带着无辜者之血回到通灵学院，将它放在门廊的火盆下面，基尔图诺斯会前来吞噬你的灵魂。 勇敢地战斗吧，不要退缩！杀死基尔图诺斯，然后回到艾瓦·萨克霍夫那儿。",
    [5385] = "将特雷·莱弗治的残骸交给费伍德森林的杰希尔·月弓。",
    [5386] = "与葬影村的吉纳泽林谈话，然后将2条血肚鱼交给纳塔卡·长角。",
    [5441] = "在懒惰的苦工睡觉时，用工头的木棒敲他们。敲醒5个苦工，然后把工头的木棒还给试炼谷的工头塔兹利尔。",
    [5461] = "到阿拉希高地的激流堡遗迹里面寻找巫妖生前的遗物。如果你能找到这样的东西，就把它交给马杜克镇长。",
    [5462] = "到东瘟疫之地的圣光之愿礼拜堂去找到莱尼德·巴萨罗梅，给他看看巫妖生前的遗物，并告诉他你收集到的情报。",
    [5463] = "到斯坦索姆城里去找到米奈希尔的礼物，把巫妖生前的遗物放在那块邪恶的土地上。",
    [5464] = "把禁锢灵魂的遗物交给东瘟疫之地的莱尼德·巴萨罗梅。",
    [5465] = "回到凯尔达隆的马杜克镇长那里，把禁锢灵魂的遗物交给他。",
    [5466] = "在通灵学院里找到莱斯·霜语。当你找到他之后，使用禁锢灵魂的遗物破除其亡灵的外壳。如果你成功地破除了他的不死之身，就杀掉他并拿到莱斯·霜语的头颅。把那个头颅交给马杜克镇长。",
    [5481] = "收集3根阴暗草，把它们交给布瑞尔墓地的初级药剂师霍兰德。",
    [5482] = "收集10株末日草，把它们交给初级药剂师霍兰德。",
    [5501] = "从科多墓地收集10根科多兽骨，把它们交给兽人小屋的比布里·弗斯巴克。",
    [5504] = "把10个银色黎明勇气勋章交给西瘟疫之地亡灵壁垒的银色黎明军需官哈萨娜。",
    [5507] = "把10个银色黎明勇气勋章交给西瘟疫之地冰风营地的银色黎明军需官莱斯巴克。",
    [5513] = "把10个银色黎明勇气勋章交给东瘟疫之地圣光之愿礼拜堂的军需官米兰达·布利洛克。",
    [5514] = "把灌魔的骸骨碎片和15枚金币交给加基森的克林科·古德斯迪尔。",
    [5515] = "在通灵学院找到詹迪斯·巴罗夫并打败她。从她的尸体上找到卡斯迪诺夫的恐惧之袋，然后将其交给艾瓦·萨克霍夫。",
    [5517] = "把25个银色黎明勇气勋章交给东瘟疫之地圣光之愿礼拜堂的银色黎明军需官米兰达·布利洛克。",
    [5518] = "把4份符文布卷、8块硬甲皮、2卷符文线和一份食人魔鞣酸交给诺特·希姆加克。他现在被拴在厄运之槌的戈多克食人魔那边。",
    [5521] = "把25个银色黎明勇气勋章交给西瘟疫之地冰风营地的银色黎明军需官莱斯巴克。",
    [5522] = "把冰冻的龙蛋交给东瘟疫之地的莱尼德·巴萨罗梅。",
    [5524] = "把25个银色黎明勇气勋章交给西瘟疫之地亡灵壁垒的银色黎明军银色黎明军需官哈萨娜。",
    [5526] = "在厄运之槌中找到魔藤，然后从它上面采集一块碎片。只有干掉了奥兹恩之后，你才能进行采集工作。使用净化之匣安全地封印碎片，然后将其交给月光林地永夜港的拉比恩·萨图纳。",
    [5527] = "到希利苏斯的南风村去寻找净化之匣。然后将其交给月光林地永夜港的拉比恩·萨图纳。",
    [5529] = "杀掉20只瘟疫龙崽，然后向圣光之愿礼拜堂的贝蒂娜·比格辛克复命。",
    [5531] = "将冰冻的龙蛋交给贝蒂娜·比格辛克。",
    [5533] = "和西瘟疫之地冰风岗的化学家阿尔比顿谈一谈。",
    [5534] = "寻找埃达拉斯废墟中的纳迦携带的那些符石，然后把它们交给艾萨拉的基姆加尔。",
    [5535] = "杀掉6个上层精灵的幻影和6个上层精灵鬼巫，然后向艾萨拉的罗哈图复命。",
    [5536] = "杀掉6个哈达尔萨特、2个哈达尔欺诈者和2个哈达尔魔仆，然后向灰谷与艾萨拉交界处的罗哈图复命。",
    [5537] = "将15块骷髅碎片交给西瘟疫之地冰风岗的化学家阿尔比顿。",
    [5538] = "把灌魔的骸骨碎片和15枚金币交给加基森的克林科·古德斯迪尔。",
    [5541] = "把海格纳的弹药交给丹莫罗的海格纳·重枪。",
    [5542] = "杀掉20条瘟疫幼犬、5条瘟疫犬和5条狂怒的瘟疫犬。任务完成之后向提里奥·弗丁复命。",
    [5543] = "杀死30只瘟疫蝙蝠，然后向提里奥·弗丁复命。",
    [5544] = "在东瘟疫之地搜索腐肉虫和腐肉吞噬者。杀了它们并收集它们的肉。当你收集到15块食腐虫肉块之后，就回到提里奥·弗丁那里。",
    [5545] = "收集8捆木材，把它们交给东谷伐木场的管理员莱琳。",
    [5561] = "将科多兽诱引器和5头被驯服的科多兽交给瑟卡布斯库的营地中的斯米德·瑟卡布斯库。",
    [5581] = "放逐6个玛诺洛克集会所的传送门，然后回到葬影村的泰迦·慧鬃那里。",
    [5582] = "把健康的龙鳞交给东瘟疫之地圣光之愿礼拜堂中的贝蒂娜·比格辛克。",
    [5601] = "在达隆郡里找到帕米拉·雷德帕斯。",
    [5621] = "找到哨兵莎恩雅并使用次级治疗术（等级 2）来治疗她。然后对她施放真言术：韧，最后向多兰纳尔的劳尔娜·晨光复命。",
    [5622] = "与泰达希尔的劳尔娜·晨光谈一谈。",
    [5623] = "与艾尔文森林的女牧师洁塞塔谈一谈。",
    [5624] = "找到卫兵罗伯兹并使用次级治疗术（等级 2）来治疗他。然后对他施放真言术：韧，最后向闪金镇的女牧师洁塞塔复命。",
    [5625] = "找到巡山人多尔夫并使用次级治疗术（等级 2）来治疗他。然后对他施放真言术：韧，最后向卡拉诺斯的马克萨恩·安沃尔复命。",
    [5626] = "与丹莫罗的马克萨恩·安沃尔谈一谈。",
    [5628] = "与达纳苏斯的女祭司阿兰希雅谈一谈。",
    [5629] = "与达纳苏斯的女祭司阿兰希雅谈一谈。",
    [5630] = "与达纳苏斯的女祭司阿兰希雅谈一谈。",
    [5631] = "与达纳苏斯的女祭司阿兰希雅谈一谈。",
