    [5677] = "与暴风城的高阶牧师劳瑞娜谈一谈。",
    [5713] = "保护哨兵阿娜莎，然后向灰谷迈斯特拉岗哨的奥奈雅报告。",
    [5721] = "将遗物包裹放在达隆郡的广场中。 在霍古斯死亡之前，达维必须存活。 在雷德帕斯队长堕落之前保证他存活。 击败堕落的雷德帕斯。 当约瑟夫·雷德帕斯出现在广场中时，与他的灵魂进行交谈，然后回到帕米拉的家中去找帕米拉。",
    [5722] = "在怒焰裂谷搜寻玛尔·恐怖图腾的尸体以及他留下的东西。",
    [5723] = "在奥格瑞玛找到怒焰裂谷，杀掉8个怒焰穴居人和8个怒焰萨满祭司，然后向雷霆崖的拉哈罗复命。",
    [5724] = "将恐怖图腾背包交给雷霆崖的拉哈罗。",
    [5725] = "将《暗影法术研究》和《扭曲虚空的魔法》这两本书交给幽暗城的瓦里玛萨斯。",
    [5726] = "将军官的徽章交给奥格瑞玛的萨尔。",
    [5727] = "将军官的徽章交给尼尔鲁·火刃并与他谈一谈，看看他是否相信你是火刃氏族中的一员，然后回到奥格瑞玛的萨尔那里。",
    [5728] = "杀死巴扎兰和祈求者耶戈什，然后回到奥格瑞玛的萨尔那里。",
    [5729] = "与奥格瑞玛的尼尔鲁·火刃谈一谈。",
    [5730] = "与奥格瑞玛的萨尔谈一谈，告诉他你了解到的东西。",
    [5741] = "拿到圣光节杖，并将它交给艾瑟雷索塔里的阿佐尔·奥达蒙特。",
    [5742] = "听听提里奥·弗丁要说什么。",
    [5761] = "进入怒焰裂谷，杀死饥饿者塔拉加曼，然后把他的心脏交给奥格瑞玛的尼尔鲁·火刃。",
    [5762] = "将克拉维尔的箱子送到荆棘谷的赫米特·奈辛瓦里那里。",
    [5763] = "将鲁恩的科多兽角送到荆棘谷的赫米特·奈辛瓦里那里。",
    [5781] = "到东瘟疫之地最南端的墓室去找回泰兰之锤。完成目标之后，返回提里奥·弗丁那里。",
    [5801] = "把骷髅钥匙模具和2块瑟银锭带到安戈洛尔环形山地区的火羽山顶部。在熔岩湖旁使用骷髅钥匙模具，铸造出一把未完工的骷髅钥匙。 把未完工的骷髅钥匙交给西瘟疫之地冰风岗的化学家阿尔比顿。",
    [5802] = "把骷髅钥匙模具和2块瑟银锭带到安戈洛尔环形山地区的火羽山顶部。在熔岩湖旁使用骷髅钥匙模具，铸造出一把未完工的骷髅钥匙。 把未完工的骷髅钥匙交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。",
    [5803] = "杀掉召唤者阿拉基，并将阿拉基的圣甲虫交给西瘟疫之地冰风岗的化学家阿尔比顿。",
    [5804] = "杀掉召唤者阿拉基，并将阿拉基的圣甲虫交给西瘟疫之地亡灵壁垒的药剂师迪瑟斯。",
    [5821] = "护送基泽尔顿商队通过科卡尔半人马村，然后与瑟卡布斯库的营地中的斯米德谈话以领取你的奖赏。",
    [5845] = "到东瘟疫之地东北部的北谷去，找到失落荣耀的象征。完成目标之后向提里奥·弗丁复命。",
    [5846] = "到凯尔达隆岛去，寻找关于那副画的线索。凯尔达隆岛在瘟疫之地南部的湖中央。",
    [5848] = "到瘟疫之地北部的斯坦索姆去。你可以在血色十字军堡垒中找到“爱与家庭”这幅画，它被隐藏在另一幅描绘两个月亮的画之后。 把这幅画还给提里奥·弗丁。",
    [5861] = "到瘟疫之地南部的乌瑟尔之墓去，将提里奥的礼物交给巫女麦兰达。",
    [5862] = "和巫女麦兰达交谈以获得血色幻象的效果。在血色幻象的掩护下深入壁炉谷，将提里奥的礼物交给大领主泰兰·弗丁。 壁炉谷在北方，泰兰应该在玛登霍尔德城堡里面。",
    [5863] = "加基森的安迪·利恩想要你攻入砂槌营地，杀死10个砂槌蛮兵、10个砂槌执行者，以及掠夺者格玛洛克。",
    [5881] = "马格兰希望你将信送到贫瘠之地升降梯的瑞什·远行者手中。",
    [5892] = "把10份深铁矿洞补给品交给丹巴达尔的联盟军需官。",
    [5893] = "把10份冷齿矿洞补给品交给霜狼要塞的部落军需官。",
    [5901] = "在东瘟疫之地的蚁丘上使用空的白蚁瓶。当你收集了100只瘟疫白蚁之后，就回到提瑞斯法林地的亡灵壁垒去找米克·莱文。",
    [5902] = "到西瘟疫之地的北山伐木场去找个合适的地方，在那里放下一桶瘟疫白蚁。",
    [5903] = "在东瘟疫之地的蚁丘上使用空的白蚁瓶。当你收集了100只瘟疫白蚁之后，就回到西瘟疫之地的冰风岗去找纳萨尼尔·杜马。",
    [5904] = "到西瘟疫之地的北山伐木场去找个合适的地方，在那里放下一桶瘟疫白蚁。",
    [5921] = "使用法术“传送：月光林地”抵达月光林地，在那里与永夜港的德迪利特·星焰谈一谈。",
    [5922] = "使用法术“传送：月光林地”抵达月光林地，在那里与永夜港的德迪利特·星焰谈一谈。",
    [5923] = "与达纳苏斯塞纳里奥区的玛斯雷·驭熊者谈一谈。",
    [5924] = "与达纳苏斯塞纳里奥区的玛斯雷·驭熊者谈一谈。",
    [5925] = "与达纳苏斯塞纳里奥区的玛斯雷·驭熊者谈一谈。",
    [5926] = "与雷霆崖长者高地上的图拉克·符文图腾谈一谈。",
    [5927] = "与雷霆崖长者高地上的图拉克·符文图腾谈一谈。",
    [5928] = "与雷霆崖长者高地上的图拉克·符文图腾谈一谈。",
    [5929] = "到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。",
    [5930] = "到月光林地的西北部去寻找巨熊之灵，向它学习关于熊的知识，然后回到月光林地的永夜港去找德迪利特·星焰。",
    [5931] = "回到达纳苏斯，与塞纳里奥区的玛斯雷·驭熊者谈一谈。",
    [5932] = "回到雷霆崖，与长者高地的图拉克·符文图腾谈一谈。",
    [5941] = "将一包遗物交给安多哈尔的克罗米。",
    [5942] = "用约瑟夫的钥匙打开约瑟夫的箱子。",
    [5943] = "护送基泽尔顿车队通过玛诺洛克集会所，然后与瑟卡布斯库的营地的斯米德谈一谈，领取你的奖励。",
    [5944] = "护送泰兰·弗丁走出壁炉谷。",
    [5961] = "与东瘟疫之地的纳萨诺斯·凋零者谈一谈。据说他居住在玛瑞斯农场。",
    [5981] = "雷沃·霜翼要你去杀死4个霜槌巨人和4个霜槌保卫者。",
    [6001] = "使用奥伯丁的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。 任务完成之后，与达纳苏斯的玛斯雷·驭熊者谈一谈。",
    [6002] = "使用莫高雷与贫瘠之地交界处的月夜枭兽之石上面的塞纳里奥月尘引出月爪枭兽，然后击败月爪枭兽并吸取它所拥有的身心之力。 任务完成之后，与雷霆崖的图拉克·符文图腾谈一谈。",
    [6004] = "杀死2个血色医护员、2个血色猎人、2个血色魔法师和2个血色骑士，然后回到西瘟疫之地的科尔斯塔·迪普沙东那儿。",
    [6021] = "将塞达尔的头颅交给圣光之愿礼拜堂的护理者奥林。",
    [6022] = "到东边的考林路口去屠杀镇里的亡灵天灾。在10分钟内收集7块生命腐质，使用研钵和捣杵将其研磨成凝固腐质。",
    [6023] = "杀掉猎人莱德雷和骑士杜尔根，然后向西瘟疫之地的科尔斯塔·迪普沙东复命。",
    [6024] = "杀了渗透者哈米亚，用他的钥匙开启墓室后的一堆泥土。",
    [6025] = "进入壁炉谷并找一处高地，你可以在那里观察整个城镇并估算血色十字军的兵力，然后向西瘟疫之地的科尔斯塔·迪普沙东回报。",
    [6026] = "烟鬼拉鲁恩要你拿来2块瑟银锭、1根金棒、8颗高爆炸弹和8个不牢固的扳机。 你需要找铁匠和工程学技师帮忙制作这些东西。",
    [6027] = "拿到上古之书，将其交给艾瑟雷索塔中的阿佐尔·奥达蒙特。",
    [6028] = "把永望镇报告送给西瘟疫地冰风岗的银色黎明军官普尔哈特。",
    [6029] = "把永望镇报告送给西瘟疫地亡灵壁垒的银色黎明军官加鲁什。",
    [6030] = "将《灵语研究》这本书交给东瘟疫之地圣光之愿礼拜堂的尼古拉斯·瑟伦霍夫公爵。",
    [6031] = "把30块符文布交给木喉要塞的梅罗什。",
    [6032] = "把2块月布交给木喉要塞的梅罗什。",
    [6041] = "到圣光之愿礼拜堂西北方的病木林去。在那些有爆炸标记的建筑物中对爆炸标记使用烟鬼的特殊混合物，以此来摧毁8座亡灵天灾建筑。烟鬼已经给通灵塔和屠宰房做上了标记。 一旦你放置好炸弹，就离那些建筑物远一些，然后尽情欣赏你的杰作吧。 顺便说一句，烟鬼的特殊混合物相当不稳定……",
    [6042] = "杀掉20只毒性瘟疫蝙蝠和10只巨型瘟疫蝙蝠，然后回到纳萨诺斯·凋零者那里。",
    [6061] = "使用驯兽棒驯服成年陆行鸟。练习你的技能，然后将驯兽棒还给血蹄村的雅文·刺鬃。",
    [6062] = "使用驯兽棒驯服可怕的杂斑野猪。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。",
    [6063] = "使用驯兽棒驯服树林潜伏者。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。",
    [6064] = "使用驯兽棒驯服大型峭壁野猪。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。",
    [6065] = "与血蹄村的雅文·刺鬃谈一谈。",
    [6066] = "与血蹄村的雅文·刺鬃谈一谈。",
    [6067] = "与血蹄村的雅文·刺鬃谈一谈。",
    [6068] = "与剃刀岭的索塔尔谈一谈。",
    [6069] = "与剃刀岭的索塔尔谈一谈。",
    [6070] = "与剃刀岭的索塔尔谈一谈。",
    [6071] = "与多兰纳尔的达扎拉谈一谈。",
    [6073] = "与多兰纳尔的达扎拉谈一谈。",
    [6074] = "与卡拉诺斯的格瑞夫谈一谈。",
    [6075] = "与卡拉诺斯的格瑞夫谈一谈。",
    [6076] = "与卡拉诺斯的格瑞夫谈一谈。",
    [6081] = "与奥格瑞玛的奥玛克谈一谈。",
    [6082] = "使用驯兽棒驯服硬甲蝎。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。",
    [6083] = "使用驯兽棒驯服海浪蟹。练习你的技能，然后将驯兽棒还给剃刀岭的索塔尔。",
    [6084] = "使用驯兽棒驯服雪豹。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。",
    [6085] = "使用驯服兽棒驯服一头冰爪熊。练习你的技能，然后将驯兽棒还给卡拉诺斯的格瑞夫。",
    [6086] = "与铁炉堡的贝莉亚·雷岩谈一谈。",
    [6087] = "使用驯兽棒驯服一只草原捕食者。练习你的技能，然后将驯兽棒还给血蹄村的雅文·刺鬃。",
    [6088] = "使用驯兽棒驯服一只猛鹫。练习你的技能，然后将驯服法杖交还给血蹄村的雅文·刺鬃。",
    [6089] = "与雷霆崖猎人高地的浩特·雷角谈一谈。",
    [6101] = "使用驯兽棒驯服一只夜刃捕食者。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。",
    [6102] = "使用驯兽棒驯服一只巨翼恶枭。练习你的技能，然后将驯兽棒还给多兰纳尔的达扎拉。",
    [6103] = "与达纳苏斯塞纳里奥区的祖卡斯特谈一谈。",
    [6121] = "到月光林地去，与永夜港的德迪利特·星焰谈一谈。",
    [6122] = "使用空的峭壁之泉取样器在瀑布洞口获得水样。 将盛满的峭壁之泉取样器送到黑海岸奥伯丁的奥兰达利亚·夜歌那里。",
    [6123] = "收集5个地根草和12个月亮菇，把它们交给奥伯丁的奥兰达利亚·夜歌，这样她就可以制作解药了。",
    [6124] = "对黑海岸的10头生病的鹿使用动物医疗药膏，以此来治疗它们。从壁泉河到奥伯丁，直到最南端靠近灰谷的地区都有生病的鹿出没。",
    [6125] = "回到达纳苏斯塞纳里奥区的玛斯雷·驭熊者那里。",
    [6126] = "到月光林地去，与永夜港的德迪利特·星焰谈一谈。",
    [6127] = "使用空的鬼雾峰取样器在山顶取水样。 将盛满的鬼雾峰取样器送到贫瘠之地十字路口的图加·符文图腾那里。",
    [6128] = "收集5个地根草和5个科多兽角，把它们交给十字路口的图加·符文图腾，这样他就可以制作解药了。",
    [6129] = "对贫瘠之地北部的10只生病的瞪羚使用动物医疗药膏，以此来治疗它们。在穿过十字路口的那条东西走向的大路北面到处都是生病的蹬羚。",
    [6130] = "回到雷霆崖长者高地的图拉克·符文图腾那里。",
    [6132] = "护送梅丽萨，然后与科多兽坟场的霍恩尼兹谈一谈。",
    [6133] = "到东瘟疫之地的北方边界去找回奎尔萨拉斯名册，这件物品在奎尔林斯小屋的某处。 另外你还必须杀掉8个游侠、8个巡路者和8个护林者。",
    [6134] = "把幽灵磁铁箱和8份幽灵电浆交给凄凉之地的霍恩尼兹。",
    [6135] = "找到暗翼蝠并杀掉它。从尸体上取下一块暗翼蝠的皮，并把它交给纳萨诺斯·凋零者。 据说暗翼蝠游荡在玛瑞斯农场北面的荒原上。",
    [6136] = "找到东瘟疫之地北方荒原中的淤血虫并消灭它。任务完成之后，向纳萨诺斯·凋零者复命。",
    [6141] = "与凄凉之地的安东修士谈一谈。",
    [6142] = "找到10块软壳蚌肉，把它们交给葬影村的麦拉斯。",
    [6143] = "杀死7个滑刃侍从、7个滑刃纳迦，以及5个滑刃巫师，然后与葬影村的杜泽加尔谈谈。",
    [6144] = "到幽暗城去与瓦里玛萨斯谈一谈。",
    [6145] = "返回东瘟疫之地，找到并杀死红衣信使，拿到大十字军的命令。 把命令交给纳萨诺斯·凋零者，并等待进一步的指示。",
    [6146] = "到玛瑞斯农场东南方的提尔之手去，抵达那里之后就咬一口烂苹果。在血色十字军伪装的掩护下，把大十字军的命令交给十字军领主瓦德玛尔。",
    [6147] = "带着新情报返回纳萨诺斯·凋零者那里。",
    [6148] = "血色十字军正在从提尔之手到斯坦索姆的路上巡逻，你可以在巡逻队中找到圣者德米提雅和她的随从，找到并杀死她。如果你成功了，就回到纳萨诺斯·凋零者那里去复命。",
    [6161] = "找到拉克摩尔的银钥匙和金钥匙。找到并打开拉克摩尔的箱子。",
    [6162] = "杀死主宰洛尔，把他的爪子交给费伍德森林血毒岗哨的德雷卡苏。",
    [6163] = "到斯坦索姆去，杀掉吞咽者拉姆斯登。把他的头颅交给纳萨诺斯。",
    [6164] = "把奥古斯图斯的收据册交给恶蛛隧道中的被感动的奥古斯图斯。",
    [6181] = "将刘易斯的便笺交给狮鹫管理员索尔。",
    [6182] = "与暴风城的马迪亚斯·肖尔谈一谈，他住在旧城区的兵营里。",
    [6183] = "如果你愿意接这个任务，就再和马迪亚斯·肖尔谈一谈。",
    [6184] = "到西瘟疫之地的冰风岗去跟弗林特·沙多摩尔会面。",
    [6185] = "搜寻东瘟疫之地，寻找“凋零者”的线索以及失踪的军情七处密探。如果你找到任何军情七处徽章，就把它们交给冰风岗的弗林特·沙多摩尔。",
    [6186] = "回到暴风城，将纳萨诺斯·玛瑞斯的下落报告给伯瓦尔·弗塔根公爵。",
    [6187] = "组织一支部队，然后到东瘟疫之地去。向纳萨诺斯·凋零者和任何敢于保护他的部落成员发起攻击。 你要倾尽全力，<name>。部落会不惜一切代价保护他们的游侠领主。",
    [6261] = "将奥斯瑞克的箱子交给狮鹫管理员杜加尔·朗德瑞克。",
    [6281] = "从狮鹫管理员索尔那里租用一头狮鹫，然后把刘易斯的便笺交给暴风城的奥斯瑞克·斯图恩。",
    [6282] = "烈日石居的马格兰要你去杀掉7个血怒鹰身人、7个血怒伏击者、7个血怒杀戮者和7个血怒游荡者。",
    [6283] = "烈日石居的马格兰要你去杀掉血怒撕裂者，然后把她的遗体带回来作为证据。",
    [6284] = "杀掉贝瑟莱斯，然后把贝瑟莱斯的牙齿交给烈日石居的马格兰。",
    [6285] = "从狮鹫管理员杜加尔·朗德瑞克那里租用一头狮鹫飞到哨兵岭，然后将奥斯瑞克的箱子交给哨兵岭的刘易斯。",
    [6301] = "烈日石居的塔姆拉·荒原想让你去收集10枚盖亚之种。",
    [6321] = "将博迪瑞格的订单交给卡洛斯·拉佐克。",
    [6322] = "将高顿的箱子交给迈克尔·加勒特。",
    [6323] = "从蝙蝠管理员卡洛斯·拉佐克那里租一只蝙蝠飞往幽暗城，然后将博迪瑞格的订单交给幽暗城里的高顿·温德哈姆。",
    [6324] = "从蝙蝠管理员迈克尔·加勒特那儿租一只蝙蝠飞往瑟伯切尔，然后将高顿的箱子交给瑟伯切尔的亡灵卫兵博迪瑞格。",
    [6341] = "将尼莎的货物交给维斯派塔斯。",
    [6342] = "从角鹰兽管理员维斯派塔斯那里租用一只角鹰兽飞到奥伯丁，然后将尼莎的货物交给莱尔德。",
    [6343] = "将莱尔德的回信交给尼莎·影歌。",
    [6344] = "与尼莎·影歌谈一谈。",
    [6361] = "带着兽皮去找十字路口的迪弗拉克。",
    [6362] = "从双足飞龙管理员迪弗拉克那里租一只驭风者飞往雷霆崖，然后将这捆兽皮交给雷霆崖的安哈努。",
    [6363] = "将安哈努的皮货交给雷霆崖的塔尔。",
    [6364] = "从双足飞龙管理员塔尔那里租用一头飞往十字路口的双足飞龙，并把安哈努的皮货交给加翰·鹰翼。",
    [6365] = "把扎尔夫的肉品交给十字路口的迪弗拉克。",
    [6381] = "将10枚盖亚之种种植在盖亚土堆中，然后与烈日石居的塔姆拉谈一谈。",
    [6382] = "与灰谷碎木哨岗的塞娜尼·雷心谈一谈。",
    [6384] = "从双足飞龙管理员迪弗拉克那里租一只驭风者飞往奥格瑞玛，然后将扎尔夫的肉品交给奥格瑞玛的格雷什卡。",
    [6385] = "将格雷什卡的信交给奥格瑞玛的多拉斯。",
    [6386] = "从驭风者管理员多拉斯那里雇一只驭风者前往十字路口，然后将格雷什卡的信交给十字路口的扎尔夫。",
    [6387] = "将布洛克的名单交给塞尔萨玛的索格拉姆·伯雷森。",
    [6388] = "将荣誉锄交给铁炉堡的格莱斯·瑟登。",
    [6389] = "使用北山伐木场里的铁棍放出那里的瘟疫白蚁，然后向西瘟疫之地冰风岗的纳萨尼尔·杜马报告。",
    [6390] = "使用北山伐木场里的铁棍放出那里的瘟疫白蚁，然后向提瑞斯法林地亡灵壁垒的米克·莱文报告。",
    [6391] = "从狮鹫管理员索格拉姆·伯雷森那里租一只狮鹫飞往铁炉堡，然后将布洛克的名单交给铁炉堡的高尼尔·石趾。",
    [6392] = "从狮鹫管理员格莱斯·瑟登那里租用一头飞往塞尔萨玛的狮鹫，然后将荣誉锄交给塞尔萨玛的布洛克·寻石者。",
    [6393] = "将10块焚火余烬交给烈日石居的苏纳曼。",
    [6394] = "将塔兹利尔的镐还给塔兹利尔。",
    [6395] = "将塞缪尔·菲普斯的遗骸带到玛拉的坟墓去，然后回到新兵艾尔雷斯那里。",
    [6401] = "把这个好消息告诉烈日石居的塔姆拉·荒原。",
    [6402] = "前往暴风城的城门。与侍卫洛文交谈，他会通知温德索尔元帅你已经到达了。",
    [6403] = "护送雷吉纳德·温德索尔穿过暴风城，确保他毫发无损！ 若需再次联系雷吉纳德·温德索尔，请去找侍卫洛文。",
    [6421] = "深入滚岩峡谷的洞穴中，为烈日石居的摩罗加尔取回10块共鸣水晶以供研究。",
    [6441] = "为碎木哨岗的皮克希尔收集16只萨特的角。",
    [6442] = "将20颗怒尾纳迦的头颅交给佐拉姆海岸的玛鲁凯。",
    [6461] = "玛拉卡金的辛吉拉要求你杀死10只深苔爬行者和7只深苔毒蜘蛛。",
    [6462] = "将8个巨魔符咒交给佐拉姆加前哨站的米苏瓦。",
    [6481] = "使用魔化共鸣水晶打开共鸣桶，然后杀死高戈罗克。将这个消息告诉摩罗加尔，并把魔化共鸣水晶还给他。",
    [6482] = "护送鲁尔，然后与慰藉之林的雅玛·雪蹄谈一谈。",
    [6501] = "你必须寻遍世界以找到一种能恢复龙眼碎片的能量的生物。你对这种生物的唯一了解就是：他们确实存在。",
    [6502] = "你必须从达基萨斯将军手中取得黑龙勇士之血。 达基萨斯位于黑石塔晋升大厅后方的王座室内。",
    [6503] = "杀掉9个灰谷先驱者，然后回到碎木哨岗的库莱比那里。",
    [6504] = "找到丢失的12页伐木机操作指南，把它们合并为第1、2、3章。然后带着这些书页回到碎木岗哨去找古尔达·怒痕。",
    [6521] = "把玛克林大使的头颅交给幽暗城的瓦里玛萨斯。",
    [6522] = "把小卷轴交给幽暗城的瓦里玛萨斯。",
    [6523] = "护送卡雅·扁蹄回到阿帕拉耶营地，然后到石爪山东南边界附近的玛卡巴·扁蹄那里去复命。",
    [6541] = "到贫瘠之地北部的卡德拉克那里报到。",
    [6542] = "到贫瘠之地北部的卡德拉克那里报到。",
    [6543] = "打开报告集，把战歌报告交给战歌斥候、战歌信使和战歌侦查骑兵。把他们的最新报告交给贫瘠之地北部哨塔上的卡德拉克。",
    [6544] = "保护在银翼哨站与杜瑞尔·月火作战的托雷克，然后向慰籍之林的埃尔托格·怒齿汇报胜利的消息。",
    [6548] = "杀掉8个恐怖图腾恶徒和6个恐怖图腾佣兵，然后向石爪山脉东南边界处的玛卡巴·扁蹄复命。",
    [6561] = "把暮光领主克尔里斯的头颅交给雷霆崖的巴珊娜·符文图腾。",
    [6562] = "与灰谷的耶努萨克雷谈一谈。",
    [6563] = "收集20颗阿库麦尔蓝宝石，把它们交给灰谷的耶努萨克雷。",
    [6564] = "把潮湿的便笺交给灰谷的耶努萨克雷。",
    [6565] = "杀掉黑暗深渊里的洛古斯·杰特，然后向灰谷的耶努萨克雷复命。",
    [6566] = "听萨尔讲话。",
    [6567] = "按照酋长的指示找到雷克萨。他在石爪山和菲拉斯之间的凄凉之地游荡。",
    [6568] = "把雷克萨的证明交给西瘟疫之地的巫女麦兰达。",
    [6569] = "到黑石塔去收集20颗黑色龙人的眼球，完成任务之后回到巫女麦兰达那里。",
    [6570] = "到尘泥沼泽中的巨龙沼泽去，找到埃博斯塔夫的洞穴。进入洞穴之后戴上龙形护符，然后跟埃博斯塔夫交谈。",
    [6571] = "收集战歌氏族的补给品：战歌锯条、伐木绳、战歌之油，还有一箱战歌之斧。",
    [6582] = "找到蓝龙斯克利尔并杀掉他。从他的身上取下他的颅骨，然后将其交给埃博斯塔夫。 你可以在冬泉谷找到斯克利尔。",
    [6583] = "杀掉绿龙索姆努斯，把他的颅骨交给埃博斯塔夫。",
    [6584] = "诺兹多姆的孩子克鲁纳里斯在塔纳利斯沙漠守卫着时光之穴。杀了他，把他的颅骨交给埃博斯塔夫。",
    [6585] = "到格瑞姆巴托去杀掉红龙埃克托兹，把他的颅骨交给埃博斯塔夫。",
    [6601] = "看来这场假面舞会就要结束了。你知道麦兰达为你制作的龙形护符在黑石塔里面不会发挥作用，也许你应该去找雷克萨，将你的困境告诉他。把黯淡的龙火护符给他看看，也许他知道下一步该怎么做。",
    [6602] = "到黑石塔去杀掉达基萨斯将军，把它的血交给雷克萨。",
    [6603] = "到冬泉谷的温泉附近去找到多诺瓦·雪山。",
    [6604] = "与坠星村的加隆·石矛谈一谈。",
    [6605] = "与费伍德森林的温娜·哈萨德谈一谈。",
    [6607] = "纳特·帕格要你钓到以下几种鱼： 悲伤沼泽芦苇海岸的芦苇海岸大马哈鱼。 凄凉之地萨瑟里斯海岸的萨瑟里斯虎鱼。 菲拉斯沃丹提斯河的菲拉斯草鱼。 荆棘谷野人海岸的野人海岸蓝色叉牙鱼。 当你钓到这些鱼之后，就可以回到纳特·帕格那里去了！",
    [6608] = "你认为鲁玛克想要告诉你，他已经不能帮你提高钓鱼的技能了。也许你应该去找到他的朋友纳特·帕格，他居住在塞拉摩以南的某个岛屿上，他是一名人类渔夫（至少你认为鲁玛克是这么说的）。",
    [6609] = "到卡利姆多大陆的塞拉摩去。从那里向南方出发，找到一座岛屿。纳特·帕格就在岛上等待着你的到来！",
    [6610] = "迪尔格·奎克里弗想要你收集这些原料： 12只巨蛋。你可以在塔纳利斯的大鹏或是其它大型鸟类那里获得这种蛋。 10块美味的蚌肉。你可以从任何蚌类身上获得这种原料！ 20块奥特兰克冷酪。去买就是了！ 收集好所有原料，然后把它们交给迪尔格。",
    [6611] = "到塔纳利斯沙漠的加基森去，与迪尔格·奎克里弗谈谈你的厨师生涯。",
    [6612] = "到塔纳利斯沙漠的加基森去，与迪尔格·奎克里弗谈谈你的厨师生涯。",
    [6621] = "把卡拉恩的旗子插到污林图腾堆中。不要让熊怪摧毁这面旗子。击败穆戈特酋长，将穆戈特的图腾交给佐拉姆加的卡拉恩·阿玛卡。",
    [6622] = "使用急救绷带来治疗病人。你必须在6个病人死亡之前拯救15个病人。 一定要牢记治疗的顺序！受致命伤的病人会很快死亡，其次是重伤病人，受普通伤的病人死亡得最慢。所以你最好在治疗那些受致命伤和重伤的病人之后再去治疗受普通伤的病人。",
    [6623] = "到阿拉希高地的落锤镇去，与格里高利·维克托医生谈一谈关于加入部落外科医疗队的事宜。",
    [6624] = "使用急救绷带来治疗病人。你必须在6个病人死亡之前拯救15个病人。 一定要牢记治疗的顺序！受致命伤的病人会很快死亡，其次是重伤病人，受普通伤的病人死亡得最慢。所以你最好在治疗那些受致命伤和重伤的病人之后再去治疗受普通伤的病人。",
    [6625] = "到尘泥沼泽的塞拉摩去，与古斯塔夫·范沃森医生谈一谈关于加入联盟外科医疗队的事宜。",
    [6626] = "杀掉8个剃刀沼泽护卫者、8个剃刀沼泽织棘者和8个亡首教徒，然后向剃刀高地入口处的麦雷姆·月歌复命。",
    [6627] = "成功回答布劳格·幽魂的问题，然后和他再次对话。他会一直在石爪山等你回答问题。",
    [6628] = "成功回答帕科瓦·芬塔拉斯的问题，然后再次和他对话。他会一直在幽暗城等你回答问题。",
    [6629] = "杀掉格鲁迪格·暗云和6个恐怖图腾蛮兵，然后向石爪山东南面的玛卡巴·扁蹄复命。",
    [6641] = "在穆格拉什寻找火盆的过程中保证他的安全。帮助他扑灭火盆，然后在与纳迦作战时保护他。 如果你成功了，就回到佐拉姆加前哨站去，把鞭笞者沃尔沙的死讯通知给战歌信使。",
    [6661] = "使用捕鼠者之笛捕获5只矿道老鼠，把它们引到蒙提那儿去。别忘了退还笛子。",
    [6662] = "把装着神秘肉品的纸箱交给暴风城矿道地铁仓库的尼普希。",
    [6681] = "把拉文霍德徽记交给拉文霍德庄园的法拉德，庄园就坐落在希尔斯布莱德的群山之中。 你的智慧将在这次旅途中得到考验。做好准备吧。",
    [6721] = "与多兰纳尔的达扎拉谈一谈。",
    [6722] = "与多兰纳尔的达扎拉谈一谈。",
    [6761] = "与达纳苏斯的塞纳里奥区的玛斯雷·驭熊者谈一谈。",
    [6762] = "与月光林地永夜港的拉比恩·萨图纳谈一谈。月光林地在费伍德森林和冬泉谷之间，可以从木喉要塞中的一条通道抵达那里。",
    [6804] = "对东瘟疫之地的被感染的水元素使用海神之水。把12副不谐护腕和海神之水交给艾萨拉的海达克西斯公爵。",
    [6805] = "杀死15个灰尘风暴和15个沙漠奔行者，然后回到艾萨拉的海达克西斯公爵那儿。",
    [6821] = "将艾博希尔之眼交给艾萨拉的海达克西斯公爵。",
    [6822] = "杀死一个火焰之王、一个熔岩巨人、一个上古熔火恶犬和一个熔岩奔腾者，然后回到艾萨拉的海达克西斯公爵那里。",
    [6823] = "在海达希亚水元素中达到被尊敬的声望，然后与艾萨拉的海达克西斯公爵谈一谈。",
    [6824] = "将鲁西弗隆之手、萨弗隆之手、基赫纳斯之手和沙斯拉尔之手交给艾萨拉的海达克西斯公爵。",
    [6844] = "将异种蝎粘液包裹的物体交给月光林地永夜港的阿姆伯尔，他是塞纳里奥议会的档案管理员。",
    [6845] = "与月光林地永夜港的拉比恩·萨图纳谈一谈。",
    [6921] = "把深渊之核交给灰谷佐拉姆加前哨站里的耶努萨克雷。",
    [6922] = "把奇怪的水球交给灰谷佐拉姆加前哨站的耶努萨克雷。",
    [6981] = "寻找更多有关这块噩梦碎片的信息。",
    [6982] = "把10份冷齿矿洞补给品交给丹巴达尔的联盟军需官。",
    [6985] = "把10份深铁矿洞补给品交给霜狼要塞的部落军需官。",
    [7001] = "找到奥特兰克山谷中的霜狼。使用霜狼口套来驯服它们。被驯服的霜狼会跟随你回到兽栏管理员那里，然后与兽栏管理员谈话以获得你的奖励。",
    [7003] = "使用索尔宾的超级压缩器，把菲拉斯的任意巨人缩小到便于对付的体型。从缩小后的巨人身上收集15份微缩残渣，交给菲拉斯被遗忘的海岸码头上的索尔宾·范达瑟。",
    [7027] = "找到奥特兰克山谷中的山羊。使用雷矛训练颈圈来驯服它们。被驯服的山羊会跟随你回到兽栏管理员那里，然后与兽栏管理员谈话以获得你的奖励。",
    [7028] = "为凄凉之地的维洛收集25个瑟莱德丝水晶雕像。",
    [7029] = "在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。 在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。 治疗8株植物并杀死那些诺克赛恩幼体，然后向葬影村的瓦克·战痕复命。",
    [7041] = "在玛拉顿里用天蓝水瓶在橙色水晶池中装满水。 在维利斯塔姆藤蔓上使用装满水的天蓝水瓶，使堕落的诺克赛恩幼体出现。 治疗8株植物并杀死那些诺克赛恩幼体，然后向尼耶尔前哨站的塔琳德莉亚复命。",
    [7044] = "找回塞雷布拉斯节杖的两个部分：塞雷布拉斯魔棒和塞雷布拉斯钻石。 然后设法和塞雷布拉斯对话。",
    [7046] = "帮助赎罪的塞雷布拉斯制作塞雷布拉斯节杖。 当仪式完成之后再和他谈谈。",
    [7064] = "杀死瑟莱德丝公主，然后回到凄凉之地葬影村附近的瑟琳德拉那里复命。",
    [7065] = "杀死瑟莱德丝公主，然后回到凄凉之地尼耶尔前哨站的守护者玛兰迪斯那里复命。",
    [7066] = "到月光林地去找到雷姆洛斯，将生命之种交给他。",
    [7067] = "阅读贱民的指引，然后从玛拉顿得到联合坠饰，将其交给凄凉之地南部的半人马贱民。",
    [7068] = "从玛拉顿收集10块暗影残片，然后把它们交给奥格瑞玛的尤塞尔奈。",
    [7070] = "从玛拉顿收集10块暗影残片，然后把它们交给尘泥沼泽塞拉摩岛上的大法师特沃什。",
    [7081] = "占领一座墓地，然后向丹巴达尔的诺雷格·雷矛中尉复命。",
    [7082] = "占领一座墓地，然后向霜狼村的亚斯拉复命。",
    [7101] = "占领敌方的某座哨塔，然后向霜狼村的提卡·血牙复命。",
    [7102] = "摧毁敌方的某座哨塔或者碉堡中的旗帜，然后向丹巴达尔的杜尔根·雷矛复命。",
    [7121] = "与雷矛军需管谈一谈。",
    [7122] = "占领一座还没有被雷矛部族控制的矿洞，然后向丹巴达尔的雷矛军需官复命。",
    [7123] = "与霜狼军需官谈一谈。",
    [7124] = "占领一座矿洞，然后向霜狼村的霜狼军需官报告。",
    [7141] = "进入奥特兰克山谷，击败部落将军德雷克塔尔。然后回到勘查员塔雷·石镐那里。",
    [7142] = "进入奥特兰克山谷，击败矮人将军范达尔·雷矛。然后回到沃加·死爪那里。",
    [7161] = "到主基地东南边的蛮爪洞穴中去找到霜狼军旗，然后把它交给拉格隆德。",
    [7162] = "到主基地东南边的冰翼洞穴中去找到雷矛军旗，然后把它交给哈格丁中尉。",
    [7181] = "血怒者科尔拉克躲在冰斧洞穴的深处。据说只有在第1001个冰斧巨魔被干掉的时候，这个强大的冰斧巨魔领袖才会出现。 到冰斧洞穴中去，杀掉所有挡在你面前的巨魔，直到科尔拉克出现为止。杀掉科尔拉克，然后向拉格隆德复命。",
    [7201] = "前往黑石深渊，找回10份元素精华。你首先想到的是搜查魔像和魔像制造者。你还记得薇薇安·拉格雷含糊地提到过元素生物。",
    [7202] = "血怒者科尔拉克躲在冰斧洞穴的深处。据说只有在第1001个冰斧巨魔被干掉的时候，这个强大的冰斧巨魔领袖才会出现。 到冰斧洞穴中去，杀掉所有挡在你面前的巨魔，直到科尔拉克出现为止。杀掉科尔拉克，然后向哈格丁中尉复命。",
    [7223] = "给丹巴达尔的莫高特·深炉带去20块护甲碎片。",
    [7224] = "给霜狼村的铁匠雷格萨带去20块护甲碎片。",
    [7241] = "到希尔斯布莱德丘陵地区的奥特兰克山谷去。找到拉格隆德并和他谈谈，然后成为霜狼氏族的士兵。",
    [7261] = "到希尔斯布莱德丘陵地区的奥特兰克山谷去。到那里之后，和哈格丁中尉谈谈。 为了铜须的荣耀！",
    [7281] = "深入雷矛部族的领地，杀掉指挥官卡尔·菲利普。任务完成之后向指挥官刘易斯·菲利普复命。",
    [7282] = "深入霜狼氏族的领地，杀掉指挥官刘易斯·菲利普。任务完成之后，回到指挥官卡尔·菲利普处复命。",
    [7301] = "到霜狼氏族的领地中去搜寻空军指挥官斯里多尔、空军指挥官维波里和空军指挥官艾克曼。任务完成之后向指挥官杜菲复命。",
    [7302] = "找到空军指挥官古斯、空军指挥官杰斯托和空军指挥官穆维里克。任务完成之后向挥官穆法特复命。",
    [7321] = "给塔伦米尔的克里斯托弗·杰弗寇特带去10块海龟肉和一些舒心草。",
    [7366] = "你被指派去杀死奥特兰克山谷中的被遗忘者玩家。 杀死一个被遗忘者，然后把一枚被遗忘者的精华交给指挥官卡尔·菲利普（他一般在伐木场和矿井之间徘徊）。",
    [7381] = "如果科尔拉克重新出现在奥特兰克山谷的冰斧山洞中，就找到并干掉他。 将科尔拉克的徽记交给霜狼要塞的拉格隆德。",
    [7382] = "如果科尔拉克重新出现在奥特兰克山谷的冰斧山洞中，就找到并干掉他。 将科尔拉克的徽记交给丹巴达尔的哈格丁中尉。",
    [7383] = "用月亮井的水装满紫水晶瓶，然后把它交给多兰纳尔的科瑞萨斯·月怒。",
    [7441] = "到厄运之槌去找到小鬼普希林。你可以使用任何手段从小鬼那里得到埃斯托尔迪的咒术之书。 找到咒术之书后，回到拉瑞斯小亭的埃斯托尔迪那里。",
    [7461] = "你必须干掉5座水晶塔周围的守卫，那5座水晶塔维持着关押伊莫塔尔的监狱。一旦水晶塔的能量被削弱，伊莫塔尔周围的能量力场就会消散。 进入伊莫塔尔的监狱，干掉站在中间的那个恶魔。最后，在图书馆挑战托塞德林王子。 当任务完成之后，到庭院中去找辛德拉古灵。",
    [7463] = "到厄运之槌的扭木广场去杀掉水元素海多斯博恩。把海多斯博恩精华交给图书馆的博学者莱德罗斯。",
    [7481] = "到厄运之槌去寻找泰尔米乌斯·探梦者。向莫沙彻营地的先知科鲁拉克报告你所找到的信息。",
    [7482] = "到厄运之槌去寻找泰尔米乌斯·探梦者。向羽月要塞的学者卢索恩·纹角报告你所找到的信息。",
    [7483] = "将急速圣典、1块原始黑钻石、2份大块魔光碎片和2份英雄之血交给厄运之槌的博学者莱德罗斯，以换取一份急速秘药。",
    [7484] = "将专注圣典、1块原始黑钻石、4份大块魔光碎片和2张暗影之皮交给厄运之槌的博学者莱德罗斯，以换取一份专注秘药。",
    [7485] = "将防护圣典、1块原始黑钻石、2份大块魔光碎片和1份磨损的憎恶缝合线交给厄运之槌的博学者莱德罗斯，以换取一份防护秘药。",
    [7486] = "从海达克西斯的箱子拿取你的奖励。",
    [7488] = "把蕾瑟塔蒂丝的网交给菲拉斯羽月要塞的拉托尼库斯·月矛。",
    [7489] = "把蕾瑟塔蒂丝的网交给非拉斯莫沙彻营地的塔罗·刺蹄。",
    [7490] = "将奥妮克希亚的头颅交给奥格瑞玛的萨尔。",
    [7491] = "在力量谷找到伦萨克。",
    [7492] = "和菲拉斯莫沙彻营地的塔罗·刺蹄谈一谈。",
    [7494] = "和菲拉斯羽月要塞的拉托尼库斯·月矛谈一谈。",
    [7495] = "将奥妮克希亚的头颅交给暴风城的伯瓦尔·弗塔根公爵。",
    [7496] = "在英雄谷找到玛丁雷少校。",
    [7498] = "将这本典籍交给它的主人。",
    [7499] = "将这本典籍交给它的主人。",
    [7500] = "将这本典籍交给它的主人。",
    [7501] = "将这本典籍交给它的主人。",
    [7502] = "将这本典籍交给它的主人。",
    [7503] = "将这本典籍交给它的主人。",
    [7504] = "将这本典籍交给它的主人。",
    [7505] = "将这本典籍交给它的主人。",
    [7506] = "将这本典籍交给它的主人。",
    [7507] = "将《诺斯特罗的屠龙技术纲要》还回图书馆。",
    [7508] = "把黯淡的精灵剑交给博学者莱德罗斯。",
    [7509] = "你必须设法让奥妮克希亚对这把未淬火的的上古之刃喷射火焰。完成之后，捡起加热过的上古之刃。你要注意的是，加热过的上古之刃不会一直保持被加热的状态，时间非常紧迫。 在把它给我拿回来之前的最后一步是杀掉那条龙，并将加热过的上古之刃插入她的尸体中。 完成这些之后，奎尔塞拉就是你的了。",
    [7562] = "与燃烧平原的莫苏尔·召血者谈一谈。",
    [7563] = "把30瓶狂暴野兽的血交给燃烧平原的莫苏尔·召血者。",
    [7564] = "把血箱交给燃烧平原的戈瑟奇·邪眼。",
    [7581] = "到菲拉斯的厄运之槌去，从扭木广场的荒野萨特身上找到15份萨特之血，然后把它们交给腐烂之痕的戴奥。",
    [7582] = "到冬泉谷的暗语峡谷去，从盘踞在峡谷中的赫达琳恶魔身上找到5块赫达琳之泪。完成任务之后回到腐烂之痕的戴奥那里。",
    [7583] = "在腐烂之痕中找到一个末日守卫指挥官。 对其使用光芒水晶监牢。你要做好承受疯狂攻击的准备，那个恶魔会拼命挣扎试图逃脱。 如果你成功了，就把被囚禁的末日守卫交给腐烂之痕的戴奥。",
    [7601] = "与费伍德森林的伊普斯谈一谈。",
    [7602] = "费伍德的伊普斯要求你从三个不同的地区收集三块无暇的恶魔精华，然后把它们交给他。 艾萨拉的雷加斯萨特、费伍德森林的加德纳尔军团士兵和诅咒之地的地狱卫士斥候分别拥有一种无暇的恶魔精华。",
    [7603] = "在费伍德森林的碎痕谷中搜寻克罗苏斯的尸体。当你找到尸体后，在他身上使用魔火，并等待克罗苏斯复生。当这个地狱火被唤醒之后，干掉他，从他的身上拿取克罗苏斯的恶魔之核。 把克罗苏斯的恶魔之核交给费伍德森林的尼比。",
    [7604] = "如果你愿意接受萨弗隆的设计图，请将瑟银兄弟会契约交给罗克图斯·暗契。",
    [7622] = "在总计有15个农夫被杀死之前拯救50个农夫。完成任务之后与艾瑞斯·哈文法谈谈。 你可以通过浏览死亡布告来了解自己拯救了多少农夫。",
    [7623] = "从燃烧平原的戈瑟奇那里购买暗影药水。 使用这种药剂进入加德纳尔，然后与魔王贝恩霍勒谈一谈。",
    [7624] = "找到并杀死乌拉泰克，然后把叛徒之心交给加德纳尔的魔王贝恩霍勒。",
    [7625] = "从乌尔丹那里购买克索诺斯星尘，把它交给燃烧平原的戈瑟奇·邪眼。",
    [7626] = "把10瓶暗影之力药剂交给燃烧平原的戈瑟奇·邪眼。",
    [7627] = "把6份大块魔光碎片和25块黑铁矿石交给燃烧平原的戈瑟奇·邪眼。",
    [7628] = "把35块黑龙鳞片交给燃烧平原的戈瑟奇·邪眼。",
    [7629] = "把瓶中的小鬼带到通灵学院的炼金实验室中。在小鬼制造出羊皮纸之后，把瓶子还给戈瑟奇·邪眼。",
    [7630] = "把3块奥金锭交给燃烧平原的戈瑟奇·邪眼。",
    [7631] = "阅读莫苏尔的指南，并召唤出一匹克索诺斯恐惧战马，击败它，然后控制它的灵魂。",
    [7632] = "找到远古石叶的主人。祝你好运，<name>。这个世界是很大的。",
    [7634] = "费伍德森林的古树哈斯塔特要求你带回一块成年蓝龙的肌腱。",
    [7635] = "费伍德森林的古树斯托玛要求你带给他一块成年黑龙的肌腱。",
    [7636] = "你必须找到并干掉下列4个恶魔： 迷人的西蒙妮。 疯狂的克林弗兰。 S屠杀者索伦诺尔。 摧毁者阿托留斯。 杀掉这些恶魔，然后回到费伍德森林的古树瓦特鲁斯那里去。 根据你背包中的石化树皮来找到它们所在位置的线索。 你必须独自完成这个任务。",
    [7637] = "到铁炉堡去找高阶牧师洛汉，从他那里拿到驱魔香炉。你需要捐赠150金币来获得它。",
    [7638] = "与暴风城教堂区的格雷森·沙东布瑞克公爵谈一谈。",
    [7639] = "把驱魔香炉交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
    [7640] = "使用驱魔香炉召唤恐惧谷中的灵魂。当你杀掉25个恐惧谷的灵魂之后，回到暴风城教堂区的格雷森·沙东布瑞克公爵那里复命。",
    [7641] = "与暴风城矮人区的格瑞曼德·艾尔默谈一谈。",
    [7642] = "把40块符文布、6块奥金锭、10棵阿尔萨斯之泪、5瓶斯坦索姆圣水和150枚金币交给暴风城矮人区的格瑞曼德·艾尔默。",
    [7643] = "你需要特殊的饲料来喂养灵魂马。南海镇的梅丽德丝·卡尔森可以为你提供这样的粮草。 到菲拉斯的厄运之槌去，杀掉特迪斯·扭木，释放上古圣马之魂。用特殊的粮草喂养它，这样可以安抚它的灵魂。最后，把奥金马铠交给它就可以完成祝福。",
    [7644] = "将被祝福的奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
    [7645] = "把制作魔法粮草所需要的重要材料：20块可口的魔法点心带给希尔斯布莱德丘陵的梅丽德丝·卡尔森。据说银色黎明会出售这种饼干。 你还需要给她50金币来对她进行安抚。",
    [7646] = "把一块艾泽拉斯钻石和一块原始黑钻石交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
    [7647] = "在通灵学院尸骨储藏所地下室的中心使用预言水晶球。将你要审判的灵魂引领出来。将这些灵魂击败然后死亡骑士达克雷尔就将被召唤出来。将其击败然后获得堕落战马的灵魂。 把赎罪的战马之魂和被祝福的奥金马铠一起附在达克雷尔的堕落战马身上。",
    [7648] = "把奥金马铠交给暴风城教堂区的格雷森·沙东布瑞克公爵。",
    [7649] = "将这本典籍交给它的主人。",
    [7650] = "将这本典籍交给它的主人。",
    [7651] = "将这本典籍交给它的主人。",
    [7667] = "如果你愿意帮助奥格瑞玛智慧谷的萨格尼，就将一块艾泽拉斯钻石和一块原始黑钻石交给他。",
    [7670] = "与暴风城教堂区的格雷森·沙东布瑞克公爵谈一谈。",
    [7701] = "那个叫做工头玛托留斯的黑铁矮人叛徒就藏在大熔炉的熔渣之池深处。 杀死工头玛托留斯，将他的头颅交给灼热峡谷的侦查队长洛洛尔以换取你的奖励。",
    [7703] = "找到戈多克力量护手，并将它交给厄运之槌的克罗卡斯。 根据克罗卡斯所说的，“传说”自称是王子的精灵托塞德林从一名戈多克食人魔手中偷走了那件神器。",
    [7721] = "从菲拉斯被遗忘的海岸那里的海元素和巨型海元素身上获取10块水元素核心，把它们交给码头附近的索尔宾·范达瑟。",
    [7722] = "在大熔炉的熔渣之池中的某个地方，你可以找到工头玛托留斯偷走的秘密设计图：炽热助熔剂。找到这些设计图，把它们还给灼热峡谷的大铁匠博恩奈特。",
    [7723] = "汉瑟尔·重拳让你杀掉20个重型作战傀儡。 重型作战傀儡就在灼热峡谷的大熔炉附近。当你杀死足够多的傀儡后，就回去找汉瑟尔·重拳。",
    [7724] = "汉瑟尔·重拳要你在灼热峡谷杀死20只灼热熔岩蜘蛛。你可以在灼热峡谷的高地和熔岩池附近找到它们。 杀死足够多的灼热熔岩蜘蛛后，回去向灼热峡谷的汉瑟尔·重拳复命。",
    [7725] = "使用索尔宾的超级压缩器来缩小菲拉斯的任意种类的巨人，将他们缩小到更容易控制的体积。从缩小过的巨人身上收集10份微缩残渣，把它们交给菲拉斯被遗忘的海岸码头的索尔宾·范达瑟。",
    [7726] = "从菲拉斯被遗忘的海岸那里的海元素和巨型海元素身上获取6块水元素核心，把它们交给码头附近的索尔宾·范达瑟。",
    [7727] = "汉瑟尔·重拳让你去杀掉20个熏火龙。 熏火龙侵占了熔渣之池中的那些岩浆池。熔渣之池就在灼热峡谷的大熔炉中。 当你杀死足够数量的熏火龙后，就回去找汉瑟尔·重拳。",
    [7728] = "找到冶炼鼓风机和侦查员的望远镜，把它们还给灼热峡谷的监工斯克兰格。 你所知道的关于这些物品的惟一信息是：它们肯定是被黑铁矮人偷走的。冶炼鼓风机是铁匠用的锻造工具，侦查员的望远镜是侦查员所需的侦查工具。",
    [7729] = "杀死15个黑铁工头和15个黑铁奴隶贩子。完成任务之后就回去找监工斯克兰格。",
    [7730] = "把20块祖卡什虫壳交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。",
    [7731] = "击败痛苦深渊中的毒刺鞭笞者，把它的腺体交给菲拉斯莫沙彻营地的哈杜肯·迅蹄。",
    [7732] = "把莫沙彻营地祖卡什报告交给奥格瑞玛暗巷区的基尔兹宾·鼓眼。",
    [7733] = "把10块怒痕雪人的毛皮交给菲拉斯羽月要塞的普拉特·马克格鲁比。",
    [7734] = "把10块怒痕雪人的毛皮交给菲拉斯莫沙彻营地的杉多尔·迅蹄。",
    [7735] = "把原始雪人毛皮交给菲拉斯羽月要塞的普拉特·马克格鲁比。",
    [7738] = "把完美的雪人毛皮交给菲拉斯莫沙彻营地的杉多尔·迅蹄。",
    [7761] = "真是个愚蠢的兽人。看来你需要找到那枚烙印并获得达基萨斯徽记才可以使用命令宝珠。 你从信中获知，达基萨斯将军守卫着烙印。也许你应该就此进行更深入的调查。",
    [7781] = "将奈法利安的头颅交给暴风城的伯瓦尔·弗塔根公爵。",
    [7782] = "回到暴风城的英雄谷，与艾法希比元帅谈一谈。",
    [7783] = "将奈法利安的头颅交给奥格瑞玛的萨尔。",
    [7784] = "和奥格瑞玛的萨鲁法尔大王谈谈。他在力量谷等你。",
    [7785] = "查看复生之瓶，然后回到德米提恩那里去。",
    [7786] = "如果你想要把逐风者桑德兰从监牢里释放出来，你就必须找到左右两块逐风者禁锢之颅，10块源质锭，以及火焰之王的精华，把它们交给德米提恩。",
    [7787] = "把风吻之刃交给德米提恩。",
    [7810] = "与荆棘竞技场的小个子约翰·米斯瑞尔谈一谈。",
    [7815] = "辛特兰恶齿村的钓鱼者卡图姆要你去杀掉15只海水钳嘴龟。完成任务之后回到他那里去复命。",
    [7816] = "辛特兰恶齿村的钓鱼者卡图姆要你去杀掉加莫里塔，并从它的尸体上找到卡图姆的超级鱼饵。 卡图姆说加莫里塔和其它海龟都在海岸附近活动。",
    [7828] = "辛特兰恶齿村的猎户马克霍尔要求你去杀掉15头银鬃捕猎者和15头银鬃嗥狼。完成任务之后就回到他那里复命。 马克霍尔说过那些狼都躲在辛特兰的野外。",
    [7829] = "辛特兰恶齿村的猎户马克霍尔要求你去杀掉20头野蛮的枭兽。完成任务之后就回到他那里复命。 马克霍尔说过那些野蛮的枭兽都躲在辛特兰的野外。",
    [7830] = "辛特兰恶齿村的猎户马克霍尔要求你杀掉一头翱翔的锋喙狮鹫，并将它的狮鹫长羽拿回去交给他。 马克霍尔说过那些翱翔的锋喙狮鹫就躲在辛特兰的野外。",
    [7839] = "辛特兰恶齿村的铁匠斯拉提要你去找到斯拉提的工具。完成任务之后就回到他那里去。 你记得铁匠斯拉提说过，你可以在辛特兰东北部的某个邪枝巨魔神庙中找到它，要不然就是在隐匿石那边。",
    [7840] = "辛特兰恶齿村的拉尔德要求你去找到拉尔德的午餐。完成任务之后就回到他那里去。 拉尔德说他把午餐留在了北面的岛上。当心邪枝巨魔。",
    [7841] = "辛特兰恶齿村的奥索·莫吉克要你去杀掉15个高原前锋、15个高原斥候、15个高原神射手和15个高原游侠。任务完成之后回到他那里去复命。 你可以在辛特兰西北部的奎尔丹尼小屋找到那些高原精灵。",
    [7842] = "辛特兰恶齿村的奥索·莫吉克要你从辛特兰的狮鹫身上收集10根细长的狮鹫羽毛。任务完成之后回到他那里去复命。 在辛特兰各处都有狮鹫出没。",
    [7843] = "辛特兰恶齿村的奥索·莫吉克要你去辛特兰西部的鹰巢山，把给蛮锤部族的警告插在城镇中心的水井旁边。任务完成之后回到他那里去复命。 当心那些愤怒的蛮锤矮人以及野蛮的联盟成员。",
    [7844] = "辛特兰恶齿村的秘法师雅尔金要你去杀掉30个邪枝割颅者和15个邪枝占卜者。任务完成之后回到他那里去复命。 秘法师雅尔金说过，你可以在辛特兰东北部的沙尔瓦萨和亚戈瓦萨神庙附近找到那些巨魔。",
    [7845] = "辛特兰恶齿村的断齿族长要求你到辛萨罗去拯救她的爱人，断齿长者。 你听说他被关在辛萨罗顶部，辛萨罗位于辛特兰的南部地区，那里是邪枝巨魔的主城。",
    [7846] = "辛萨罗的断齿长者要求你杀掉守护者希坦亚，并用她身上的镣铐钥匙打开他的镣铐。当你找到钥匙之后就回到他那里去。",
    [7847] = "辛萨罗的断齿长者要求你将他已经被营救的消息带给恶齿村的断齿族长。",
    [7848] = "进入黑石深渊，在通往熔火之心的传送门附近找到一块熔火碎片，然后回到黑石山脉的洛索斯·天痕那里。",
    [7849] = "辛特兰恶齿村的猎户马克霍尔要你去找回他的双胞胎兄弟的尸体。找到它，然后把猎户莫克霍尔的头颅和猎户莫克霍尔的骨头交给猎户马克霍尔。 马克霍尔说过，他兄弟的尸体被软泥怪和邪枝巨魔的狼群分食。他还提到在辛萨罗有个大坑，里面全都是软泥怪，那里还有个狼穴。这两个地方都在靠近辛萨罗神庙顶部的区域。",
    [7850] = "辛特兰恶齿村的断齿族长要你在辛萨罗找到10瓶腐化之血。任务完成之后就回到断齿族长那里。",
    [7861] = "你必须杀掉邪恶祭司海克斯和20名邪枝精英守卫。任务完成之后回到辛特兰的恶齿村，向断齿族长报告。 你可以在辛特兰的邪枝巨魔城市辛萨罗的顶部找到他们。",
    [7862] = "你必须消灭20个邪枝狂战士、20个邪枝暗影猎手、20个邪枝饮血者和20个邪枝噬魂者。 完成任务之后向辛特兰恶齿村的断齿族长复命。",
    [7877] = "返回图书馆去找到辛德拉的宝藏。拿取你的奖励吧！",
    [7907] = "当暗月马戏团来到镇上的时候，把野兽套牌交给他们。",
    [7927] = "当暗月马戏团来到镇上的时候，把入口套牌交给他们。",
    [7928] = "当暗月马戏团来到镇上的时候，把督军套牌交给他们。",
    [7929] = "当暗月马戏团来到镇上的时候，把元素套牌交给他们。",
    [8053] = "从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱护腕。你还必须在赞达拉部族中达到友善或更高的声望。 击碎者金罗克在荆棘谷的尤亚姆巴岛上。",
    [8054] = "从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱披肩。你还必须在赞达拉部族中达到尊敬或更高的声望。 击碎者金罗克在荆棘谷的尤亚姆巴岛上。",
    [8055] = "从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱徽章。你还必须在赞达拉部族中达到崇敬或更高的声望。 击碎者金罗克在荆棘谷的尤亚姆巴岛上。",
    [8056] = "从祖尔格拉布把以下权力珍宝交给祖达萨的梅维克：1条原始哈卡莱护臂。你还必须在赞达拉部族中达到友善或更高的声望。 祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。",
    [8057] = "从祖尔格拉布把以下权力珍宝带给祖达萨的梅维克：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友好或更高的声望。 祖达萨的梅维克在荆棘谷的尤亚姆巴岛上。",
    [8058] = "从祖尔格拉布把以下权力珍宝带给击碎者金罗克：1条原始哈卡莱护臂。你还必须在赞达拉部族中达到友善或更高的声望。 击碎者金罗克在荆棘谷的尤亚姆巴岛上。",
    [8059] = "从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友善或更高的声望。 全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。",
    [8060] = "从祖尔格拉布把以下权力珍宝带给全知者阿塔比姆：1条原始哈卡莱护腕。你还必须在赞达拉部族中达到友善或更高的声望。 全知者阿塔比姆克在荆棘谷的尤亚姆巴岛上。",
    [8061] = "从祖尔格拉布把以下权力珍宝交给全知者阿塔比姆：1条原始哈卡莱直柱。你还必须在赞达拉部族中达到友善或更高的声望。 全知者阿塔比姆在荆棘谷的尤亚姆巴岛上。",
