    [93159] = "在影风森林与奇怪的隐士交谈，多了解一下他的情况。",
    [93160] = "在影风森林收集8颗影风橡子。",
    [93165] = "从影风森林、阿基尔神殿或阵风浆果低地的奥拉凯斯密教徒身上收集5件奥拉凯斯教徒的徽饰。",
    [93172] = "在影风森林消灭10个空洞风灵。",
    [93176] = "使用昆虫学入门工具包内的物品，寻找并捕捉一只树栖狼蛛、一份干草象鼻虫样本和一只剔肉蝎。",
    [93188] = "保持你在玛格拉姆的声望，前往白骨之谷北面入口附近，向奥尔格鲁尔复命。",
    [93196] = "保持你在玛格拉姆的声望，举行一场通灵仪式来复活杰恩可汗。仪式场地就在玛格拉姆村中心湖畔的一个帐篷里。",
    [93197] = "将海加尔山顶营地塞贝利亚的邮件包裹交给永望镇的旅店老板维兹奇。",
    [93224] = "消灭凄凉之地任意氏族的半人马，收集5枚雕刻半人马图腾，再交给尼耶尔前哨站的本迪加斯上尉。",
    [93225] = "消灭凄凉之地任意氏族的半人马，收集5枚雕刻半人马图腾，再交给幽灵岗哨的古尔达·蛮鬃。",
    [93226] = "把图腾手提包交给凄凉之地玛格拉姆村的玛格拉姆军需官，以大幅提高你在该氏族中的声望。你在玛格拉姆半人马中的声望至少必须达到中立。",
    [93227] = "把图腾手提包交给凄凉之地吉尔吉斯村的吉尔吉斯军需官，以大幅提高你在该氏族中的声望。你在吉尔吉斯半人马中的声望至少必须达到中立。",
    [93269] = "将信件从永望镇带给海加尔山顶的旅店老板塞贝利亚。",
    [93317] = "收集6块风歌爬行者肉。",
    [93318] = "在申达尔高地消灭贪得无厌的乌尔加拉，将她的头颅带给达纳瑞·怒面。",
    [93319] = "从申达尔高地的高地强盗手中夺回10块被偷走的风石。",
    [93320] = "向阵风浆果低地东部瞭望塔的尤拉娜·风苇报到。",
    [93341] = "调查辛德拉附近的荒弃花园，然后回到附近神殿找米瑟拉复命。",
    [93362] = "在荒弃花园中清理植物，然后回到辛德拉向米瑟拉复命。",
    [93383] = "等待个人生存包的安全机制解除并打开它。",
    [93394] = "在辛德拉神殿内找到魔导师基兰迪斯。",
    [93404] = "深入玛拉顿，取回一瓶大地之歌水。将其带回凄凉之地，交给荒弃花园的林地怪。",
    [93406] = "在永望镇北边的山丘中寻找4封丢失的信件，将其带给旅店老板维兹奇。",
    [93407] = "在海加尔山顶的森林中寻找荆棘种子，将其带给蒂亚拉·白鬃。",
    [93422] = "击杀黑棘信使，并截获她的密信。",
    [93429] = "在农田避难所消灭10名失落者。",
    [93430] = "找到偷走佩卢克鱼饵的失落者渔夫，并将鱼饵夺回来。",
    [93443] = "将遗失的货箱交给河林爆破引线港的弗里兹·法拉兹斯帕克。",
    [93444] = "猎杀一只夜刃豹守卫，然后在山顶北部的山脊上，用夜刃豹守卫的大腿肉做诱饵，引出并击杀甘苏罗克。 带着奇美拉的心脏回来复命。",
    [93450] = "拿走维达尔未完工的剑，想办法将它送入灵魂界，然后把幻象之刃交还给辛德拉的维达尔。",
    [93461] = "在申达尔村与拉西里尔·日矛和科里埃拉·平风交谈。",
    [93464] = "找到凄凉之地那名了解德莱尼水晶力量的法师。",
    [93465] = "取得吉玛什关于德莱尼水晶的笔记，然后带回给阿佐尔·奥达蒙特。",
    [93510] = "在止水湖寻找战争精英童年记忆中的船锚。",
    [93521] = "将维罕的研究笔记交给蒂亚拉·白鬃。",
    [93546] = "在辛德拉附近寻找鬼铁矿脉，收集10块鬼铁矿石。凑齐后，返回辛德拉找维达尔。",
    [93547] = "在忠诚派德鲁伊营地的旅店、储物塔和树丛附近种下荆棘种子。",
    [93551] = "使用刺绣剑鞘，在海加尔山悲泣之眠的破损火炮旁与战争精英会面。",
    [93552] = "从森达尔林地的原始风石上收集15个风石簇。",
    [93567] = "在悲泣之眠的破损火炮旁，听战争精英讲述往事。",
    [93568] = "把消化了一半的项圈交给知晓其来历的人。想必在凄凉之地的辛德拉或附近能找到此人。",
    [93574] = "寻找一个对食尸者的甲壳感兴趣的人。",
    [93584] = "消灭10个黑棘专家和10个狂野印记教徒。",
    [93585] = "护送塔特尔神父前往避难营。",
    [93594] = "在凄凉之地辛德拉的荒弃花园找到林地怪。",
    [93601] = "在刺背避难所寻找一位有头有脸的野猪人。",
    [93604] = "深入剃刀高地，取回剧毒的阿迦玛甘之血。将其交给凄凉之地刺背避难所的勇敢的科格苏格。科格苏格特意强调过，剃刀沼泽里的阿迦玛甘之血糊弄不了他。",
    [93606] = "平息野猪人之间的争端，为库尔加带去仁慈的花束和剧毒的阿迦玛甘之血。制作花束所需的花朵，可在凄凉之地辛德拉附近的荒弃花园中采集。",
    [93609] = "将遗忘项链带给凄凉之地辛德拉神殿的米瑟拉。",
    [93615] = "在海加尔山的荒野中找到沙拉卡尔的小猫。",
    [93617] = "阻止雄鹿们扮演捕食者的行为。",
    [93644] = "这些文字暗示，这本日记的作者可能就在辛德拉的某处。",
    [93663] = "找到失踪的信使，确保达尔的货物被送到避难营。",
    [93678] = "将阿佐尔誊写的笔记带回悲伤沼泽避难营，交给玛格图尔。",
    [93679] = "与玛格图尔一起观看昂库的幻象。",
    [93680] = "为塔伦米尔的大法师沃迪恩·伍德格莱尔取得达拉然下水道钥匙。",
    [93684] = "在诅咒之地找到那名正在寻找德莱尼水晶的德莱尼人。",
    [93685] = "在诅咒之地找到一颗无暇的德莱尼水晶球，并将其交给收藏家库米沙。 注意，这种宝石是整个艾泽拉斯最稀有的水晶之一。这片土地上的任何生物都可能携带无暇的德莱尼水晶球。",
    [93735] = "在瓦拉纳尔西侧找到里阿尼·夜风。",
    [93736] = "从影风森林的空洞风灵身上收集10份空洞风灵精华。",
    [93737] = "与里阿尼·夜风交谈，听听他有什么要说的。",
    [93738] = "向瓦拉纳尔的阿耶莎·晨歌复命。",
    [93739] = "到格罗玛什要塞向纳兹格雷尔询问指引，再依照他的指示，分别拜访沃金、凯恩·血蹄和希尔瓦娜斯·风行者女士。",
    [93740] = "从阵风浆果低地的奥拉凯斯密教徒尸体上收集10个奥拉凯斯风石护符。",
    [93746] = "在前往阿基尔神殿的路上与贝拉萨恩·明愿对峙。",
    [93747] = "在毁坏的弩车、毁坏的投石车和毁坏的飞行器附近种下附魔种子。",
    [93759] = "从纯净的海加尔雄鹿身上收集2块海加尔鹿肉排，并收集6个血色飞镖块茎，用来制作隐士的炖肉。",
    [93773] = "向海加尔山的凯萨拉斯复命。",
    [93786] = "消灭12名草甸溪农场雇农，然后带着你胜利的消息向克罗姆罗什复命。",
    [93787] = "从草甸溪的联盟农场偷取6个饲料袋，然后向克罗姆罗什复命。",
    [93788] = "从特纳的伐木场的伐木工那里，为洛格玛的克雷扎·暗棘夺回10把木匠的斧头。",
    [93791] = "与瓦拉纳尔的贝兰·风木交谈。",
    [93797] = "将注入风之力的树枝带给瓦拉纳尔的贝兰·风木。",
    [93825] = "收集12簇月纱苔藓，将其交给苏玛·苔鬃。",
    [93826] = "击败8名死木图腾师和8名死木邪能看护者，然后向长者松语者复命。",
    [93827] = "收集16个附魔鹰身人护符，将其交给索邦·树液之爪。",
    [93828] = "从树皮地洞周围收集10株风干的悬挂草药，并将其交给芬纳·苔鬃。",
    [93830] = "在死木熊怪兽穴外的池塘里，装满芬纳·苔鬃提供的水袋。",
    [93831] = "在海加尔山收集30串熊果，将其交给奥斯·迷雾之爪。",
    [93833] = "将5具猫头鹰尸体带给海加尔山树皮地洞的长者松语者。",
    [93834] = "为达拉·白颚收集10份掘地甲虫碎片。",
    [93835] = "穿过传送门前往上方的罗哈什尖塔，与伊拉德林·晚风和阿耶莎·晨歌会合，共同对抗高阶女祭司洛苏娜。",
    [93836] = "在瓦拉纳尔与塔拉尼斯·影歌交谈。",
    [93848] = "返回凯萨拉斯处，向他报告永恒之巅发生的事情。",
    [93926] = "在西部瞭望塔找到维和者瓦尼尔。",
    [93927] = "收集在阵亡维和者附近找到的便笺，看看接下来该怎么做。",
    [93948] = "将影歌家族的图章戒指交给瓦拉纳尔的塔拉尼斯·影歌。",
    [93949] = "在瓦拉纳尔击杀天空跳跃者，直到消灭8只被施法的天空跳跃者。",
    [93951] = "在申达尔高地收集8根角鹰兽绒毛。",
    [93952] = "击败9名死木兽穴守卫并向布莱鲁法复命。",
    [93958] = "在阿基尔神殿的内殿与瓦伦妮亚·风暴之拳交谈。",
    [93963] = "到暴风要塞向兰达尔·埃默森询问指引，再依照他的指示，分别拜访国王麦格尼·铜须、大工匠梅卡托克和泰兰德·语风。",
    [93976] = "将利刃交给洛格玛东面码头处克雷扎·暗棘的熟人。",
    [94003] = "从阿基尔神殿的扎尔·风暴之盾手里夺回破天者壁垒。",
    [94004] = "备齐客户要求的物品，并将其送至地图上标记的地点。你必须携带本文书才能完成交易。",
    [94006] = "在瓦拉纳尔东北方的瀑布附近与乌尔森德里斯交谈。",
    [94007] = "向瓦拉纳尔的奎尔阿娜·疾风报到。",
    [94013] = "在阵风浆果低地使用驯兽棒驯服一只瓦尔德伦头狼。磨炼你的驯兽技巧，然后把驯兽棒还给瓦拉纳尔的奎尔阿娜·疾风。",
    [94050] = "与瓦拉纳尔的奎尔多拉·疾风交谈。",
