    [94369] = "在瓦拉纳尔与塔拉尼斯·影歌交谈。",
    [94373] = "收集2个霜鬃熊坠饰，交给安威玛尔的提欧·暴风之锤。",
    [94374] = "找到灵魂石，并饮下大地灵契。",
    [94375] = "将粗糙的石英交给安威玛尔的提欧·暴风之锤。",
    [94411] = "在申达尔高地消灭6名高阶会学徒。",
    [94413] = "在申达尔高地消灭6名塑风者见习先知。",
    [94414] = "与哈兰·鹰眼交谈，借用他的天赋去观察远处的锚点水晶塔。",
    [94427] = "与幽暗城的塔尼斯·桤木交谈。",
    [94434] = "收集10块亚麻布，交给幽暗城的塔尼斯·桤木。",
    [94435] = "返回班达里安堡，向丹妮莎·莫尔复命。",
    [94436] = "在班达里安堡与亡灵卫兵比尔穆斯交谈。 如果你遗失了生命符记，请返回丹妮莎·莫尔处重新领取。",
    [94438] = "携带生命符记，使用它在毒蛛峡谷复活亡灵卫兵法尔甘。 如果你遗失了生命符记，请返回丹妮莎·莫尔处重新领取。",
    [94440] = "从毒蛛峡谷的血色十字军战士处取回血色十字军的攻击计划，随后返回班达里安堡，将其交给亡灵卫兵比尔穆斯。",
    [94441] = "与班达里安堡中的丹妮莎·莫尔交谈。",
    [94449] = "在丹莫罗找到布鲁格斯·燃生。",
    [94465] = "将眠炎火炬带给洛克莫丹的布拉尔迪·灰烬披风。",
    [94466] = "收集1份火焰焦油和1个试剂袋，交给洛克莫丹的布拉尔迪·灰烬披风。",
    [94467] = "击败火焰之魂，将余烬放入恒焰圣殿顶部的火盆。",
    [94468] = "将恒焰火炬带给丹莫罗的布鲁格斯·燃生。",
    [94479] = "在污染山麓寻找对你找到的金属零件感兴趣的人。",
    [94480] = "将偷来的饲料交给洛格玛的戈尔格。",
    [94481] = "在训练场喂饱8名洛格玛受训者。",
    [94483] = "在河流以南消灭8个法霍德牧师和12个法霍德斥候。",
    [94484] = "前往影风森林东北部，寻找并与埃莱盖尔·刺爪交谈。",
    [94485] = "收集8簇贵妇之泪苔藓。",
    [94486] = "在影风森林从影风尖啸幼兽身上收集20根羽毛。",
    [94487] = "从影风森林的奥拉凯斯步兵和奥拉凯斯逐风者身上收集10件染血的传家宝。",
    [94488] = "击杀指挥官哈利恩，并将他的徽记交给影风森林的埃莱盖尔·刺爪。",
    [94489] = "进入夜牙兽穴治疗7名德鲁伊，并在影风森林找到乔雷尔·风歌。",
    [94490] = "将撕破的信件交给影风森林的埃莱盖尔·刺爪。",
    [94491] = "将信件交给瓦拉纳尔的洛瑟鲁姆，向他报告这儿发生的一切。",
    [94494] = "在洛克莫丹找到诺里克·洛克赛恩。",
    [94495] = "在湿地找到赫尔夫达娜·赛格伦德。",
    [94497] = "在赫尔夫达娜洞穴下方的瀑布底部，灌满空的棕色水囊，然后返回湿地交给她。",
    [94499] = "在石堡瀑布附近的鱼人夜行者处，灌满空的红色水囊，然后返回湿地交给赫尔夫达娜·赛格伦德。",
    [94500] = "在灰谷阿斯特兰纳的水域，灌满空的蓝色水囊，然后返回湿地交给赫尔夫达娜·赛格伦德。",
    [94501] = "将一瓶最纯净的水带给洛克莫丹的诺里克·洛克赛恩。",
    [94502] = "喝下水之灵契，涤净西部荒野斯特登的池塘的腐化。 事成后返回洛克莫丹诺里克处复命。",
    [94503] = "在西部荒野与水之魂交谈。",
    [94504] = "将你在树皮地洞的声望提高到中立。",
    [94505] = "将水灵碎片带给洛克莫丹的诺里克·洛克赛恩。",
    [94532] = "为洛格玛的涅扎·血吻消灭8个赤脊山秘法师、8个赤脊山捕兽者和6个赤脊山蛮兵。",
    [94533] = "在刺毛丘陵找到斯纳格尔，将其击杀，并把他的鼻子带给涅扎·血吻。",
    [94535] = "从刺毛丘陵的豺狼人那里为克雷扎·暗棘收集40块被偷走的矿石。",
    [94556] = "护送乔姆-乔姆前往博尔德罗克，将其交给克鲁格菲斯特。",
    [94568] = "与塔拉尼斯·影歌交谈，并旁听对话。",
    [94613] = "前往惠勒的垦野，打听丢失马匹的情况。",
    [94614] = "在惠勒的垦野附近的河畔消灭8个泥鳍智者和8个泥鳍战士。",
    [94615] = "在惠勒的垦野的马厩附近寻找丢失马匹下落的线索。",
    [94617] = "消灭那只名叫“煤皮”的山狗，并将它的皮毛带给本吉·惠勒。",
    [94618] = "找到一匹在山狗袭击后逃离惠勒的垦野的马，喂给它一些饲料。",
    [94638] = "在申达尔高地找到并击杀乌尔恩德拉。",
    [94668] = "向血领主之环竞技场的杰扎普复命。",
    [94669] = "支付安全押金以获得血领主之环竞技场的参赛资格。",
    [94670] = "在血领主之环竞技场击败嗡鸣鸟。",
    [94672] = "为洛格玛的特兰古尔消灭阳光林地中的8名暮光袭击者和8名暮光新教徒。",
    [94678] = "为南哨的塞德里克·道尔顿消灭8个赤脊山秘法师、8个赤脊山捕兽者和6个赤脊山蛮兵。",
    [94679] = "在刺毛丘陵找到并杀死斯纳格尔，把他的徽记带给南哨的塞德里克·道尔顿。",
    [94680] = "为洛格玛的特兰古尔从阳光林地的暮光暗影法师身上夺取3封暮光信件。",
    [94727] = "说服阳光林地的一名暮光之锤矿工，让他泄露秘密。",
    [94733] = "在博尔德罗克找到戈巴姆。",
    [94734] = "为戈巴姆收集8个甜浆果和12棵河草。",
    [94737] = "将这包货物交给博尔德罗克的杰扎普·叮当链。",
    [94739] = "在血领主之环竞技场击败科隆克。",
    [94744] = "在洛格玛以西的丘陵地带找到达格罗什。",
