    [97253] = "从棘齿城以南的海盗上层营地收集5把错综复杂的零件，然后交给棘齿城的卑鄙的维尼克斯。",
    [97263] = "送达埃尔德伦被错放的包裹。",
    [97264] = "清除附近区域的12只老碎齿熊，然后返回莎尔娜·棕角处。",
    [97265] = "在凄凉之地的萨格隆击败各种怨怒萨特，然后返回葬影村的阿卡莱身边。",
    [97275] = "把耶尔玛克的药水交给伍特。",
    [97277] = "去西北面的山丘找到格伦德和戈兹温的营地，取回戈兹温的机械日志，并消灭雪豹潜伏者。",
    [97279] = "收集6件被遗弃的训练武器，然后拿回去交给兽穴的克赞·荆条。",
    [97281] = "把黯淡的风暴宝珠带给枯水谷附近的雷兹拉克。",
    [97282] = "把5个带电的雷霆蜥蜴器官带给枯水谷附近的雷兹拉克。",
    [97284] = "前往凄凉之地的雷斧堡垒，消灭那里的火刃氏族兽人，然后回尼耶尔前哨站向瓦拉里尔·屠魔者复命。",
    [97287] = "与达拉然附近的大法师茉德拉的影像对话。",
    [97288] = "把憎恶头颅带给幽暗城的大药剂师法拉尼尔。",
    [97289] = "将男爵的头颅带到幽暗城中奥斯玛尔的躯体旁。",
    [97290] = "将你的发现汇报给幽暗城的大药剂师法拉尼尔。",
    [97291] = "为幽暗城的大药剂师法拉尼尔收集药材：去贸易区找塔文·格瑞斯特拿一顶剧毒骨帽，在草药学训练师附近采点水疱草，最后去潜行者区找毒药商人买些苦楚精华。",
    [97292] = "替大药剂师法拉尼尔将嘶嘶血清注入奥斯玛尔躯体上方的仪器中。",
    [97319] = "在海加尔山某处找到失踪的表亲。",
    [97326] = "找来8块光滑的巨石，交给格罗玛什要塞后面的斯拉。",
    [97327] = "深入黑喉要塞，为艾萨拉埃达拉斯废墟的埃卡尔寻回5个黑喉袋。",
    [97328] = "从荆棘谷的祖昆达废墟夺回8批被盗的货物，并把你的战利品交给藏宝海湾的某个人。",
    [97329] = "将在荆棘谷祖昆达废墟的巨魔身上找到的粗糙的钥匙，交给齐米克斯·喷火。",
    [97331] = "护送齐米克斯·喷火离开祖昆达废墟，然后向藏宝海湾的码头管理员罗兹基尔复命，告诉他你已经成功救人。",
    [97332] = "把那份两次重订的包裹交给河林爆破引线港的码头管理员维兹巴兹。",
    [97378] = "把镜鳞的翅膀带去交给雷霆崖的梅洛·石蹄。",
    [97386] = "格罗姆高营地的指挥官阿格罗戈什要你前往莫什奥格食人魔山，杀死那里的食人魔。",
    [97403] = "消灭15只冰风破坏者，然后返回冬泉谷北部的瑞兰·霍华德身边。",
    [97404] = "消灭年迈的碎齿熊族母库罗玛和卡穆罗，将它们的徽记带给莎尔娜·棕角。",
    [97405] = "克纳兹·枪焰需要你在莫什奥格食人魔山消灭3名莫什奥格法师、3名莫什奥格好战者、3名莫什奥格虐待者和3名莫什奥格萨满祭司。",
    [97420] = "从纳菲瑞提湖的风险投资公司作业点弄来4桶原油，然后交给荆棘谷的克纳兹·枪焰。",
    [97453] = "铲除格罗姆高南方的6株食肉杂草，然后向格米尔的母亲报告。",
    [97485] = "向草药供应商尼达购买一捆草药，向附魔供应商纳塔购买一捆雪松枝，向制皮供应商曼胡购买筋腱丝线，并向烹饪供应商纳尔购买仪式燧石和火绒。 把这些物品组合起来，然后在猎人高地撒下熏香。",
    [97490] = "在冬泉谷南部的山丘寻找名为冰雹之怨的巨人，取得长在他身上的冰霜苔藓。",
    [97530] = "塔纳利斯热砂港的保安主管图拉·比尔吉维兹要你找回一只格外闪亮的手镯，它遗失在砂槌食人魔营地附近。",
    [97534] = "奎因要你找回7块沙漠废料，并在加基森交还给她。",
    [97536] = "霍尔迪·水炉要你将一箱放射性废料倾倒在塔纳利斯沙漠中远离加基森和其他垃圾的安全地点，然后回去找他。",
    [97538] = "雷霆崖的塔恩·冰蹄需要30份暗色湖的幽暗草荚。",
    [97539] = "将12份外科蛛丝交给阿拉希高地落锤镇的格里高利·维克托医生。",
    [97540] = "为刚刚解了渴的图加指明道路，带他回到妻子托尔塔身边。",
    [97558] = "给舍伦尼·洛巴尔特带去8张夜行蝙蝠翼膜、6张夜行犬皮以及3张邪鳍鱼人皮。",
    [97583] = "购买一些营养丰富的泥浆怪淤泥，回去喂给你结识的那只小软泥怪。如果它显得没精打采，就再陪它跳支舞，重新吸引它的注意力。",
    [97617] = "找回8件未研究的神器、一顶探险者协会采矿头盔和一把无瑕的鹤嘴锄，把它们交给位于洛克莫丹与荒芜之地交界处的多尔加隆。",
    [97663] = "在漫尘盆地消灭食人魔，找回穆斯哈雷失窃的补给品。用它们收集附近石刻的拓片后，返回卡加斯向穆斯哈雷复命。",
    [97821] = "在荒芜之地寻找一名对这项发现感兴趣的人。",
    [97884] = "前往河林的阳光林地，找回特雷曼恩家族锻造技术秘典。",
    [97891] = "在规定时限内，将不稳定药水交给炼金房的马丁·费尔本医生。",
    [97894] = "去黑海岸的奥伯丁找高尔博德·钢手看看情况。 博古斯提过，暴风城港口最南边的码头有艘船能直达那里。",
    [97899] = "展示出你对专业技能的精通后，前往奥格瑞玛寻找伍特，学习如何制作与你专业相符的露营物品。",
