    [97969] = "展示出你对专业技能的精通后，前往申达尔村寻找因达里·日缝，学习如何制作与你专业相符的露营物品。",
    [97970] = "展示出你对专业技能的精通后，前往申达尔村寻找梅萨娜·冠风，学习如何制作与你专业相符的露营物品。",
    [97971] = "展示出你对专业技能的精通后，前往申达尔村寻找门达拉斯·碎补，学习如何制作与你专业相符的露营物品。",
    [97973] = "展示出你对专业技能的精通后，前往申达尔村寻找塔琳·闪线，学习如何制作与你专业相符的露营物品。",
    [97977] = "收集4个瘤背图腾，然后将它们交给塔琳德拉。",
    [97979] = "施放艾露恩之光与影遁。",
    [97985] = "消灭千针石林的风暴之心，夺取它的心脏。",
    [97986] = "前往东瘟疫之地，与黑木湖西北方那座银色黎明野外营地里的医师交谈。",
    [97987] = "与暴风城花园里的塞拉·维拉威交谈。",
    [98013] = "替古树之林的阿尔巴尔消灭12名雷鳞侍从、8名雷鳞巫师和6名雷鳞战士。",
    [98021] = "向西部荒野哨兵岭的格里安·斯托曼报到。",
    [98024] = "向贫瘠之地十字路口的索克报到。",
    [98025] = "找到并消灭那只名叫贾伊瓦内尔的猫头鹰，然后拔下它的一根羽毛。最后一次有人瞧见这只黑色猫头鹰，还是在亚米萨兰废墟北边的山脚底下。拿着羽毛，去向奥伯丁的哨兵戈琳达·纳希恩报告贾伊瓦内尔的死讯。",
    [98027] = "将新月项链交还给阿斯特兰纳的玛琳。",
    [98028] = "将这颗浑浊的水球，带去交给黑海岸古树之林的安努。",
    [98042] = "从黑海岸主宰之剑的暮光信徒或暮光暴徒身上夺取一颗无双之眼，然后在奥伯丁里找到那个愿意接手这烫手山芋的人。",
