    [99258] = "将枯竭的水晶之心投入不稳定的法力裂隙。带上能说明实验成败的证据，回辛德拉神殿向历史学家比拉克萨斯复命。",
    [99260] = "与瓦拉纳尔的伊拉德林·晚风交谈。",
    [99411] = "莫高雷血蹄村的阿哈布·麦蹄请你喂饱他的宝贝小狗——疯狂的凯雷。 用鲜嫩的陆行鸟肉喂饱凯雷，然后向阿哈布·麦蹄复命。",
    [99435] = "护送雷吉纳德·温德索尔穿过暴风城，务必确保他毫发无损！ 如需再次联系雷吉纳德·温德索尔，请找侍卫洛文。",
    [99670] = "返回宁静摇篮的杰雷曼处。",
}

